import{n as s}from"./shared-CAKwAg2C.js";const r={"LEARN HOW THE INTERNET WORKS":"PELAJARI CARA KERJA INTERNET","NOW LEARNING":"SEDANG DIPELAJARI","OSI LAYER":"LAPISAN OSI","LEARNING PROGRESS":"KEMAJUAN ANDA",COMPLETE:"SELESAI","IN PROGRESS":"BERJALAN","{pct}% complete":"{pct}% selesai","DESIGNED BY":"DIRANCANG OLEH","Dilum Sanjaya on X":"Dilum Sanjaya di X","Layer {n}: {name}":"Lapisan {n}: {name}",Physical:"Fisik","Data Link":"Tautan data",Network:"Jaringan",Transport:"Transport",Session:"Sesi",Presentation:"Presentasi",Application:"Aplikasi","OVERVIEW · {n} STEPS":"IKHTISAR · {n} LANGKAH","STEP {n}/{total} · {title}":"LANGKAH {n}/{total} · {title}","LESSON COMPLETE":"PELAJARAN SELESAI",PROTOCOLS:"PROTOKOL",Protocols:"Protokol",Language:"Bahasa",Theme:"Tema","Light mode":"Mode terang","Dark mode":"Mode gelap","INTERNET PROTOCOLS":"PROTOKOL INTERNET",More:"Lainnya","Close the protocol list":"Tutup daftar protokol","Close (Esc)":"Tutup (Esc)",ALL:"SEMUA",CORE:"INTI",APPLICATION:"APLIKASI",SECURITY:"KEAMANAN",NETWORK:"JARINGAN",SEQUENCE:"URUTAN",View:"Tampilan","Switch view (V)":"Ganti tampilan (V)","Network diagram":"Diagram jaringan","Sequence diagram":"Diagram urutan","STEP {n}":"LANGKAH {n}","PROTOCOL OVERVIEW":"IKHTISAR","STEP DETAILS":"DETAIL LANGKAH","LESSON SUMMARY":"RINGKASAN",OVERVIEW:"AWAL",ACTIVE:"AKTIF","STEP {n} OF {total}":"LANGKAH {n} DARI {total}","PACKET {n} OF {total}":"PAKET {n} DARI {total}","PACKETS {from}–{to} OF {total}":"PAKET {from}–{to} DARI {total}","{n} LOST":"{n} HILANG","1 LOST":"1 HILANG",ENCRYPTED:"TERENKRIPSI","LOST ON THE WAY":"HILANG DI JALAN","PACKET FLOW":"ALIRAN PAKET","Colour key":"Keterangan warna","Playback speed":"Kecepatan putar","Previous step (←)":"Langkah sebelumnya (←)","Previous step":"Langkah sebelumnya","Play / pause (Space)":"Putar / jeda (Spasi)",PLAY:"PUTAR",PAUSE:"JEDA",REPLAY:"ULANGI",STEP:"LANGKAH","One packet at a time":"Satu paket setiap kali",RESET:"ATUR ULANG",Reset:"Atur ulang","Back to the overview (Esc)":"Kembali ke ikhtisar (Esc)","NO.":"NO.",TIME:"WAKTU",SOURCE:"SUMBER",DESTINATION:"TUJUAN",PROTOCOL:"PROTOKOL",INFO:"INFO",SIZE:"UKURAN","No packets on the wire yet.":"Belum ada paket di jaringan.",LOST:"HILANG","Packet inspector":"Pemeriksa paket","Previous packet":"Paket sebelumnya","Previous packet (←)":"Paket sebelumnya (←)","Next packet":"Paket berikutnya","Next packet (→)":"Paket berikutnya (→)",Close:"Tutup","E.G.":"MIS.","an example value: it differs in every real capture":"nilai contoh: berbeda di setiap tangkapan nyata","bytes the lesson can’t show: encrypted, random, or a file’s contents":"byte yang tidak bisa ditampilkan pelajaran: terenkripsi, acak, atau isi sebuah berkas",BYTES:"BYTE","{n} in this frame":"{n} di frame ini","This row stands for {n} TCP segments carrying a {size}-byte message; the first segment is shown":"Baris ini mewakili {n} segmen TCP yang membawa pesan {size} byte; yang ditampilkan adalah segmen pertama","This packet was lost on the way":"Paket ini hilang di jalan",Padding:"Padding","192.168.1.10/24 · 24 H LEASE":"192.168.1.10/24 · SEWA 24 JAM","2 SEGMENTS":"2 SEGMEN","3 SEGMENTS":"3 SEGMEN","3 DATAGRAMS":"3 DATAGRAM","4 DATAGRAMS":"4 DATAGRAM","203.0.113.10 IS NOT LOCAL":"203.0.113.10 BUKAN LOKAL","250 QUEUED":"250 DIANTREKAN",ANSWER:"JAWABAN","APP COVERS THE 20 MS GAP":"APLIKASI MENUTUP CELAH 20 MS","APP DATA":"DATA APLIKASI","ARP REPLY":"BALASAN ARP","ARP REQUEST":"PERMINTAAN ARP","ARRIVED WITH TTL 116":"TIBA DENGAN TTL 116","AUTH FAILURE":"AUTH GAGAL","At QUIT":"Saat QUIT","CACHED · TTL 3600 S":"DI CACHE · TTL 3600 S","CERTIFICATE VALID":"SERTIFIKAT SAH","CHAIN LEADS TO A TRUSTED ROOT":"RANTAI BERUJUNG DI ROOT TEPERCAYA","CHANNEL OPEN":"BUKA KANAL",CONFIRMED:"DIKONFIRMASI","DNS QUERY":"KUERI DNS","DNS REPLY":"BALASAN DNS","DUP ACK":"ACK GANDA","EACH KEY IS ITS OWN PACKET":"TIAP TOMBOL SATU PAKET",ECHO:"ECHO","ECHO REPLY":"BALASAN ECHO","ECHO REQUEST":"PERMINTAAN ECHO",ENTER:"ENTER","FRAME 7 LOST · NOT RESENT":"FRAME 7 HILANG · TIDAK DIKIRIM ULANG","HOP 2 · 198.51.100.1":"HOP 2 · 198.51.100.1","HOST KEY MATCHES KNOWN_HOSTS":"KUNCI HOST COCOK DENGAN KNOWN_HOSTS","IN BOB’S MAILBOX":"DI KOTAK SURAT BOB","IP PACKET":"PAKET IP",MESSAGE:"PESAN","MESSAGE 1 DELETED":"PESAN 1 DIHAPUS","NEW MAIL ARRIVED":"SURAT BARU TIBA","NO IP ADDRESS YET":"BELUM ADA ALAMAT IP","NOT IN CACHE":"TIDAK ADA DI CACHE","OFFER KEY":"TAWARKAN KUNCI",OUTPUT:"KELUARAN","PASSWORD IN PLAIN TEXT":"KATA SANDI TEKS POLOS",REFERRAL:"RUJUKAN",REPLY:"BALASAN",RESEND:"KIRIM ULANG","SEGMENT 1 LOST":"SEGMEN 1 HILANG","SFTP or FTPS":"SFTP atau FTPS","SFTP, or FTPS (FTP + TLS)":"SFTP, atau FTPS (FTP + TLS)","SHARED SECRET COMPUTED":"RAHASIA BERSAMA DIHITUNG",SIGNED:"DITANDATANGANI","STILL ON SERVER · \\SEEN":"MASIH DI SERVER · \\SEEN",SUCCESS:"BERHASIL","TIME EXCEEDED":"WAKTU HABIS","TIME=34MS TTL=52":"WAKTU=34MS TTL=52",UNREACHABLE:"TAK TERJANGKAU",VERSION:"VERSI","VOICE 1":"SUARA 1","+OK or -ERR":"+OK atau -ERR",".com Server":"Server .com",Authoritative:"Otoritatif","Log In":"Masuk",Key:"Kunci",Why:"Mengapa",End:"Akhir","MACs, in":"MAC, masuk",Internet:"Internet",Router:"Router","Router 192.168.1.1":"Router 192.168.1.1","Router: 192.168.1.1":"Router: 192.168.1.1",Routers:"Router",Hardware:"Perangkat keras",Audio:"Audio",Ping:"Ping",Cookie:"Cookie","Magic cookie":"Magic cookie",Visible:"Terlihat",Tickets:"Tiket","4, 20 bytes":"4, 20 byte","20–60 bytes":"20–60 byte","20–60 bytes (IPv4)":"20–60 byte (IPv4)","8 bytes (TCP: 20+)":"8 byte (TCP: 20+)","32 bytes (Windows)":"32 byte (Windows)","1,460 bytes (MSS)":"1,460 byte (MSS)","78 bytes (seq 1–78)":"78 byte (seq 1–78)","bytes 1461–2920":"byte 1461–2920","text/html, 12.2 KB":"text/html, 12.2 KB","1026 (× 256 = 262,656 bytes)":"1026 (× 256 = 262,656 byte)","501 (× 128 = 64,128 bytes)":"501 (× 128 = 64,128 byte)","X25519MLKEM768 (1,216 bytes), X25519":"X25519MLKEM768 (1,216 byte), X25519","X25519MLKEM768 (1,120 bytes)":"X25519MLKEM768 (1,120 byte)",'"abcdefghijklmnopqrstuvwabcdefghi" (32 bytes)':'"abcdefghijklmnopqrstuvwabcdefghi" (32 byte)','"hello, anyone here" (18 bytes)':'"hello, anyone here" (18 byte)',"32 bits (IPv4), 128 (IPv6)":"32 bit (IPv4), 128 (IPv6)","64 → 52 (12 routers)":"64 → 52 (12 router)","52 (64 − 12 routers)":"52 (64 − 12 router)","1 (Ethernet)":"1 (Ethernet)","report.pdf, 4,000 bytes":"report.pdf, 4,000 byte","1190 bytes (sntrup761 1,158 + X25519 32)":"1190 byte (sntrup761 1,158 + X25519 32)","RTP + audio":"RTP + audio","One packet at a time (S)":"Satu paket setiap kali (S)","KEYBOARD SHORTCUTS":"PINTASAN KEYBOARD","Press {key} any time to see these again.":"Tekan {key} kapan saja untuk melihatnya lagi.","Search protocols":"Cari protokol","Search protocols and steps":"Cari protokol dan langkah","Nothing matches.":"Tidak ada yang cocok.","to move":"untuk berpindah","to open":"untuk membuka","Protocol list":"Daftar protokol","Diagram only":"Diagram saja",Fullscreen:"Layar penuh","Keyboard shortcuts":"Pintasan keyboard",Playback:"Pemutaran","Hide the protocol list (L)":"Sembunyikan daftar protokol (L)","Diagram only (D)":"Diagram saja (D)","Fullscreen (F)":"Layar penuh (F)","Keyboard shortcuts (?)":"Pintasan keyboard (?)","Show the protocol list (L)":"Tampilkan daftar protokol (L)","Show all panels (D)":"Tampilkan semua panel (D)","Exit fullscreen (F)":"Keluar dari layar penuh (F)","Play or pause":"Putar atau jeda","Next step":"Langkah berikutnya","Go to step 1 to 9":"Ke langkah 1 sampai 9","Slower, faster":"Lebih lambat, lebih cepat","Back to the overview":"Kembali ke ikhtisar","Network or sequence view":"Tampilan jaringan atau urutan","Show or hide the protocol list":"Tampilkan atau sembunyikan daftar protokol","Light or dark theme":"Tema terang atau gelap",Find:"Cari","Next or previous protocol":"Protokol berikutnya atau sebelumnya","These shortcuts":"Pintasan ini","Previous or next packet":"Paket sebelumnya atau berikutnya","Close it":"Tutup"},o={"Hypertext Transfer Protocol":"Transfer hiperteks","HTTP Secure":"HTTP aman","Transmission Control Protocol":"Protokol kontrol transmisi","User Datagram Protocol":"Protokol datagram pengguna","Internet Protocol":"Protokol internet","Domain Name System":"Sistem nama domain","Dynamic Host Configuration":"Konfigurasi host dinamis","Internet Control Message":"Pesan kontrol internet","Simple Mail Transfer Protocol":"Transfer surat sederhana","Post Office Protocol v3":"Protokol kantor pos v3","Internet Message Access":"Akses pesan internet","File Transfer Protocol":"Transfer berkas","Secure Shell":"Shell aman","Transport Layer Security":"Keamanan lapisan transport",Internet:"Internet",Client:"Klien",Router:"Router","DNS Resolver":"Resolver DNS","Web Server":"Server web","Root Server":"Server root",".com TLD Server":"Server TLD .com","Authoritative Server":"Server otoritatif","Mail Server":"Server surel","Web Communication":"Komunikasi web",Request:"Permintaan",Response:"Respons","Data ACKs not shown":"ACK data tidak ditampilkan","HTTP is the protocol of the web: a client asks for a resource, such as an HTML page, and the server answers with a status code, headers and usually a body. Every exchange is one request and one response, written as readable text in HTTP/1.1.":"HTTP adalah protokol web: klien meminta sebuah sumber daya, misalnya halaman HTML, dan server menjawab dengan kode status, header, dan biasanya sebuah body. Setiap pertukaran terdiri dari satu permintaan dan satu respons, yang di HTTP/1.1 ditulis sebagai teks yang bisa dibaca.",Layer:"Lapisan","Application (Layer 7)":"Aplikasi (lapisan 7)","Default Port":"Port bawaan",Transport:"Transport","Data Format":"Format data","Text (headers + optional body)":"Teks (header + body opsional)","Common Methods":"Metode umum","Defined In":"Didefinisikan di","Page delivered":"Halaman terkirim","One request, one response":"Satu permintaan, satu respons","In under a tenth of a second the laptop looked up an address, opened a TCP connection and exchanged one HTTP request and response, all of it readable by anyone on the path. Press REPLAY to watch it again.":"Dalam kurang dari sepersepuluh detik, laptop mencari sebuah alamat, membuka koneksi TCP, dan bertukar satu permintaan dan respons HTTP, semuanya bisa dibaca siapa pun di sepanjang jalur. Tekan ULANGI untuk menontonnya lagi.","Round trips":"Perjalanan pulang-pergi","Total time":"Total waktu","Page size":"Ukuran halaman","Sent as 9 TCP segments":"Dikirim dalam 9 segmen TCP","Client Request":"Permintaan klien","Browser prepares the request":"Browser menyiapkan permintaan","You open http://www.example.com. The browser will send a GET request, but packets travel to IP addresses, not names, so first it needs the server’s address. (Browsers now try https:// first; this is the plain version.)":"Anda membuka http://www.example.com. Browser akan mengirim permintaan GET, tetapi paket dikirim ke alamat IP, bukan ke nama, jadi browser terlebih dulu butuh alamat server. (Browser kini mencoba https:// lebih dulu; ini versi tanpa enkripsi.)",Method:"Metode","Next hop":"Hop berikutnya","Router 192.168.1.1":"Router 192.168.1.1","DNS Resolution":"Resolusi DNS","Finds the server’s IP address":"Menemukan alamat IP server","The laptop asks the DNS server it was given by DHCP, 8.8.8.8, for the address of www.example.com. The query goes over UDP port 53 and the answer is an A record with the IPv4 address. (On a network with IPv6 it would also ask for an AAAA record.)":"Laptop menanyakan alamat www.example.com kepada server DNS yang diberikan DHCP, yaitu 8.8.8.8. Kueri lewat port UDP 53 dan jawabannya berupa record A berisi alamat IPv4. (Di jaringan dengan IPv6, laptop juga akan meminta record AAAA.)",Resolver:"Resolver","8.8.8.8 (had it cached)":"8.8.8.8 (sudah ada di cache)","UDP, port 53":"UDP, port 53",Answer:"Jawaban","TCP Connection":"Koneksi TCP","Establishes a reliable link":"Membangun tautan yang andal","HTTP runs on top of TCP. Before any page data moves, the laptop and the server open a connection to port 80 with a three-way handshake: SYN, SYN-ACK, ACK.":"HTTP berjalan di atas TCP. Sebelum data halaman apa pun bergerak, laptop dan server membuka koneksi ke port 80 dengan three-way handshake: SYN, SYN-ACK, ACK.","Server port":"Port server","Client port":"Port klien",Handshake:"Handshake","HTTP Exchange":"Pertukaran HTTP","Request and response messages":"Pesan permintaan dan respons","The browser sends a GET request with a Host header. The server answers 200 OK with the HTML in the body: 12.2 KB, too big for one packet, so TCP splits it into 9 segments of up to 1460 bytes (drawn here as one).":"Browser mengirim permintaan GET dengan header Host. Server menjawab 200 OK dengan HTML di body: 12.2 KB, terlalu besar untuk satu paket, jadi TCP memecahnya menjadi 9 segmen berukuran paling banyak 1460 byte (di sini digambar sebagai satu).",Status:"Status",Body:"Body","Sent as":"Dikirim sebagai","12.2 KB in 9 segments":"12.2 KB dalam 9 segmen","Page Rendering":"Merender halaman","Browser displays the content":"Browser menampilkan isinya","The browser parses the HTML and paints the page. Linked CSS, images and scripts would each start more requests just like this one, reusing the open connection where they can.":"Browser mengurai HTML dan menggambar halaman. Setiap CSS, gambar, dan skrip yang ditautkan akan memulai permintaan lain seperti ini, dan memakai ulang koneksi yang terbuka bila bisa.",Document:"Dokumen",Connection:"Koneksi","Kept open for reuse":"Tetap terbuka untuk dipakai ulang","Seen on the laptop’s home network":"Terlihat di jaringan rumah laptop",Destination:"Tujuan","The router: anything beyond the home network goes to it first.":"Router: semua yang keluar dari jaringan rumah lewat router lebih dulu.",Source:"Sumber","The laptop’s network card.":"Kartu jaringan laptop.",Type:"Tipe","What the frame carries.":"Apa yang dibawa frame ini.","Version, header length":"Versi, panjang header","IPv4, with no options.":"IPv4, tanpa opsi.","Priority and congestion marks; 0 means ordinary traffic.":"Tanda prioritas dan kemacetan; 0 berarti lalu lintas biasa.","Total length":"Panjang total","This header and everything inside it.":"Header ini dan semua isinya.",Identification:"Identifikasi","Lets the receiver reassemble the pieces if the packet gets split.":"Memungkinkan penerima menyusun ulang potongan jika paket dipecah.",Flags:"Flag",none:"tidak ada","Routers may split it if a link is too small.":"Router boleh memecahnya jika sebuah tautan terlalu kecil.","Time to live":"Time to live","Windows starts at 128.":"Windows mulai dari 128.",Protocol:"Protokol","Header checksum":"Checksum header","Covers this header only; every router recomputes it after lowering the TTL.":"Hanya mencakup header ini; setiap router menghitungnya ulang setelah menurunkan TTL.","Source port":"Port sumber","Destination port":"Port tujuan",Length:"Panjang","UDP header and data. That is all of UDP: no numbering, no acknowledgements.":"Header UDP dan data. Itulah seluruh UDP: tanpa penomoran, tanpa pengakuan.",Checksum:"Checksum","Covers the header, the data and the IP addresses.":"Mencakup header, data, dan alamat IP.","Transaction ID":"ID transaksi","Picked at random; the answer must carry the same one.":"Dipilih acak; jawabannya harus membawa ID yang sama.","0x0100: query, RD (recursion desired)":"0x0100: kueri, RD (rekursi diinginkan)",Questions:"Pertanyaan",Answers:"Jawaban","Authority records":"Record otoritas","Additional records":"Record tambahan",Question:"Pertanyaan","www.example.com, type A, class IN":"www.example.com, tipe A, kelas IN","The laptop.":"Laptop.","The router’s side facing the home network.":"Sisi router yang menghadap jaringan rumah.","Started at 128; 10 routers on the way each took 1.":"Mulai dari 128; masing-masing dari 10 router di jalan mengurangi 1.","0x8180: response, RD (recursion desired), RA (recursion available)":"0x8180: respons, RD (rekursi diinginkan), RA (rekursi tersedia)","DF (don’t fragment)":"DF (jangan fragmentasi)","Routers must not split it; if it’s too big they report back instead.":"Router tidak boleh memecahnya; jika terlalu besar, router melapor balik.","Picked by the laptop’s system for this connection.":"Dipilih sistem laptop untuk koneksi ini.","Sequence number":"Nomor urut","This side’s starting number. Shown as 0; the real one is random.":"Nomor awal sisi ini. Ditampilkan sebagai 0; yang asli acak.","Real sequence number":"Nomor urut asli",Acknowledgment:"Pengakuan","0 (not used yet)":"0 (belum dipakai)","A first SYN has nothing to acknowledge.":"SYN pertama belum punya apa pun untuk diakui.","Header length":"Panjang header","20 bytes, plus 12 of options.":"20 byte, ditambah 12 byte opsi.",Window:"Jendela","How much more data this side can take right now.":"Berapa banyak lagi data yang bisa diterima sisi ini sekarang.","Covers the header, the data and the IP addresses, so damage is caught.":"Mencakup header, data, dan alamat IP, sehingga kerusakan ketahuan.","Urgent pointer":"Urgent pointer",Options:"Opsi","Maximum segment size":"Ukuran segmen maksimum","The most data this side wants in one segment.":"Data terbanyak yang diinginkan sisi ini dalam satu segmen.","Spacing, so the next option lines up.":"Pengisi, agar opsi berikutnya sejajar.","Window scale":"Skala jendela","Window values are multiplied by this, so windows can be larger than 64 KB.":"Nilai jendela dikalikan dengan ini, sehingga jendela bisa lebih dari 64 KB.","SACK permitted":"SACK diizinkan",yes:"ya","This side understands selective acknowledgements.":"Sisi ini memahami pengakuan selektif.","Started at 64; 12 routers on the way each took 1.":"Mulai dari 64; masing-masing dari 12 router di jalan mengurangi 1.","The next byte this side expects: everything before it has arrived.":"Byte berikutnya yang ditunggu sisi ini: semua sebelumnya sudah tiba.","Position of this segment’s first byte, counted from this side’s SYN.":"Posisi byte pertama segmen ini, dihitung dari SYN sisi ini.",Padding:"Padding","Ethernet frames are at least 60 bytes (64 with the checksum the card adds), so short ones are padded.":"Frame Ethernet paling sedikit 60 byte (64 dengan checksum yang ditambahkan kartu), jadi frame yang pendek diberi padding.",Text:"Teks","covers bytes not shown here":"mencakup byte yang tidak ditampilkan di sini","12,500 bytes: the HTML page":"12,500 byte: halaman HTML","The page itself; its contents are not part of the lesson.":"Halaman itu sendiri; isinya bukan bagian dari pelajaran.","Secure Web":"Web aman","TLS handshake":"Handshake TLS","HTTP request":"Permintaan HTTP","HTTP response":"Respons HTTP","HTTPS is HTTP sent through an encrypted TLS connection. TLS proves the server is who it claims to be with a certificate, agrees on fresh encryption keys, and then protects every request and response from being read or changed on the way.":"HTTPS adalah HTTP yang dikirim melalui koneksi TLS terenkripsi. TLS membuktikan dengan sertifikat bahwa server memang yang diakuinya, menyepakati kunci enkripsi baru, lalu melindungi setiap permintaan dan respons agar tidak dibaca atau diubah di jalan.","Application (HTTP over TLS)":"Aplikasi (HTTP di atas TLS)",Security:"Keamanan","TLS 1.3 (1.2 still common)":"TLS 1.3 (1.2 masih umum)",Proves:"Membuktikan","Server identity (certificate)":"Identitas server (sertifikat)","Secure page delivered":"Halaman aman terkirim","Encrypted, except the lookup":"Terenkripsi, kecuali pencarian DNS","The browser looked up the address in plain DNS, opened a TCP connection, checked the server’s certificate and agreed on keys in one round trip. Every HTTP byte after that travelled encrypted. Press REPLAY to watch it again.":"Browser mencari alamat lewat DNS tanpa enkripsi, membuka koneksi TCP, memeriksa sertifikat server, dan menyepakati kunci dalam satu perjalanan pulang-pergi. Setiap byte HTTP sesudahnya berjalan terenkripsi. Tekan ULANGI untuk menontonnya lagi.",Cipher:"Cipher","Still visible":"Masih terlihat","IPs, server name, sizes":"IP, nama server, ukuran","Secure Request":"Permintaan aman","Browser asks for https://":"Browser meminta https://","You type https://www.example.com. The “s” tells the browser to protect the connection with TLS, on port 443 by default. Before it can connect at all, it still has to find the server’s IP address.":"Anda mengetik https://www.example.com. Huruf “s” memberi tahu browser untuk melindungi koneksi dengan TLS, secara bawaan di port 443. Sebelum bisa terhubung, browser tetap harus menemukan alamat IP server.",Port:"Port","DNS Lookup":"Pencarian DNS","Same lookup as HTTP, not encrypted":"Pencarian yang sama seperti HTTP, tanpa enkripsi","The lookup is exactly the same as for plain HTTP: a query to 8.8.8.8 over UDP port 53. It is not encrypted, so anyone on the path can see which name you asked for, unless the browser uses DNS over HTTPS.":"Pencariannya persis sama dengan HTTP biasa: kueri ke 8.8.8.8 lewat port UDP 53. Kueri ini tidak terenkripsi, jadi siapa pun di jalur bisa melihat nama yang Anda tanyakan, kecuali browser memakai DNS over HTTPS.",Encrypted:"Terenkripsi","No (plain DNS)":"Tidak (DNS biasa)","TCP Handshake":"Handshake TCP","Opens a connection to port 443":"Membuka koneksi ke port 443","TLS rides on TCP, so the same three-way handshake comes first, this time to port 443. Nothing is encrypted yet.":"TLS berjalan di atas TCP, jadi three-way handshake yang sama datang lebih dulu, kali ini ke port 443. Belum ada yang terenkripsi.","TLS Handshake":"Handshake TLS","Agrees on keys, checks the certificate":"Menyepakati kunci, memeriksa sertifikat","The browser offers ciphers and key shares, including a post-quantum hybrid. The server picks it and sends its own share, then its certificate, already encrypted. The browser checks it against authorities it trusts.":"Browser menawarkan cipher dan key share, termasuk hibrida pascakuantum. Server memilihnya dan mengirim key share miliknya, lalu sertifikatnya, yang sudah terenkripsi. Browser memeriksanya terhadap otoritas yang dipercayainya.",Version:"Versi","Key exchange":"Pertukaran kunci","X25519MLKEM768 (hybrid)":"X25519MLKEM768 (hibrida)","Server name":"Nama server","Sent in clear (SNI)":"Dikirim tanpa enkripsi (SNI)","key shares: hybrid + x25519":"key share: hibrida + x25519","cipher: AES_128_GCM_SHA256":"cipher: AES_128_GCM_SHA256","then encrypted: cert, Finished":"lalu terenkripsi: sertifikat, Finished","handshake complete (encrypted)":"handshake selesai (terenkripsi)","Encrypted Exchange":"Pertukaran terenkripsi","HTTP inside TLS records":"HTTP di dalam record TLS","The GET and 200 OK are the same HTTP messages as before, sealed in TLS records that look like random “application data” on the wire. The server also hands over two session tickets, so a later visit can skip part of the handshake.":"GET dan 200 OK adalah pesan HTTP yang sama seperti tadi, disegel dalam record TLS yang di jaringan tampak seperti “data aplikasi” acak. Server juga memberikan dua session ticket, supaya kunjungan berikutnya bisa melewati sebagian handshake.",Inside:"Di dalam","GET / and 200 OK":"GET / dan 200 OK",Tickets:"Tiket","2, for faster reconnects":"2, untuk menyambung ulang lebih cepat","inside: GET / HTTP/1.1":"di dalam: GET / HTTP/1.1","outside: encrypted bytes":"di luar: byte terenkripsi","inside: HTTP/1.1 200 OK":"di dalam: HTTP/1.1 200 OK","outside: 12.9 KB, 9 segments":"di luar: 12.9 KB, 9 segmen","Browser shows the padlock":"Browser menampilkan gembok","The browser decrypts the response, paints the page and shows a padlock: the connection is private and the server proved its identity. The Strict-Transport-Security header tells it to use HTTPS for this site from now on.":"Browser mendekripsi respons, menggambar halaman, dan menampilkan gembok: koneksinya privat dan server telah membuktikan identitasnya. Header Strict-Transport-Security memberi tahu browser untuk memakai HTTPS di situs ini mulai sekarang.",Remembers:"Mengingat","HTTPS only (HSTS), 1 year":"Hanya HTTPS (HSTS), 1 tahun","Server Hello + encrypted handshake, 3 segments":"Server Hello + handshake terenkripsi, 3 segmen","Change Cipher Spec, Finished (encrypted)":"Change Cipher Spec, Finished (terenkripsi)","Application Data (HTTP request)":"Application Data (permintaan HTTP)","New Session Ticket ×2 (encrypted)":"New Session Ticket ×2 (terenkripsi)","Application Data (HTTP response), 9 segments":"Application Data (respons HTTP), 9 segmen",Record:"Record","Content type":"Tipe konten","A Client Hello’s record says TLS 1.0 so old middleboxes let it through; the real versions are offered inside.":"Record dari Client Hello menyebut TLS 1.0 agar middlebox lama meloloskannya; versi yang sebenarnya ditawarkan di dalam.","Handshake type":"Tipe handshake",Contents:"Isi","Everything the browser supports. Browsers vary a few details from one connection to the next.":"Semua yang didukung browser. Browser mengubah sedikit detail dari satu koneksi ke koneksi lain.","Server name (SNI)":"Nama server (SNI)","Versions offered":"Versi yang ditawarkan","Key shares":"Key share","App protocols (ALPN)":"Protokol aplikasi (ALPN)","TLS 1.3 records say 1.2 on the outside, for compatibility.":"Record TLS 1.3 menyebut 1.2 di bagian luar, demi kompatibilitas.","The server’s choices and its half of the hybrid key exchange.":"Pilihan server dan bagiannya dalam pertukaran kunci hibrida.","Cipher suite":"Cipher suite","Key share":"Key share","Has no job in TLS 1.3; sent so middleboxes see a familiar handshake.":"Tidak punya fungsi di TLS 1.3; dikirim agar middlebox melihat handshake yang familier.","Every encrypted record says Application Data on the outside; the real type is inside.":"Setiap record terenkripsi menyebut Application Data di bagian luar; tipe sebenarnya ada di dalam.","Encrypted data":"Data terenkripsi","Ciphertext, ending in a 16-byte tag that shows any change. Only the two ends can read it.":"Ciphertext, diakhiri tag 16 byte yang memperlihatkan setiap perubahan. Hanya kedua ujung yang bisa membacanya.","Encrypted Extensions (ALPN: http/1.1), Certificate (the chain), Certificate Verify (the signature), Finished":"Encrypted Extensions (ALPN: http/1.1), Certificate (rantainya), Certificate Verify (tanda tangannya), Finished","Finished: a check value over the whole handshake":"Finished: nilai pemeriksaan atas seluruh handshake","The HTTP request":"Permintaan HTTP","New Session Ticket: lets a later visit resume":"New Session Ticket: memungkinkan kunjungan berikutnya melanjutkan sesi","The HTTP response, then the 12,500-byte page":"Respons HTTP, lalu halaman 12,500 byte","Reliable Delivery":"Pengiriman andal","Handshake and ACKs":"Handshake dan ACK","Data from laptop":"Data dari laptop","Data from server":"Data dari server","Closing (FIN)":"Penutupan (FIN)","TCP turns the internet’s best-effort packet delivery into a reliable, ordered stream of bytes. It numbers every byte, acknowledges what arrives, resends what goes missing, and paces the sender so neither the other side nor the network is overwhelmed.":"TCP mengubah pengiriman paket internet yang bersifat “best effort” menjadi aliran byte yang andal dan berurutan. TCP menomori setiap byte, mengakui yang tiba, mengirim ulang yang hilang, dan mengatur laju pengirim agar sisi lain maupun jaringan tidak kewalahan.","Transport (Layer 4)":"Transport (lapisan 4)","Three-way handshake":"Three-way handshake",Reliability:"Keandalan","Sequence numbers + ACKs":"Nomor urut + ACK",Recovery:"Pemulihan",Retransmission:"Transmisi ulang",Header:"Header","Connection closed":"Koneksi ditutup","Every byte accounted for":"Setiap byte terhitung","TCP opened a connection, numbered and acknowledged every byte, spotted a gap and resent just the missing segment, then closed both directions cleanly. curl received every byte in order and never saw the loss. Press REPLAY to watch it again.":"TCP membuka koneksi, menomori dan mengakui setiap byte, menemukan celah dan hanya mengirim ulang segmen yang hilang, lalu menutup kedua arah dengan rapi. curl menerima setiap byte secara berurutan dan tidak pernah melihat kehilangan itu. Tekan ULANGI untuk menontonnya lagi.",Segments:"Segmen","14 (1 lost, 1 resent)":"14 (1 hilang, 1 dikirim ulang)","Bytes delivered":"Byte terkirim","78 up, 2,920 down":"78 naik, 2,920 turun","Loss found by":"Kehilangan terdeteksi lewat","Duplicate ACK + SACK":"ACK ganda + SACK","Open Connection":"Membuka koneksi","curl already knows the server’s address. Before any data moves, both sides choose a starting sequence number and confirm it: SYN, SYN-ACK, ACK. The numbers here are relative; real ones start at a random value.":"curl sudah tahu alamat server. Sebelum data apa pun bergerak, kedua sisi memilih nomor urut awal dan mengonfirmasinya: SYN, SYN-ACK, ACK. Nomor di sini relatif; nomor sebenarnya dimulai dari nilai acak.",Server:"Server","203.0.113.10, port 80":"203.0.113.10, port 80","Send Data":"Mengirim data","Every byte is numbered":"Setiap byte dinomori","curl sends its 78-byte HTTP request: bytes 1 to 78. The server’s ACK number, 79, is the next byte it expects, which means everything before it has arrived.":"curl mengirim permintaan HTTP-nya yang berukuran 78 byte: byte 1 sampai 78. Nomor ACK dari server, 79, adalah byte berikutnya yang ditunggunya, artinya semua sebelumnya sudah tiba.",Sent:"Terkirim","79 = next byte expected":"79 = byte berikutnya yang ditunggu","Two Segments Back":"Dua segmen kembali","One of them is lost":"Salah satunya hilang","The server answers with 2,920 bytes: two full segments of 1,460 bytes, the most that fits in one packet here, sent back to back. The first is dropped somewhere on the internet; the second gets through.":"Server menjawab dengan 2,920 byte: dua segmen penuh berukuran 1,460 byte, jumlah terbanyak yang muat dalam satu paket di sini, dikirim berturut-turut. Yang pertama jatuh di suatu tempat di internet; yang kedua sampai.","Segment 1":"Segmen 1","bytes 1–1460 (lost)":"byte 1–1460 (hilang)","Segment 2":"Segmen 2","Segment size":"Ukuran segmen","seq=1 and seq=1461":"seq=1 dan seq=1461","the first is lost":"yang pertama hilang","A Gap Is Noticed":"Celah terdeteksi","Duplicate ACK with SACK":"ACK ganda dengan SACK","Bytes 1461–2920 arrive, but 1–1460 never did. An ACK can only count bytes received in order, so the laptop repeats ACK 1 at once and adds a SACK block saying it already holds 1461–2920.":"Byte 1461–2920 tiba, tetapi 1–1460 tidak pernah sampai. ACK hanya bisa menghitung byte yang diterima berurutan, jadi laptop segera mengulang ACK 1 dan menambahkan blok SACK yang menyatakan bahwa ia sudah punya 1461–2920.","1 (still waiting for byte 1)":"1 (masih menunggu byte 1)","holds bytes 1461–2920":"punya byte 1461–2920","At once, not delayed":"Segera, tanpa ditunda","sack: has 1461–2920":"sack: punya 1461–2920","Resend the Gap":"Mengirim ulang celah","Only the missing bytes":"Hanya byte yang hilang","The SACK tells the server exactly what is missing, so it resends just segment 1, and the laptop acknowledges everything. Had no ACK come back at all, timers would have stepped in: a probe after about two round trips, then a retransmission timeout (at least 200 ms on Linux).":"SACK memberi tahu server persis apa yang hilang, jadi server hanya mengirim ulang segmen 1, dan laptop mengakui semuanya. Kalau sama sekali tidak ada ACK yang kembali, timer yang akan bertindak: lebih dulu probe setelah sekitar dua kali bolak-balik, lalu batas waktu transmisi ulang (minimal 200 ms di Linux).",Resent:"Dikirim ulang","bytes 1–1460 only":"hanya byte 1–1460","Next ACK":"ACK berikutnya","2921 (everything)":"2921 (semuanya)","curl saw":"Yang dilihat curl","Every byte, in order":"Setiap byte, berurutan","just the missing segment":"hanya segmen yang hilang","Close Connection":"Menutup koneksi","Each side says goodbye":"Tiap sisi berpamitan","curl is done, so it closes. Each direction closes on its own: the laptop sends FIN and the server acknowledges it, then the server sends its own FIN and the laptop acknowledges that. The laptop keeps the connection’s details for a while (TIME-WAIT).":"curl sudah selesai, jadi ia menutup koneksi. Setiap arah ditutup sendiri-sendiri: laptop mengirim FIN dan server mengakuinya, lalu server mengirim FIN-nya sendiri dan laptop mengakuinya. Laptop menyimpan detail koneksi untuk sementara (TIME-WAIT).","Closed by":"Ditutup dengan","A FIN from each side":"Satu FIN dari tiap sisi",Order:"Urutan",Then:"Lalu","Laptop waits (TIME-WAIT)":"Laptop menunggu (TIME-WAIT)",Data:"Data","1,460 bytes: the HTTP response, bytes 1–1460":"1,460 byte: respons HTTP, byte 1–1460","1,460 bytes: the HTTP response, bytes 1461–2920":"1,460 byte: respons HTTP, byte 1461–2920","has 1461–2920":"punya 1461–2920","Bytes that arrived after the gap, so only the gap needs resending.":"Byte yang tiba setelah celah, jadi hanya celah itu yang perlu dikirim ulang.","Fast Datagrams":"Datagram cepat","Your voice":"Suara Anda","Their voice":"Suara lawan bicara","Media Server":"Server media","UDP sends data in independent packets called datagrams, with no connection, no acknowledgements and no resends. That keeps it fast and light: right for voice, video, games and DNS, where a late answer is worse than a missing one.":"UDP mengirim data dalam paket-paket independen yang disebut datagram, tanpa koneksi, tanpa konfirmasi, dan tanpa pengiriman ulang. Itu membuatnya cepat dan ringan: cocok untuk suara, video, game, dan DNS, di mana jawaban yang terlambat lebih buruk daripada jawaban yang hilang.",None:"Tidak ada","None (no ACKs, no resends)":"Tidak ada (tanpa ACK, tanpa pengiriman ulang)",Ordering:"Urutan","Not guaranteed":"Tidak dijamin","Call keeps flowing":"Panggilan terus berjalan","Fast, simple, no guarantees":"Cepat, sederhana, tanpa jaminan","Audio started with the very first packet, every datagram travelled on its own, and the one that was lost was simply gone: UDP never noticed. The app covered the gap and the call carried on. Press REPLAY to watch it again.":"Audio dimulai sejak paket pertama, setiap datagram berjalan sendiri-sendiri, dan yang hilang ya hilang begitu saja: UDP tidak pernah menyadarinya. Aplikasi menutupi celahnya dan panggilan terus berlanjut. Tekan ULANGI untuk menontonnya lagi.",Datagrams:"Datagram","11 (1 lost, never resent)":"11 (1 hilang, tidak pernah dikirim ulang)","Setup time":"Waktu penyiapan","0 ms (no handshake)":"0 ms (tanpa handshake)",Shown:"Ditampilkan","The first 0.2 s of a call":"0.2 detik pertama sebuah panggilan","Send Right Away":"Langsung kirim","No handshake, data goes first":"Tanpa handshake, data langsung dikirim","A call app already knows the media server’s address and port from signing in. It doesn’t open a connection: the very first datagram already carries 20 ms of your voice, behind an 8-byte UDP header.":"Aplikasi panggilan sudah tahu alamat dan port server media sejak Anda masuk. Aplikasi tidak membuka koneksi: datagram pertama pun sudah membawa 20 ms suara Anda, di belakang header UDP 8 byte.",Setup:"Penyiapan",Ports:"Port","92 B of audio, no setup":"92 B audio, tanpa penyiapan","A Stream of Datagrams":"Aliran datagram","One every 20 ms, each on its own":"Satu setiap 20 ms, masing-masing sendiri","The app keeps sending a datagram every 20 ms. Each one stands alone, with its own header and no link to the others. UDP doesn’t number them, and nothing comes back to confirm they arrived.":"Aplikasi terus mengirim satu datagram setiap 20 ms. Masing-masing berdiri sendiri, dengan header sendiri dan tanpa kaitan dengan yang lain. UDP tidak menomorinya, dan tidak ada yang kembali untuk memastikan datagram itu sampai.",Rate:"Laju","1 datagram / 20 ms":"1 datagram / 20 ms",Numbering:"Penomoran","None in UDP itself":"Tidak ada di UDP itu sendiri",Confirmation:"Konfirmasi","None (no ACKs)":"Tidak ada (tanpa ACK)","voice frames 2–5":"frame suara 2–5","each with its own 8-byte header":"masing-masing dengan header 8 byte sendiri","Lost on the Way":"Hilang di jalan","Nobody resends it":"Tidak ada yang mengirim ulang","Frame 7 is dropped somewhere on the internet. The media server never asks for it, and UDP never tells the laptop: there are no acknowledgements to miss. The datagrams after it arrive as normal.":"Frame 7 terbuang di suatu tempat di internet. Server media tidak pernah memintanya, dan UDP tidak pernah memberi tahu laptop: tidak ada konfirmasi yang bisa terasa hilang. Datagram setelahnya tiba seperti biasa.",Lost:"Hilang","Voice frame 7":"Frame suara 7","Never (no ACKs)":"Tidak pernah (tanpa ACK)",Missing:"Terlewat","20 ms of audio":"20 ms audio","voice frames 6–8":"frame suara 6–8","frame 7 is lost":"frame 7 hilang","Replies Come Back":"Balasan kembali","The other voice comes back":"Suara lawan bicara kembali","The other person’s voice arrives the same way, as separate datagrams sent to port 50000. They get back in because your router remembered the outgoing port when it translated your address (NAT).":"Suara lawan bicara tiba dengan cara yang sama, sebagai datagram-datagram terpisah yang dikirim ke port 50000. Datagram itu bisa masuk karena router Anda mengingat port keluar saat menerjemahkan alamat Anda (NAT).",Direction:"Arah","Independent of ours":"Tidak bergantung pada arah kita","Through NAT":"Melewati NAT","Router remembers the port":"Router mengingat port-nya","the other person’s voice":"suara lawan bicara","sent to port 50000":"dikirim ke port 50000","The App Decides":"Aplikasi yang menentukan","Reliability is up to the app":"Keandalan diserahkan ke aplikasi","The call app numbers its own frames (RTP does this), so it sees that frame 7 is missing and smooths over the 20 ms gap instead of waiting. Waiting for a resend would make the whole call lag.":"Aplikasi panggilan menomori frame-nya sendiri (itulah tugas RTP), jadi ia melihat bahwa frame 7 hilang dan menyamarkan celah 20 ms itu alih-alih menunggu. Menunggu pengiriman ulang akan membuat seluruh panggilan tersendat.","App’s job (e.g. RTP)":"Tugas aplikasi (mis. RTP)",Loss:"Kehilangan","Hidden by the app":"Disembunyikan oleh aplikasi","Also on UDP":"Juga lewat UDP","DNS, games, QUIC":"DNS, game, QUIC","Version etc.":"Versi dll.","2, no padding, no extension, no CSRCs":"2, tanpa padding, tanpa ekstensi, tanpa CSRC","Marker, payload type":"Marker, jenis payload","1, 111 (Opus, agreed when the call was set up)":"1, 111 (Opus, disepakati saat panggilan disiapkan)","Counts up by one per packet, so the app can spot a missing or late one.":"Bertambah satu per paket, agar aplikasi bisa mengenali paket yang hilang atau terlambat.",Timestamp:"Stempel waktu","Audio clock at 48,000 per second: +960 per 20 ms frame.":"Jam audio 48,000 per detik: +960 per frame 20 ms.","Identifies this audio stream.":"Mengidentifikasi aliran audio ini.",Audio:"Audio","80 bytes of Opus audio (20 ms)":"80 byte audio Opus (20 ms)","0, 111 (Opus, agreed when the call was set up)":"0, 111 (Opus, disepakati saat panggilan disiapkan)","Addressing & Routing":"Pengalamatan & perutean","Outgoing packet":"Paket keluar",Reply:"Balasan","IP gives every device an address and moves packets from network to network. Each router looks only at the destination address to choose the next hop. IP is best effort: it doesn’t promise delivery or order. TCP adds those on top.":"IP memberi setiap perangkat sebuah alamat dan memindahkan paket dari jaringan ke jaringan. Setiap router hanya melihat alamat tujuan untuk memilih hop berikutnya. IP bersifat best effort: tidak menjanjikan pengiriman maupun urutan. TCP menambahkan keduanya di atasnya.","Network (Layer 3)":"Jaringan (lapisan 3)",Address:"Alamat","Lowered by 1 at each router":"Dikurangi 1 di setiap router",Delivery:"Pengiriman","Best effort":"Best effort","There and back":"Pergi dan pulang","Twelve routers each way":"Dua belas router di setiap arah","The laptop sent the packet to its router, which swapped in its public address. Twelve routers in all passed it along by destination address alone, and the reply found its way back the same way. Press REPLAY to watch it again.":"Laptop mengirim paket ke router-nya, yang memasang alamat publiknya sendiri. Total dua belas router meneruskannya hanya berdasarkan alamat tujuan, dan balasannya menemukan jalan pulang dengan cara yang sama. Tekan ULANGI untuk menontonnya lagi.",Routers:"Router","12 each way (1 home + 11)":"12 per arah (1 di rumah + 11)","TTL at server":"TTL di server","116 (sent with 128)":"116 (dikirim dengan 128)","Rewritten by NAT":"Ditulis ulang oleh NAT","Source out, destination back":"Sumber saat pergi, tujuan saat kembali","IPv4 (IPv6 works alike)":"IPv4 (IPv6 bekerja serupa)","Local or Not?":"Lokal atau bukan?","Compare the address with the subnet":"Bandingkan alamat dengan subnet","The laptop is 192.168.1.10 with a /24 mask, so its own network is 192.168.1.0 to 192.168.1.255. The server, 203.0.113.10, is outside that range, so the packet has to go to the default gateway: the home router.":"Laptop beralamat 192.168.1.10 dengan mask /24, jadi jaringannya sendiri mencakup 192.168.1.0 sampai 192.168.1.255. Server, 203.0.113.10, berada di luar rentang itu, jadi paket harus dikirim ke default gateway: router rumah.",Laptop:"Laptop","Local range":"Rentang lokal",Gateway:"Gateway","Find the Router":"Temukan router","ARP turns an IP into a MAC":"ARP mengubah IP menjadi MAC","On the local network, frames are delivered by MAC address. If the router’s MAC isn’t in the laptop’s ARP cache, it broadcasts “who has 192.168.1.1?” and the router answers with its MAC address.":"Di jaringan lokal, frame dikirim berdasarkan alamat MAC. Jika MAC router belum ada di cache ARP laptop, laptop menyiarkan “siapa yang punya 192.168.1.1?” dan router menjawab dengan alamat MAC-nya.",Asks:"Bertanya","Who has 192.168.1.1?":"Siapa yang punya 192.168.1.1?","Sent to":"Dikirim ke","Everyone (broadcast)":"Semua (broadcast)",Learns:"Mengetahui","Router’s MAC address":"Alamat MAC router","who has 192.168.1.1?":"siapa yang punya 192.168.1.1?","tell 192.168.1.10":"beri tahu 192.168.1.10","Send the Packet":"Kirim paketnya","Addresses, TTL and protocol":"Alamat, TTL, dan protokol","The IP header carries the source and destination addresses, a TTL and the protocol inside. Here it holds a TCP SYN to port 443. Windows starts the TTL at 128 (Linux and macOS use 64).":"Header IP membawa alamat sumber dan tujuan, sebuah TTL, dan protokol di dalamnya. Di sini isinya TCP SYN ke port 443. Windows memulai TTL dari 128 (Linux dan macOS memakai 64).","From → to":"Dari → ke","TTL 128 · protocol TCP":"TTL 128 · protokol TCP","NAT, Then Hop by Hop":"NAT, lalu hop demi hop","The router rewrites and forwards":"Router menulis ulang dan meneruskan","The router swaps the private source for its public address 198.51.100.7 (and here port 52344 for 40112), notes the mapping, and lowers the TTL to 127. Then 11 routers on the internet each choose the next hop by destination and lower the TTL again.":"Router mengganti sumber privat dengan alamat publiknya 198.51.100.7 (dan di sini port 52344 dengan 40112), mencatat pemetaannya, lalu menurunkan TTL menjadi 127. Kemudian 11 router di internet masing-masing memilih hop berikutnya berdasarkan tujuan dan menurunkan TTL lagi.","New source":"Sumber baru","Leaves home":"Keluar dari rumah","At the server":"Di server","TTL 116 (11 more hops)":"TTL 116 (11 hop lagi)","TTL 127 · after NAT":"TTL 127 · setelah NAT","The Reply Comes Back":"Balasannya kembali","NAT translates it for the laptop":"NAT menerjemahkannya untuk laptop","The server answers the address it saw, 198.51.100.7:40112. The router looks that up in its NAT table, rewrites the destination back to 192.168.1.10:52344 and passes it on. The reply started at TTL 64 and arrives with 52.":"Server menjawab ke alamat yang dilihatnya, 198.51.100.7:40112. Router mencarinya di tabel NAT, menulis ulang tujuannya kembali menjadi 192.168.1.10:52344, lalu meneruskannya. Balasan berangkat dengan TTL 64 dan tiba dengan 52.","Delivered to":"Diantar ke","TTL 52 · after NAT":"TTL 52 · setelah NAT","TTL 127 · 40112 → 443 [SYN] (after NAT)":"TTL 127 · 40112 → 443 [SYN] (setelah NAT)","TTL 52 · 443 → 52344 [SYN, ACK] (after NAT)":"TTL 52 · 443 → 52344 [SYN, ACK] (setelah NAT)","ARP request · 28 bytes":"Permintaan ARP · 28 byte","Broadcast: every device on the network receives it.":"Broadcast: setiap perangkat di jaringan menerimanya.","The sender’s network card.":"Kartu jaringan pengirim.","Hardware type":"Jenis perangkat keras","Protocol type":"Jenis protokol","Address sizes":"Ukuran alamat",Operation:"Operasi","1 (request: who has …?)":"1 (permintaan: siapa yang punya …?)","Sender MAC":"MAC pengirim","Sender IP":"IP pengirim","Target MAC":"MAC target","All zeros: this is what the request wants to find out.":"Semuanya nol: inilah yang ingin diketahui permintaan ini.","Target IP":"IP target","ARP reply · 28 bytes":"Balasan ARP · 28 byte","Straight back to the device that asked.":"Langsung kembali ke perangkat yang bertanya.","2 (reply: … is at …)":"2 (balasan: … ada di …)","Seen as it leaves the router’s internet side":"Terlihat saat keluar dari sisi internet router","The internet provider’s router, the next hop.":"Router penyedia internet, hop berikutnya.","The router’s internet-facing port.":"Port router yang menghadap internet.","As sent: this system starts at 64.":"Seperti saat dikirim: sistem ini mulai dari 64.","The router’s NAT swapped in its own port for the laptop’s.":"NAT router mengganti port laptop dengan port miliknya sendiri.","The sender’s next router; each hop puts the packet in a new frame.":"Router berikutnya milik pengirim; di setiap hop paket dimasukkan ke frame baru.","Name Resolution":"Resolusi nama",Query:"Kueri",Referral:"Rujukan","DNSSEC not requested here":"DNSSEC tidak diminta di sini","DNS turns names like www.example.com into the IP addresses computers use to reach each other. No single server knows every name: the system is a hierarchy of servers, and answers are cached along the way so most lookups never have to go far.":"DNS mengubah nama seperti www.example.com menjadi alamat IP yang dipakai komputer untuk saling menjangkau. Tidak ada satu server pun yang tahu semua nama: sistemnya adalah hierarki server, dan jawaban disimpan di cache sepanjang jalan sehingga sebagian besar pencarian tidak perlu pergi jauh.","53, UDP (TCP if large)":"53, UDP (TCP jika besar)",Turns:"Mengubah","Names into IP addresses":"Nama menjadi alamat IP",Hierarchy:"Hierarki","Root → TLD → authoritative":"Root → TLD → otoritatif",Caching:"Caching","For each record’s TTL":"Selama TTL setiap record","Name resolved":"Nama berhasil diterjemahkan","And remembered for an hour":"Dan diingat selama satu jam","Starting from an empty cache, the resolver walked from the root to .com to example.com’s own server, then answered the laptop. Until the TTL runs out, the next lookup for this name is answered straight from a cache. Press REPLAY to watch it again.":"Berawal dari cache kosong, resolver berjalan dari root ke .com lalu ke server milik example.com sendiri, kemudian menjawab laptop. Sampai TTL habis, pencarian berikutnya untuk nama ini langsung dijawab dari cache. Tekan ULANGI untuk menontonnya lagi.",Queries:"Kueri","4 (laptop 1, resolver 3)":"4 (laptop 1, resolver 3)","Cached for":"Disimpan di cache selama","Ask the Resolver":"Tanya resolver","The laptop hands the question off":"Laptop menyerahkan pertanyaannya","The browser needs the IP address of www.example.com and neither it nor Windows has one cached. The laptop sends one question to the recursive resolver it was given, 8.8.8.8, and asks it to do the whole lookup (recursion desired).":"Browser membutuhkan alamat IP www.example.com, dan baik browser maupun Windows tidak menyimpannya di cache. Laptop mengirim satu pertanyaan ke resolver rekursif yang diberikan kepadanya, 8.8.8.8, dan memintanya melakukan seluruh pencarian (rekursi diminta).","www.example.com, type A":"www.example.com, tipe A",Asked:"Ditanyakan ke","8.8.8.8 (recursive)":"8.8.8.8 (rekursif)","RD (recursion desired)":"RD (rekursi diminta)","flags: RD":"flag: RD","Points the way to .com":"Menunjukkan jalan ke .com","The resolver’s cache is empty (it has just started), so it begins at the top. A root server doesn’t know the address, but it knows which servers handle .com and replies with a referral. Many resolvers send it only “com”, not the full name.":"Cache resolver kosong (baru saja dinyalakan), jadi ia mulai dari puncak. Server root tidak tahu alamatnya, tetapi tahu server mana yang menangani .com dan membalas dengan rujukan. Banyak resolver hanya mengirim “com” kepadanya, bukan nama lengkapnya.","Root servers":"Server root","13 names, 1,000+ anycast sites":"13 nama, lebih dari 1,000 lokasi anycast","Referral (13 .com servers)":"Rujukan (13 server .com)","no answer: ask .com":"tanpa jawaban: tanyakan ke .com","Points the way to example.com":"Menunjukkan jalan ke example.com","The resolver asks one of the .com servers. They don’t store addresses for every site either, but they know which name servers each .com domain uses, so this reply is another referral, with those servers’ addresses (glue) attached.":"Resolver bertanya ke salah satu server .com. Server-server itu juga tidak menyimpan alamat setiap situs, tetapi tahu name server mana yang dipakai setiap domain .com, jadi balasan ini adalah rujukan lain, dengan alamat server-server itu (glue) terlampir.",Knows:"Mengetahui","Name servers of .com domains":"Name server domain .com","Referral + glue addresses":"Rujukan + alamat glue","no answer: ask example.com":"tanpa jawaban: tanyakan ke example.com","Gives the actual answer":"Memberi jawaban sebenarnya","Finally the resolver asks example.com’s own name server, which holds the domain’s records. It answers with the A record and marks the reply authoritative. The domain owner sets how long it may be cached: here, 3600 seconds.":"Akhirnya resolver bertanya ke name server milik example.com sendiri, yang menyimpan record domain tersebut. Server itu menjawab dengan record A dan menandai balasannya sebagai otoritatif. Pemilik domain menentukan berapa lama jawaban boleh disimpan di cache: di sini, 3600 detik.","AA (authoritative), TTL 3600":"AA (otoritatif), TTL 3600","TTL 3600 · flag AA":"TTL 3600 · flag AA","Answer & Cache":"Jawaban & cache","The laptop gets its address":"Laptop mendapatkan alamatnya","The resolver sends the answer back to the laptop and keeps a copy. For the next hour it can answer this name straight away, which is why the lookup in the HTTP lesson took only 24 ms. The laptop caches it too.":"Resolver mengirim jawabannya kembali ke laptop dan menyimpan salinannya. Selama satu jam berikutnya, resolver bisa langsung menjawab nama ini; itulah sebabnya pencarian di pelajaran HTTP hanya butuh 24 ms. Laptop juga menyimpannya di cache.","RD, RA (recursion available)":"RD, RA (rekursi tersedia)","Cached by":"Disimpan di cache oleh","Resolver and laptop":"Resolver dan laptop","flags: RD RA":"flag: RD RA","Referral: com. NS ×13 (with glue)":"Rujukan: com. NS ×13 (dengan glue)","Referral: example.com. NS ×2 (with glue)":"Rujukan: example.com. NS ×2 (dengan glue)","Response A 203.0.113.10 (authoritative)":"Respons A 203.0.113.10 (otoritatif)","As sent: this system starts at 128.":"Seperti saat dikirim: sistem ini mulai dari 128.","0x0000: query":"0x0000: kueri","UDP size 1232, DNSSEC OK = 0":"Ukuran UDP 1232, DNSSEC OK = 0","Says how big a UDP answer can be. DNSSEC signatures are not asked for here, to keep the lesson short; a validating resolver like 8.8.8.8 does ask for them.":"Menyatakan seberapa besar jawaban UDP boleh dikirim. Tanda tangan DNSSEC tidak diminta di sini agar pelajarannya tetap singkat; resolver yang memvalidasi seperti 8.8.8.8 memintanya.","0x8000: response":"0x8000: respons",Authority:"Otoritas",Additional:"Tambahan","0x8400: response, AA (authoritative)":"0x8400: respons, AA (otoritatif)","Getting an Address":"Mendapatkan alamat","From the laptop":"Dari laptop","From the DHCP server":"Dari server DHCP","Dynamic Host Configuration Protocol":"Protokol konfigurasi host dinamis","DHCP hands a device everything it needs to use a network: an IP address, the subnet mask, the router to send traffic through and the DNS servers to ask. Addresses are leased for a set time and renewed while the device stays on the network.":"DHCP memberi perangkat semua yang dibutuhkannya untuk memakai jaringan: alamat IP, subnet mask, router untuk mengirim lalu lintas, dan server DNS untuk ditanyai. Alamat dipinjamkan (lease) untuk waktu tertentu dan diperpanjang selama perangkat tetap berada di jaringan.","UDP 67 (server), 68 (client)":"UDP 67 (server), 68 (klien)","Hands out":"Membagikan","IP, mask, gateway, DNS":"IP, mask, gateway, DNS",Exchange:"Pertukaran",Lease:"Lease","Renewed at half its time":"Diperpanjang di separuh waktunya","On the network":"Di jaringan","Leased, and kept up to date":"Mendapat lease, dan selalu diperbarui","Four messages took the laptop from no address to a working configuration, and halfway through the 24-hour lease it renewed it with a direct request to the router. Press REPLAY to watch it again.":"Empat pesan membawa laptop dari tanpa alamat menjadi konfigurasi yang berfungsi, dan di separuh lease 24 jam laptop memperpanjangnya dengan permintaan langsung ke router. Tekan ULANGI untuk menontonnya lagi.",Messages:"Pesan","4 to join, 2 per renewal":"4 untuk bergabung, 2 per perpanjangan","24 h, renewed at 12 h":"24 jam, diperpanjang pada jam ke-12","No Address Yet":"Belum punya alamat","The laptop joins the network":"Laptop bergabung ke jaringan","The laptop has just connected. It has a MAC address built in, but no IP address, no gateway and no DNS server, so it can’t talk to anything beyond its own network yet. It asks for them with DHCP.":"Laptop baru saja terhubung. Laptop punya alamat MAC bawaan, tetapi belum punya alamat IP, gateway, maupun server DNS, jadi belum bisa berbicara dengan apa pun di luar jaringannya sendiri. Laptop memintanya dengan DHCP.","IP address":"Alamat IP","None (uses 0.0.0.0)":"Tidak ada (memakai 0.0.0.0)","MAC address":"Alamat MAC",Needs:"Butuh",Discover:"Discover","Shout to the whole network":"Berseru ke seluruh jaringan","Without an address of its own, the laptop sends from 0.0.0.0 to the broadcast address 255.255.255.255, so every device on the local network receives it. Only DHCP servers answer.":"Tanpa alamat sendiri, laptop mengirim dari 0.0.0.0 ke alamat broadcast 255.255.255.255, sehingga setiap perangkat di jaringan lokal menerimanya. Hanya server DHCP yang menjawab.",From:"Dari","0.0.0.0, UDP port 68":"0.0.0.0, port UDP 68","255.255.255.255, port 67":"255.255.255.255, port 67",Carries:"Membawa","MAC, transaction ID":"MAC, ID transaksi","any DHCP server out there?":"ada server DHCP di sana?",Offer:"Offer","The router proposes an address":"Router menawarkan alamat","The router’s DHCP server picks a free address and offers it with the rest of the settings. The laptop can’t use an IP address yet, so the offer goes straight to its MAC address (some clients ask for a broadcast instead).":"Server DHCP di router memilih alamat yang kosong dan menawarkannya bersama pengaturan lainnya. Laptop belum bisa memakai alamat IP, jadi tawarannya dikirim langsung ke alamat MAC-nya (sebagian klien meminta broadcast sebagai gantinya).",Offered:"Ditawarkan","Gateway, DNS":"Gateway, DNS","offer: 192.168.1.10/24":"tawaran: 192.168.1.10/24","gateway, DNS, lease 24 h":"gateway, DNS, lease 24 jam","Accept, out loud":"Terima, secara terbuka","The laptop asks for the offered address, naming the server it chose. It still broadcasts, so any other DHCP server that made an offer learns it wasn’t picked and can release its address.":"Laptop meminta alamat yang ditawarkan sambil menyebut server yang dipilihnya. Laptop masih memakai broadcast, sehingga server DHCP lain yang sempat menawarkan tahu bahwa ia tidak dipilih dan bisa melepas alamatnya.",Requests:"Meminta","Chosen server":"Server terpilih","I’ll take 192.168.1.10":"Saya ambil 192.168.1.10","from server 192.168.1.1":"dari server 192.168.1.1",Acknowledge:"Acknowledge","The address is the laptop’s":"Alamat itu milik laptop","The server confirms, and the laptop configures its address, mask, gateway and DNS server. Many systems first check with ARP that no other device is already using the address.":"Server mengonfirmasi, lalu laptop mengatur alamat, mask, gateway, dan server DNS-nya. Banyak sistem lebih dulu memeriksa dengan ARP bahwa belum ada perangkat lain yang memakai alamat itu.","DNS server":"Server DNS","192.168.1.10 is yours":"192.168.1.10 milik Anda","for 24 hours":"selama 24 jam",Renew:"Perpanjang","Halfway through the lease":"Di separuh masa lease","Twelve hours later, half the lease has passed. The laptop now has an address, so it asks the router directly to extend the lease, and the router resets it to 24 hours. If the router didn’t answer, it would broadcast at 87.5%.":"Dua belas jam kemudian, separuh masa lease sudah lewat. Laptop sekarang punya alamat, jadi ia meminta router secara langsung untuk memperpanjang lease, dan router mengaturnya kembali menjadi 24 jam. Jika router tidak menjawab, laptop akan memakai broadcast pada 87.5%.",When:"Kapan","50% of lease (T1 = 12 h)":"50% lease (T1 = 12 jam)","The router (unicast)":"Router (unicast)","If unanswered":"Jika tak dijawab","Broadcast at 87.5% (T2)":"Broadcast pada 87.5% (T2)","renew 192.168.1.10":"perpanjang 192.168.1.10","sent straight to 192.168.1.1":"dikirim langsung ke 192.168.1.1","lease renewed":"lease diperpanjang","another 24 hours":"24 jam lagi",Message:"Pesan","1 (request, from a client)":"1 (permintaan, dari klien)",Hardware:"Perangkat keras","Ethernet, 6-byte addresses":"Ethernet, alamat 6 byte",Hops:"Hop","Chosen by the client; every reply repeats it.":"Dipilih oleh klien; setiap balasan mengulanginya.",Seconds:"Detik","0x0000 (unicast replies are fine)":"0x0000 (balasan unicast boleh)","Broadcast flag off: the server may send straight to the client’s MAC address.":"Flag broadcast mati: server boleh mengirim langsung ke alamat MAC klien.","Client address":"Alamat klien","Filled in only when the client already has an address (renewing).":"Diisi hanya jika klien sudah punya alamat (saat perpanjangan).","Your address":"Alamat Anda","The address the server is giving out.":"Alamat yang diberikan server.","Next server":"Server berikutnya","Relay agent":"Agen relay","Client MAC":"MAC klien","Server name, boot file":"Nama server, file boot",empty:"kosong","Magic cookie":"Magic cookie","Marks the options that follow as DHCP.":"Menandai opsi-opsi berikutnya sebagai DHCP.","Message type: 1 (Discover)":"Jenis pesan: 1 (Discover)","Client identifier: 01 00:00:5e:00:53:10":"Pengenal klien: 01 00:00:5e:00:53:10","Host name: alice-laptop":"Nama host: alice-laptop","Vendor class: MSFT 5.0":"Kelas vendor: MSFT 5.0","Parameters wanted: 1, 3, 6, 15, 31, 33, 43, 44, 46, 47, 119, 121, 249, 252":"Parameter yang diminta: 1, 3, 6, 15, 31, 33, 43, 44, 46, 47, 119, 121, 249, 252","2 (reply, from a server)":"2 (balasan, dari server)","Message type: 2 (Offer)":"Jenis pesan: 2 (Offer)","Server identifier: 192.168.1.1":"Pengenal server: 192.168.1.1","Lease time: 86,400 s (24 h)":"Masa lease: 86,400 dtk (24 jam)","Renewal time (T1): 43,200 s (12 h)":"Waktu perpanjangan (T1): 43,200 dtk (12 jam)","Rebinding time (T2): 75,600 s (21 h)":"Waktu rebinding (T2): 75,600 dtk (21 jam)","Subnet mask: 255.255.255.0":"Subnet mask: 255.255.255.0","Broadcast address: 192.168.1.255":"Alamat broadcast: 192.168.1.255","DNS server: 8.8.8.8":"Server DNS: 8.8.8.8","Message type: 3 (Request)":"Jenis pesan: 3 (Request)","Requested address: 192.168.1.10":"Alamat yang diminta: 192.168.1.10","Client FQDN: alice-laptop":"FQDN klien: alice-laptop","Message type: 5 (ACK)":"Jenis pesan: 5 (ACK)","Network Diagnostics":"Diagnostik jaringan","Ping / probe":"Ping / probe","Echo reply":"Balasan echo","Error report":"Laporan galat","Internet Control Message Protocol":"Protokol pesan kontrol internet","ICMP is how the network reports back: a router says a packet’s time ran out, a server says nothing is listening on a port. Tools like ping and traceroute are built from these messages. It travels inside IP but carries no application data.":"ICMP adalah cara jaringan memberi laporan balik: router mengabarkan bahwa waktu sebuah paket habis, server mengabarkan bahwa tidak ada yang mendengarkan di sebuah port. Alat seperti ping dan traceroute dibangun dari pesan-pesan ini. ICMP berjalan di dalam IP tetapi tidak membawa data aplikasi.","Carried in":"Dibawa dalam","IP (protocol 1)":"IP (protokol 1)","A type and a code":"Sebuah jenis dan kode",Tools:"Alat",Often:"Sering","Filtered by firewalls":"Disaring oleh firewall","The network answered":"Jaringan menjawab","Replies, expiries and errors":"Balasan, kedaluwarsa, dan galat","An echo request measured the round trip, packets with a small TTL made each router on the path identify itself, and a closed port was reported straight back. Press REPLAY to watch it again.":"Sebuah echo request mengukur waktu pulang-pergi, paket dengan TTL kecil membuat setiap router di jalur memperkenalkan diri, dan port yang tertutup langsung dilaporkan kembali. Tekan ULANGI untuk menontonnya lagi.","Round trip":"Pulang-pergi",Path:"Jalur","12 routers, server at hop 13":"12 router, server di hop 13","Types used":"Jenis yang dipakai","8, 0, 11 and 3":"8, 0, 11, dan 3","Reply TTL":"TTL balasan",Ping:"Ping","Echo request":"Echo request","“ping -n 1 203.0.113.10” sends one ICMP echo request (plain ping sends four, a second apart): type 8, code 0, with an identifier, a sequence number and 32 bytes of filler. The server’s system answers by itself, no application needed.":"“ping -n 1 203.0.113.10” mengirim satu ICMP echo request (ping biasa mengirim empat, berjarak satu detik): jenis 8, kode 0, dengan sebuah pengenal, nomor urut, dan 32 byte pengisi. Sistem server menjawab sendiri, tanpa perlu aplikasi.","Type, code":"Jenis, kode","8, 0 (echo request)":"8, 0 (echo request)","type 8 · seq 1":"jenis 8 · urut 1","32 bytes of data":"32 byte data","Echo Reply":"Echo reply","Round-trip time":"Waktu pulang-pergi","The server sends back an echo reply, type 0, with the same identifier, sequence number and data. Ping prints the time it took and the TTL the reply arrived with: “bytes=32 time=34ms TTL=52”.":"Server mengirim balik echo reply, jenis 0, dengan pengenal, nomor urut, dan data yang sama. Ping menampilkan lama waktunya dan TTL saat balasan tiba: “bytes=32 time=34ms TTL=52”.","0, 0 (echo reply)":"0, 0 (echo reply)","TTL on arrival":"TTL saat tiba","type 0 · seq 1":"jenis 0 · urut 1","same 32 bytes back":"32 byte yang sama kembali","The first router answers":"Router pertama menjawab","“ping -n 1 -i 1” sends the same request with a TTL of 1. The home router lowers it to 0, so it must drop the packet, and it sends back a Time Exceeded message from its own address: “Reply from 192.168.1.1: TTL expired in transit.”":"“ping -n 1 -i 1” mengirim permintaan yang sama dengan TTL 1. Router rumah menurunkannya menjadi 0, jadi router harus membuang paket itu, lalu mengirim balik pesan Time Exceeded dari alamatnya sendiri: “Reply from 192.168.1.1: TTL expired in transit.”","Sent with":"Dikirim dengan","Dropped by":"Dibuang oleh","11, 0 (time exceeded)":"11, 0 (time exceeded)","echo request":"echo request","expires at the first router":"kedaluwarsa di router pertama","type 11 · from 192.168.1.1":"jenis 11 · dari 192.168.1.1","quotes the dropped header":"mengutip header yang dibuang","The next router answers":"Router berikutnya menjawab","With “-i 2”, the home router lowers the TTL to 1 and forwards it. The first router at the internet provider lowers it to 0 and reports back from 198.51.100.1. The home router translates the report back to the laptop like any reply.":"Dengan “-i 2”, router rumah menurunkan TTL menjadi 1 lalu meneruskannya. Router pertama di penyedia internet menurunkannya menjadi 0 dan melapor balik dari 198.51.100.1. Router rumah menerjemahkan laporan itu kembali ke laptop seperti balasan lainnya.","ISP router 198.51.100.1":"Router ISP 198.51.100.1","expires at the second router":"kedaluwarsa di router kedua","type 11 · from 198.51.100.1":"jenis 11 · dari 198.51.100.1","That’s Traceroute":"Itulah traceroute","TTL 1, 2, 3 … until it arrives":"TTL 1, 2, 3 … sampai tiba","tracert automates this: it raises the TTL by one each time, sends three probes per hop and lists who reports back. Hops 3 to 12 work the same way, and with TTL 13 the request finally reaches the server, which replies normally.":"tracert mengotomatiskan ini: TTL dinaikkan satu setiap kali, tiga probe dikirim per hop, dan siapa pun yang melapor balik dicatat. Hop 3 sampai 12 bekerja dengan cara yang sama, dan dengan TTL 13 permintaan akhirnya mencapai server, yang menjawab seperti biasa.","12 routers, then the server":"12 router, lalu server","Per hop":"Per hop","3 probes":"3 probe","On Linux":"Di Linux","traceroute sends UDP":"traceroute mengirim UDP","enough hops to arrive":"cukup hop untuk tiba","the server itself answers":"server itu sendiri yang menjawab","end of the route":"akhir rute",Unreachable:"Tak terjangkau","Nothing listening on that port":"Tidak ada yang mendengarkan di port itu","An app sends a UDP datagram to port 9999, where nothing is listening. The server can’t deliver it, so it replies with Destination Unreachable, code 3 (port unreachable), quoting the start of the datagram. Many firewalls drop such packets silently instead.":"Sebuah aplikasi mengirim datagram UDP ke port 9999, tempat tidak ada yang mendengarkan. Server tidak bisa mengantarkannya, jadi server membalas dengan Destination Unreachable, kode 3 (port tak terjangkau), sambil mengutip awal datagram tersebut. Banyak firewall justru membuang paket seperti ini diam-diam.","3, 3 (port unreachable)":"3, 3 (port tak terjangkau)","Other codes":"Kode lain","0 net, 1 host, 4 too big":"0 jaringan, 1 host, 4 terlalu besar",Firewalls:"Firewall","Often silent instead":"Sering diam saja","to port 9999":"ke port 9999","nothing listening there":"tidak ada yang mendengarkan","type 3 · code 3":"jenis 3 · kode 3","port unreachable":"port tak terjangkau","ICMP · Echo request":"ICMP · Echo request",Code:"Kode","Covers the whole ICMP message.":"Mencakup seluruh pesan ICMP.",Identifier:"Pengenal","Matches replies to this ping program.":"Mencocokkan balasan dengan program ping ini.","Windows counts up across every ping it sends.":"Windows terus menambah angka ini di setiap ping yang dikirimnya.","Windows ping’s filler: the alphabet, a to w, then again.":"Pengisi dari ping Windows: alfabet dari a sampai w, lalu diulang.","ICMP · Echo reply":"ICMP · Echo reply","Sent back exactly as it came.":"Dikirim balik persis seperti datangnya.","ICMP · Time exceeded (TTL reached 0)":"ICMP · Time exceeded (TTL mencapai 0)","Time exceeded (TTL reached 0)":"Time exceeded (TTL mencapai 0)",Unused:"Tidak dipakai","Original packet":"Paket asli","Its source, destination":"Sumber dan tujuannya","its IP header and first 8 bytes (28 bytes)":"header IP-nya dan 8 byte pertamanya (28 byte)","App data":"Data aplikasi","What the app sent; nothing on the server is listening for it.":"Yang dikirim aplikasi; tidak ada apa pun di server yang menunggunya.","ICMP · Destination unreachable (port unreachable)":"ICMP · Destination unreachable (port tak terjangkau)","Destination unreachable (port unreachable)":"Destination unreachable (port tak terjangkau)","Sending Email":"Mengirim email","SMTP command":"Perintah SMTP","SMTP reply":"Balasan SMTP","SMTP moves email: from your mail app to your provider’s server, and from that server to the recipient’s. It is a conversation of short text commands, each answered with a three-digit reply code. Reading mail is a different job, done with IMAP or POP3.":"SMTP memindahkan email: dari aplikasi email Anda ke server penyedia Anda, dan dari server itu ke server penerima. Isinya percakapan berupa perintah teks pendek, masing-masing dijawab dengan kode balasan tiga digit. Membaca email adalah tugas lain, dilakukan dengan IMAP atau POP3.","465/587 submit, 25 relay":"465/587 pengiriman, 25 relay","TCP, usually with TLS":"TCP, biasanya dengan TLS",Commands:"Perintah",Replies:"Balasan","2xx ok, 3xx go on, 4/5xx error":"2xx oke, 3xx lanjut, 4/5xx galat","Mail delivered":"Email terkirim","Two hops, one message":"Dua langkah, satu pesan","Alice’s app handed the message to her provider over an encrypted, logged-in connection. The provider found Bob’s mail server in DNS and relayed it there, upgrading that link to TLS. It now waits in Bob’s mailbox until he reads it with IMAP or POP3.":"Aplikasi Alice menyerahkan pesan ke penyedianya lewat koneksi terenkripsi yang sudah login. Penyedia menemukan server email Bob di DNS lalu meneruskan pesan ke sana, sambil meningkatkan sambungan itu ke TLS. Pesan itu kini menunggu di kotak surat Bob sampai ia membacanya dengan IMAP atau POP3.","Laptop → provider → Bob’s":"Laptop → penyedia → milik Bob",Submission:"Pengiriman","Port 465, TLS, login":"Port 465, TLS, login",Relay:"Relay","Port 25, STARTTLS":"Port 25, STARTTLS","Checks at Bob’s":"Pemeriksaan di pihak Bob","Connect Securely":"Terhubung dengan aman","Alice presses Send. Her mail app connects to her provider’s submission server, smtp.example.com, on port 465. On this port TLS starts immediately, so the whole SMTP conversation, including her password, is encrypted.":"Alice menekan Kirim. Aplikasi emailnya terhubung ke server pengiriman milik penyedianya, smtp.example.com, di port 465. Di port ini TLS langsung dimulai, jadi seluruh percakapan SMTP, termasuk kata sandinya, terenkripsi.","TLS from the start":"TLS sejak awal","SMTP inside TLS":"SMTP di dalam TLS","Greeting & Login":"Sapaan & login","EHLO, then AUTH":"EHLO, lalu AUTH","The server greets with code 220. The app says EHLO and the server lists what it supports, including AUTH. The app logs in with AUTH PLAIN (user name and password, base64-encoded) and gets 235: authenticated.":"Server menyapa dengan kode 220. Aplikasi mengucapkan EHLO dan server mendaftar apa saja yang didukungnya, termasuk AUTH. Aplikasi login dengan AUTH PLAIN (nama pengguna dan kata sandi, dikodekan base64) dan menerima 235: terautentikasi.",Greeting:"Sapaan",Capabilities:"Kemampuan","Login result":"Hasil login","user and password, base64":"pengguna dan kata sandi, base64","Send the Message":"Kirim pesannya","Envelope, then content":"Amplop dulu, lalu isi","MAIL FROM and RCPT TO are the envelope: sender and recipient. PIPELINING lets all three commands share one packet. After 354 comes the message, ended by a line holding just a dot.":"MAIL FROM dan RCPT TO adalah amplopnya: pengirim dan penerima. PIPELINING memungkinkan ketiga perintah berbagi satu paket. Setelah 354 datang pesannya, diakhiri dengan baris yang hanya berisi sebuah titik.",Envelope:"Amplop","Content ends":"Akhir isi","A line with only “.”":"Baris yang hanya berisi “.”",Result:"Hasil","… message …":"… pesan …","Find Bob’s Server":"Temukan server Bob","An MX lookup in DNS":"Pencarian MX di DNS","Alice’s provider now has to deliver to example.org. It asks DNS for that domain’s MX record, which names the server that accepts its mail, then looks up that server’s address.":"Penyedia Alice sekarang harus mengantarkan ke example.org. Ia menanyakan record MX domain itu ke DNS, yang menyebut server penerima email-nya, lalu mencari alamat server tersebut.","MX record":"Record MX","Asked by":"Ditanyakan oleh","Alice’s provider":"Penyedia Alice","Server to Server":"Server ke server","Port 25, upgraded with STARTTLS":"Port 25, ditingkatkan dengan STARTTLS","The provider connects to mx.example.org on port 25. This conversation starts in plain text: the greeting and EHLO reply advertise STARTTLS, the provider asks for it, gets 220 and both sides switch to TLS.":"Penyedia terhubung ke mx.example.org di port 25. Percakapan ini dimulai dalam teks biasa: sapaan dan balasan EHLO mengiklankan STARTTLS, penyedia memintanya, menerima 220, dan kedua pihak beralih ke TLS.","Starts as":"Dimulai sebagai","Plain text":"Teks biasa",Upgrade:"Peningkatan",Deliver:"Antarkan","The same transaction again":"Transaksi yang sama sekali lagi","With TLS on, the provider repeats EHLO, then the envelope and the message, now with a DKIM signature and a Received header added. Bob’s server checks SPF, DKIM and DMARC and accepts it.":"Dengan TLS aktif, penyedia mengulang EHLO, lalu amplop dan pesannya, kini dengan tanda tangan DKIM dan header Received yang ditambahkan. Server Bob memeriksa SPF, DKIM, dan DMARC lalu menerimanya.","Login needed":"Perlu login","No (server to server)":"Tidak (server ke server)","1,316 bytes (signed)":"1,316 byte (bertanda tangan)","Server Hello + encrypted handshake, 2 segments":"Server Hello + handshake terenkripsi, 2 segmen","250 capabilities (PIPELINING, SIZE, AUTH …)":"250 kemampuan (PIPELINING, SIZE, AUTH …)","AUTH PLAIN (credentials)":"AUTH PLAIN (kredensial)","MAIL FROM, RCPT TO, DATA (pipelined)":"MAIL FROM, RCPT TO, DATA (dipipelinekan)","Message (316 bytes), then “.”":"Pesan (316 byte), lalu “.”","250 capabilities (PIPELINING, STARTTLS …)":"250 kemampuan (PIPELINING, STARTTLS …)","250 capabilities (PIPELINING, SIZE …)":"250 kemampuan (PIPELINING, SIZE …)","Message (1,316 bytes), then “.”":"Pesan (1,316 byte), lalu “.”","What this client supports. Its exact contents vary from client to client; this is an example.":"Apa yang didukung klien ini. Isi persisnya berbeda dari satu klien ke klien lain; ini sebuah contoh.","up to 512 bytes":"hingga 512 byte","The server’s choices and its key share.":"Pilihan server dan bagian kuncinya.","Encrypted Extensions, Certificate (the chain), Certificate Verify (the signature), Finished":"Encrypted Extensions, Certificate (rantainya), Certificate Verify (tanda tangannya), Finished","Alice’s message (316 bytes), then a line holding only “.”":"Pesan Alice (316 byte), lalu baris yang hanya berisi “.”","example.org, type MX, class IN":"example.org, tipe MX, kelas IN","mx.example.org, type A, class IN":"mx.example.org, tipe A, kelas IN",Timestamps:"Stempel waktu","Used to measure round trips; both sides offered them.":"Dipakai untuk mengukur waktu pulang-pergi; kedua pihak menawarkannya.","The signed message (1,316 bytes), then a line holding only “.”":"Pesan bertanda tangan (1,316 byte), lalu baris yang hanya berisi “.”","Downloading Email":"Mengunduh email","POP3 command":"Perintah POP3","POP3 reply":"Balasan POP3","Post Office Protocol, version 3":"Protokol kantor pos, versi 3","POP3 lets a mail app download messages from a mailbox on a server. It was designed for one device that fetches mail and then removes it from the server. Commands are short words, and every reply starts with +OK or -ERR.":"POP3 memungkinkan aplikasi email mengunduh pesan dari kotak surat di server. Protokol ini dirancang untuk satu perangkat yang mengambil email lalu menghapusnya dari server. Perintahnya berupa kata-kata pendek, dan setiap balasan diawali +OK atau -ERR.",Model:"Model","Download, then delete":"Unduh, lalu hapus","Mail downloaded":"Email terunduh","And gone from the server":"Dan hilang dari server","Bob’s app logged in, saw two messages, downloaded the first and deleted it, which the server carried out at QUIT. That message now lives only on this laptop, which is why POP3 suits one device and IMAP suits several.":"Aplikasi Bob login, melihat dua pesan, mengunduh yang pertama lalu menghapusnya, yang dijalankan server saat QUIT. Pesan itu kini hanya ada di laptop ini; itulah sebabnya POP3 cocok untuk satu perangkat dan IMAP untuk banyak perangkat.","2 waiting, 1 downloaded":"2 menunggu, 1 terunduh",Deleted:"Dihapus","At QUIT (UPDATE state)":"Saat QUIT (status UPDATE)","Best for":"Paling cocok untuk","A single device":"Satu perangkat","Bob’s mail app connects to pop.example.org on port 995, where TLS starts right away. Inside it, the server greets with +OK. (On port 110 the session starts in plain text and is upgraded with the STLS command.)":"Aplikasi email Bob terhubung ke pop.example.org di port 995, tempat TLS langsung dimulai. Di dalamnya, server menyapa dengan +OK. (Di port 110 sesi dimulai dalam teks biasa dan ditingkatkan dengan perintah STLS.)","USER, then PASS":"USER, lalu PASS","The app sends the user name with USER and the password with PASS. Each command gets its own +OK. Because the session is inside TLS, the password isn’t readable on the way.":"Aplikasi mengirim nama pengguna dengan USER dan kata sandi dengan PASS. Setiap perintah mendapat +OK sendiri. Karena sesinya berada di dalam TLS, kata sandi tidak bisa dibaca di perjalanan.","Protected by":"Dilindungi oleh","Check the Mailbox":"Periksa kotak surat","STAT and LIST":"STAT dan LIST","STAT returns the number of messages and their total size: 2 messages, 5120 bytes. LIST gives each message’s number and size, ending with a line holding just a dot.":"STAT mengembalikan jumlah pesan dan total ukurannya: 2 pesan, 5120 byte. LIST memberi nomor dan ukuran setiap pesan, diakhiri baris yang hanya berisi sebuah titik.","Message 1":"Pesan 1","Message 2":"Pesan 2",Download:"Unduh","RETR 1 asks for the first message. The server answers +OK with its size, then the message and a closing dot: 1904 bytes plus the reply line, two TCP segments.":"RETR 1 meminta pesan pertama. Server menjawab +OK beserta ukurannya, lalu pesannya dan sebuah titik penutup: 1904 byte ditambah baris balasan, dua segmen TCP.",Command:"Perintah","Delete & Quit":"Hapus & keluar","Deleted only at QUIT":"Baru dihapus saat QUIT","DELE 1 only marks the message. The server removes it when the app says QUIT: if the connection dropped before that, nothing would be deleted. Many apps offer “leave a copy on the server”, which skips DELE.":"DELE 1 hanya menandai pesan. Server menghapusnya ketika aplikasi mengucapkan QUIT: jika koneksi terputus sebelum itu, tidak ada yang terhapus. Banyak aplikasi menawarkan “tinggalkan salinan di server”, yang melewatkan DELE.","Marks message 1":"Menandai pesan 1",Removed:"Dihapus",Option:"Opsi","Leave a copy on server":"Tinggalkan salinan di server","PASS (password)":"PASS (kata sandi)","+OK 1904 octets, message, “.” (2 segments)":"+OK 1904 octets, pesan, “.” (2 segmen)","+OK 1904 octets, the 1,904-byte message, then a line holding only “.”":"+OK 1904 octets, pesan 1,904 byte, lalu baris yang hanya berisi “.”","IMAP command":"Perintah IMAP","IMAP response":"Respons IMAP","Internet Message Access Protocol":"Protokol akses pesan internet","IMAP lets mail apps work with a mailbox that stays on the server. Folders, read and flagged marks and deletions are kept there, so a phone, a laptop and webmail all see the same mailbox. The server can also tell an app about new mail as it arrives.":"IMAP memungkinkan aplikasi email bekerja dengan kotak surat yang tetap berada di server. Folder, tanda sudah dibaca dan ditandai, serta penghapusan disimpan di sana, sehingga ponsel, laptop, dan webmail melihat kotak surat yang sama. Server juga bisa memberi tahu aplikasi tentang email baru saat email itu tiba.","Mail stays on the server":"Email tetap di server",Syncs:"Menyinkronkan","Folders and flags":"Folder dan flag","Mailbox in sync":"Kotak surat sinkron","Read once, read everywhere":"Dibaca sekali, terbaca di mana-mana","Bob’s app opened his inbox, read a message, which marked it \\Seen on the server for all his devices, and then waited with IDLE until the server announced new mail. Nothing was deleted: the server still holds everything.":"Aplikasi Bob membuka kotak masuknya dan membaca sebuah pesan, yang menandainya \\Seen di server untuk semua perangkatnya, lalu menunggu dengan IDLE sampai server mengumumkan email baru. Tidak ada yang dihapus: server masih menyimpan semuanya.","2, then 3 (new mail)":"2, lalu 3 (email baru)","Read mark":"Tanda sudah dibaca","\\Seen, stored on server":"\\Seen, disimpan di server","New mail":"Email baru","Pushed during IDLE":"Dikirim saat IDLE","Bob’s app connects to imap.example.org on port 993, where TLS starts right away. The server greets with an untagged “* OK” line that also lists its capabilities, such as IDLE.":"Aplikasi Bob terhubung ke imap.example.org di port 993, tempat TLS langsung dimulai. Server menyapa dengan baris “* OK” tanpa tag yang juga mendaftar kemampuannya, seperti IDLE.","Commands carry tags":"Perintah membawa tag","Every command starts with a tag the app chooses, like a1, and the server ends its answer with the same tag. That way several commands can be in flight and each reply is matched up. Lines starting with * are untagged data.":"Setiap perintah diawali tag pilihan aplikasi, seperti a1, dan server mengakhiri jawabannya dengan tag yang sama. Dengan begitu beberapa perintah bisa berjalan bersamaan dan setiap balasan cocok dengan perintahnya. Baris yang diawali * adalah data tanpa tag.",Tags:"Tag","Match replies to commands":"Mencocokkan balasan dengan perintah","Open the Inbox":"Buka kotak masuk","SELECT a folder":"SELECT sebuah folder","SELECT INBOX opens the folder. The server reports the message count, the flags it supports and the first unread message, then confirms the folder is open read-write.":"SELECT INBOX membuka folder. Server melaporkan jumlah pesan, flag yang didukungnya, dan pesan pertama yang belum dibaca, lalu mengonfirmasi bahwa folder terbuka untuk baca-tulis.","First unread":"Belum dibaca pertama",Access:"Akses","Read a Message":"Baca sebuah pesan","FETCH, and the \\Seen flag":"FETCH, dan flag \\Seen","FETCH 2 BODY[] downloads message 2 (three TCP segments). That sets its \\Seen flag on the server, so it shows as read on Bob’s phone too, and the message stays there.":"FETCH 2 BODY[] mengunduh pesan 2 (tiga segmen TCP). Itu memasang flag \\Seen-nya di server, sehingga pesan itu tampil sudah dibaca di ponsel Bob juga, dan pesannya tetap di sana.","Flag set":"Flag dipasang","\\Seen (on the server)":"\\Seen (di server)","Wait for New Mail":"Tunggu email baru","IDLE: the server pushes":"IDLE: server yang mengabari","IDLE tells the server “let me know when something changes”. About 42 seconds later Alice’s message arrives and the server pushes “* 3 EXISTS” straight away. The app ends IDLE with DONE and can fetch the new mail.":"IDLE memberi tahu server “kabari saya kalau ada yang berubah”. Sekitar 42 detik kemudian pesan Alice tiba dan server langsung mengirim “* 3 EXISTS”. Aplikasi mengakhiri IDLE dengan DONE dan bisa mengambil email baru itu.","Server says":"Kata server","* 3 EXISTS (new mail)":"* 3 EXISTS (email baru)","Ended by":"Diakhiri dengan","a1 LOGIN (user and password)":"a1 LOGIN (pengguna dan kata sandi)","* 2 FETCH (FLAGS (\\Seen) BODY[] {3216}, the 3,216-byte message, then a3 OK FETCH completed":"* 2 FETCH (FLAGS (\\Seen) BODY[] {3216}, pesan 3,216 byte, lalu a3 OK FETCH completed","Transferring Files":"Mentransfer file","FTP command":"Perintah FTP","FTP reply":"Balasan FTP","File data":"Data file","FTP moves files between a client and a server. It is unusual in using two TCP connections: one for commands and replies, and a fresh one for each file or listing. It dates from the early 1970s and sends everything, passwords included, as plain text.":"FTP memindahkan file antara klien dan server. Uniknya, FTP memakai dua koneksi TCP: satu untuk perintah dan balasan, dan satu koneksi baru untuk setiap file atau daftar isi. FTP berasal dari awal 1970-an dan mengirim semuanya, termasuk kata sandi, sebagai teks biasa.","21 control, data varies":"21 kontrol, data berubah-ubah",Connections:"Koneksi","Control + one per transfer":"Kontrol + satu per transfer",Encryption:"Enkripsi","None (plain text)":"Tidak ada (teks biasa)","Safer options":"Pilihan lebih aman","File downloaded":"File terunduh","Two connections, no encryption":"Dua koneksi, tanpa enkripsi","Commands went over the control connection, the file over its own data connection, and closing that connection marked the end of the file. Anyone on the path could have read the password and the file, which is why SFTP or FTPS is used today.":"Perintah lewat koneksi kontrol, file lewat koneksi datanya sendiri, dan penutupan koneksi itu menandai akhir file. Siapa pun di jalur bisa membaca kata sandi dan file-nya; itulah sebabnya kini orang memakai SFTP atau FTPS.","2 (control + data)":"2 (kontrol + data)",File:"File","4,000 bytes, 3 segments":"4,000 byte, 3 segmen",Password:"Kata sandi","Sent in plain text":"Dikirim sebagai teks biasa","Use instead":"Gunakan sebagai gantinya","Control Connection":"Koneksi kontrol","Port 21, plain text":"Port 21, teks biasa","The FTP app opens a TCP connection to ftp.example.com on port 21. This control connection carries commands and replies for the whole session. The server greets with 220. Like SMTP, every reply starts with a three-digit code.":"Aplikasi FTP membuka koneksi TCP ke ftp.example.com di port 21. Koneksi kontrol ini membawa perintah dan balasan untuk seluruh sesi. Server menyapa dengan 220. Seperti SMTP, setiap balasan diawali kode tiga digit.","USER and PASS, readable by anyone":"USER dan PASS, terbaca oleh siapa saja","The app sends USER, the server asks for the password with 331, and PASS sends it. Nothing is encrypted, so the user name and password cross every network on the way as readable text.":"Aplikasi mengirim USER, server meminta kata sandi dengan 331, dan PASS mengirimkannya. Tidak ada yang dienkripsi, jadi nama pengguna dan kata sandi melintasi setiap jaringan di jalur sebagai teks yang bisa dibaca.","Visible to":"Terlihat oleh","Anyone on the path":"Siapa pun di jalur","Passive Mode":"Mode pasif","The server names a data port":"Server menyebut port data","TYPE I asks for a byte-for-byte binary copy. PASV asks the server to open a port for the data connection. The reply encodes the address and port as six numbers: 195 × 256 + 149 = port 50069. The laptop connects out, which works through NAT.":"TYPE I meminta salinan biner byte demi byte. PASV meminta server membuka port untuk koneksi data. Balasannya mengodekan alamat dan port sebagai enam angka: 195 × 256 + 149 = port 50069. Laptop yang membuka koneksi keluar, dan itu bisa melewati NAT.","Data port":"Port data","Active mode":"Mode aktif","Server dials in: NAT blocks":"Server menghubungi balik: NAT memblokir","Data Connection":"Koneksi data","A second TCP connection":"Koneksi TCP kedua","The app opens a second TCP connection, to port 50069, and asks for the file on the control connection with RETR. The server answers 150 there and starts sending the file over the new connection.":"Aplikasi membuka koneksi TCP kedua, ke port 50069, dan meminta file di koneksi kontrol dengan RETR. Server menjawab 150 di sana dan mulai mengirim file lewat koneksi baru itu.","Data to":"Data ke","The File Arrives":"File tiba","Closing the connection ends it":"Menutup koneksi menandai akhirnya","The 4,000 bytes arrive in 3 TCP segments. FTP sends no length marker in the data itself: the server closes the data connection to mark the end of the file. Once the laptop has acknowledged everything, the server confirms with 226 on the control connection.":"Ke-4,000 byte itu tiba dalam 3 segmen TCP. FTP tidak mengirim penanda panjang di dalam datanya: server menutup koneksi data untuk menandai akhir file. Setelah laptop mengonfirmasi semuanya, server mengonfirmasi dengan 226 di koneksi kontrol.","End of file":"Akhir file","Data connection closed":"Koneksi data ditutup","4,000 bytes, readable by anyone":"4,000 byte, terbaca oleh siapa saja","end of file:":"akhir file:","data connection closed":"koneksi data ditutup",Quit:"Keluar","Close the control connection":"Tutup koneksi kontrol","QUIT ends the session and the server says goodbye with 221. For anything sensitive, SFTP (a different protocol, run over SSH) or FTPS (FTP inside TLS) gives the same job encryption.":"QUIT mengakhiri sesi dan server berpamitan dengan 221. Untuk apa pun yang sensitif, SFTP (protokol lain, berjalan di atas SSH) atau FTPS (FTP di dalam TLS) melakukan pekerjaan yang sama dengan enkripsi.","Encrypted cousins":"Kerabat terenkripsi","FTP data":"Data FTP","The file itself, unencrypted: anyone on the path could read it.":"File-nya sendiri, tanpa enkripsi: siapa pun di jalur bisa membacanya.","Secure Remote Login":"Login jarak jauh aman","Plain setup":"Penyiapan teks biasa","From laptop":"Dari laptop","From server":"Dari server","Some packets not shown":"Beberapa paket tidak ditampilkan","SSH gives you an encrypted, authenticated connection to another computer, to run commands on it, copy files (SFTP, scp) or carry other connections. The server proves who it is with a host key; you prove who you are with a key pair or a password.":"SSH memberi Anda koneksi terenkripsi dan terautentikasi ke komputer lain, untuk menjalankan perintah di sana, menyalin file (SFTP, scp), atau membawa koneksi lain. Server membuktikan siapa dirinya dengan host key; Anda membuktikan siapa diri Anda dengan pasangan kunci atau kata sandi.","Server proves":"Server membuktikan","Host key (known_hosts)":"Host key (known_hosts)","You prove":"Anda membuktikan","Key pair or password":"Pasangan kunci atau kata sandi","Logged in securely":"Login dengan aman","Encrypted from the key exchange on":"Terenkripsi sejak pertukaran kunci","The two sides agreed on algorithms, built shared keys with a post-quantum hybrid exchange, and the server proved its identity with its host key. Alice proved hers by signing with a private key that never left the laptop, then typed a command, one packet per key.":"Kedua pihak menyepakati algoritma, membangun kunci bersama dengan pertukaran hibrida pascakuantum, dan server membuktikan identitasnya dengan host key. Alice membuktikan identitasnya dengan menandatangani memakai kunci privat yang tidak pernah meninggalkan laptop, lalu mengetik sebuah perintah, satu paket per tombol.",Login:"Login","Ed25519 key, no password":"Kunci Ed25519, tanpa kata sandi","Say Hello":"Ucapkan halo","Versions, in plain text":"Versi, dalam teks biasa","Alice runs “ssh alice@server.example.com”. After the TCP handshake on port 22, each side sends one line of plain text naming the SSH protocol version (2.0) and its software. Everything else in SSH is binary.":"Alice menjalankan “ssh alice@server.example.com”. Setelah handshake TCP di port 22, setiap pihak mengirim satu baris teks biasa yang menyebut versi protokol SSH (2.0) dan perangkat lunaknya. Semua hal lain di SSH berbentuk biner.","Agree on Algorithms":"Sepakati algoritma","KEXINIT lists, first match wins":"Daftar KEXINIT, kecocokan pertama yang menang","Each side sends a KEXINIT listing every algorithm it supports, in order of preference, for key exchange, host keys, encryption, integrity and compression. In each category the first algorithm on the laptop’s list that the server also supports is chosen.":"Setiap pihak mengirim KEXINIT yang mendaftar semua algoritma yang didukungnya, urut menurut preferensi, untuk pertukaran kunci, host key, enkripsi, integritas, dan kompresi. Di setiap kategori, yang dipilih adalah algoritma pertama di daftar laptop yang juga didukung server.","Host key":"Host key","server’s algorithm lists":"daftar algoritma server","in order of preference":"urut menurut preferensi","laptop’s algorithm lists":"daftar algoritma laptop","Key Exchange":"Pertukaran kunci","Shared keys, and a host key check":"Kunci bersama, dan pemeriksaan host key","The laptop sends its half of a hybrid exchange: a Streamlined NTRU Prime key, chosen to resist future quantum computers, plus an X25519 key. The server answers with its half, its host key and a signature over the exchange. NEWKEYS switches encryption on.":"Laptop mengirim separuh bagiannya dari pertukaran hibrida: kunci Streamlined NTRU Prime, dipilih agar tahan terhadap komputer kuantum masa depan, ditambah kunci X25519. Server menjawab dengan separuh bagiannya, host key-nya, dan tanda tangan atas pertukaran itu. NEWKEYS menyalakan enkripsi.",Hybrid:"Hibrida","Matches known_hosts":"Cocok dengan known_hosts","First visit":"Kunjungan pertama","ssh asks you to confirm":"ssh meminta Anda mengonfirmasi","public keys":"kunci publik","its half, its host key":"separuh bagiannya, host key-nya","and a signature":"dan tanda tangan","Log In with a Key":"Login dengan kunci","Sign, don’t send a secret":"Tanda tangani, jangan kirim rahasia","The server lists the login methods it accepts. The laptop offers Alice’s public key, and the server says it would accept it. The laptop then signs this session with the private key, which never leaves the laptop. The server checks the signature against authorized_keys.":"Server mendaftar metode login yang diterimanya. Laptop menawarkan kunci publik Alice, dan server menjawab bahwa ia akan menerimanya. Lalu laptop menandatangani sesi ini dengan kunci privat, yang tidak pernah meninggalkan laptop. Server memeriksa tanda tangan itu dengan authorized_keys.",Methods:"Metode","Ed25519, private stays here":"Ed25519, kunci privat tetap di sini","Checked with":"Diperiksa dengan","alice’s public key":"kunci publik alice","would you accept it?":"apakah Anda menerimanya?","yes, that key":"ya, kunci itu","is in authorized_keys":"ada di authorized_keys","same key, plus a signature":"kunci yang sama, ditambah tanda tangan","made with the private key":"dibuat dengan kunci privat","logged in":"berhasil login","Open a Session":"Buka sesi","Channels inside one connection":"Kanal di dalam satu koneksi","One SSH connection can carry many channels: a shell, file transfers, forwarded ports. The laptop opens a session channel, then asks for a terminal and a shell (not shown), and the server sends its welcome text and a prompt.":"Satu koneksi SSH bisa membawa banyak kanal: shell, transfer file, port yang diteruskan. Laptop membuka kanal sesi, lalu meminta terminal dan shell (tidak ditampilkan), dan server mengirim teks sambutan serta prompt.",Channel:"Kanal",session:"sesi","Then asks for":"Lalu meminta","A terminal and a shell":"Terminal dan shell","Also possible":"Juga bisa","SFTP, port forwarding":"SFTP, penerusan port","open a channel:":"buka kanal:","channel open":"kanal terbuka","Type a Command":"Ketik perintah","Every key is a packet":"Setiap tombol adalah paket","Alice types pwd. Each key goes out at once in its own encrypted packet, and the server sends the character back to be shown (the echo). Since 9.5, OpenSSH sends keys on a 20 ms beat and adds decoy packets, so typing rhythm is harder to read from the timing.":"Alice mengetik pwd. Setiap tombol langsung dikirim dalam paket terenkripsinya sendiri, dan server mengirim balik karakternya untuk ditampilkan (echo). Sejak versi 9.5, OpenSSH mengirim tombol dengan ketukan 20 ms dan menambahkan paket umpan, agar ritme mengetik lebih sulit dibaca dari waktunya.","Per key":"Per tombol","1 packet, 90 bytes":"1 paket, 90 byte",Echo:"Echo","Sent back by the server":"Dikirim balik oleh server",Timing:"Waktu","20 ms beat plus decoys":"Ketukan 20 ms plus umpan","Enter key":"Tombol Enter","Client: KEX_ECDH_INIT (sntrup761x25519 public keys)":"Client: KEX_ECDH_INIT (kunci publik sntrup761x25519)","Server: KEX_ECDH_REPLY (host key, its half, signature)":"Server: KEX_ECDH_REPLY (host key, separuh bagiannya, tanda tangan)","Encrypted (len=44): service request, ssh-userauth":"Terenkripsi (len=44): permintaan layanan, ssh-userauth","Encrypted (len=44): service accept":"Terenkripsi (len=44): layanan diterima","Encrypted (len=68): login with method none":"Terenkripsi (len=68): login dengan metode none","Encrypted (len=52): try publickey,password":"Terenkripsi (len=52): coba publickey,password","Encrypted (len=140): offer public key":"Terenkripsi (len=140): menawarkan kunci publik","Encrypted (len=100): public key OK":"Terenkripsi (len=100): kunci publik OK","Encrypted (len=308): public key + signature":"Terenkripsi (len=308): kunci publik + tanda tangan","Encrypted (len=28): login success":"Terenkripsi (len=28): login berhasil","Encrypted (len=52): channel open: session":"Terenkripsi (len=52): buka kanal: session","Encrypted (len=44): channel open confirmed":"Terenkripsi (len=44): pembukaan kanal dikonfirmasi","Encrypted (len=36): keystroke":"Terenkripsi (len=36): ketukan tombol","Encrypted (len=36): echo":"Terenkripsi (len=36): echo","Encrypted (len=36): keystroke (Enter)":"Terenkripsi (len=36): ketukan tombol (Enter)","Encrypted (len=132): output and a new prompt":"Terenkripsi (len=132): output dan prompt baru","Packet length":"Panjang paket","Bytes after this field.":"Byte setelah kolom ini.","Padding length":"Panjang padding","Random padding brings the packet to a multiple of 8 bytes.":"Padding acak membuat paket menjadi kelipatan 8 byte.",Cookie:"Cookie","Host keys":"Host key","Ciphers, out":"Cipher, keluar","Ciphers, in":"Cipher, masuk","MACs, out":"MAC, keluar","Compression, out":"Kompresi, keluar","Compression, in":"Kompresi, masuk","Languages, out":"Bahasa, keluar","Languages, in":"Bahasa, masuk","First packet follows":"Paket pertama menyusul",Reserved:"Dicadangkan","Public keys":"Kunci publik","51 bytes: ssh-ed25519 public key":"51 byte: kunci publik ssh-ed25519","Server’s half":"Separuh milik server","1071 bytes (sntrup761 ciphertext 1,039 + X25519 32)":"1071 byte (ciphertext sntrup761 1,039 + X25519 32)",Signature:"Tanda tangan","83 bytes: ssh-ed25519 signature over the exchange":"83 byte: tanda tangan ssh-ed25519 atas pertukaran","From the next packet on, this side encrypts.":"Mulai paket berikutnya, pihak ini mengenkripsi.","SSH · encrypted packet":"SSH · paket terenkripsi","Encrypted packet":"Paket terenkripsi","With chacha20-poly1305 even the length is encrypted; a 16-byte tag at the end shows any change.":"Dengan chacha20-poly1305 bahkan panjangnya pun dienkripsi; tag 16 byte di akhir menunjukkan setiap perubahan.","SSH_MSG_USERAUTH_REQUEST (50): user “alice”, service “ssh-connection”, method “none”":"SSH_MSG_USERAUTH_REQUEST (50): pengguna “alice”, layanan “ssh-connection”, metode “none”","SSH_MSG_USERAUTH_FAILURE (51): methods that can continue: “publickey,password”":"SSH_MSG_USERAUTH_FAILURE (51): metode yang bisa dilanjutkan: “publickey,password”","SSH_MSG_USERAUTH_REQUEST (50): method “publickey”, no signature, the ssh-ed25519 public key":"SSH_MSG_USERAUTH_REQUEST (50): metode “publickey”, tanpa tanda tangan, kunci publik ssh-ed25519","SSH_MSG_USERAUTH_PK_OK (60): the same ssh-ed25519 key":"SSH_MSG_USERAUTH_PK_OK (60): kunci ssh-ed25519 yang sama","SSH_MSG_USERAUTH_REQUEST (50): method “publickey-hostbound-v00@openssh.com”, the key, the server’s host key and a signature":"SSH_MSG_USERAUTH_REQUEST (50): metode “publickey-hostbound-v00@openssh.com”, kuncinya, host key server, dan tanda tangan","SSH_MSG_CHANNEL_OPEN (90): “session”, channel 0, window 2 MB, packets up to 32 KB":"SSH_MSG_CHANNEL_OPEN (90): “session”, kanal 0, window 2 MB, paket hingga 32 KB","SSH_MSG_CHANNEL_OPEN_CONFIRMATION (91): channel 0 is open":"SSH_MSG_CHANNEL_OPEN_CONFIRMATION (91): kanal 0 terbuka","SSH_MSG_CHANNEL_DATA (94), channel 0: 1 byte, “p”":"SSH_MSG_CHANNEL_DATA (94), kanal 0: 1 byte, “p”","SSH_MSG_CHANNEL_DATA (94), channel 0: 1 byte, “p”, sent back to be shown":"SSH_MSG_CHANNEL_DATA (94), kanal 0: 1 byte, “p”, dikirim balik untuk ditampilkan","SSH_MSG_CHANNEL_DATA (94), channel 0: 1 byte, “w”":"SSH_MSG_CHANNEL_DATA (94), kanal 0: 1 byte, “w”","SSH_MSG_CHANNEL_DATA (94), channel 0: 1 byte, “w”, sent back to be shown":"SSH_MSG_CHANNEL_DATA (94), kanal 0: 1 byte, “w”, dikirim balik untuk ditampilkan","SSH_MSG_CHANNEL_DATA (94), channel 0: 1 byte, “d”":"SSH_MSG_CHANNEL_DATA (94), kanal 0: 1 byte, “d”","SSH_MSG_CHANNEL_DATA (94), channel 0: 1 byte, “d”, sent back to be shown":"SSH_MSG_CHANNEL_DATA (94), kanal 0: 1 byte, “d”, dikirim balik untuk ditampilkan","SSH_MSG_CHANNEL_DATA (94), channel 0: 1 byte, a carriage return (Enter)":"SSH_MSG_CHANNEL_DATA (94), kanal 0: 1 byte, carriage return (Enter)","SSH_MSG_CHANNEL_DATA (94), channel 0: 94 bytes: a new line, the shell’s terminal codes, “/home/alice”, and the coloured prompt":"SSH_MSG_CHANNEL_DATA (94), kanal 0: 94 byte: baris baru, kode terminal shell, “/home/alice”, dan prompt berwarna","From browser":"Dari browser","TLS puts a secure channel on top of TCP. It proves the server’s identity with a certificate, agrees on fresh keys, then encrypts and authenticates everything sent. HTTPS, secure email and many other protocols run inside it. SSL was the name of its predecessor.":"TLS memasang kanal aman di atas TCP. TLS membuktikan identitas server dengan sertifikat, menyepakati kunci baru, lalu mengenkripsi dan mengautentikasi semua yang dikirim. HTTPS, email aman, dan banyak protokol lain berjalan di dalamnya. SSL adalah nama pendahulunya.",Sits:"Letaknya","Between TCP and the app":"Di antara TCP dan aplikasi","OSI layer":"Lapisan OSI","Often placed at 6":"Sering ditaruh di 6",Current:"Saat ini",Retired:"Sudah pensiun","SSL 2 and 3, TLS 1.0 and 1.1":"SSL 2 dan 3, TLS 1.0 dan 1.1","The app’s own (443, 993 …)":"Port aplikasinya sendiri (443, 993 …)","Secure from start to finish":"Aman dari awal sampai akhir","One round trip to set up":"Satu kali pulang-pergi untuk penyiapan","One round trip agreed on a version, a cipher and a post-quantum hybrid key. The certificate chain proved who the server was, and every byte after the Server Hello was encrypted and authenticated, right up to the close_notify. Press REPLAY to watch it again.":"Satu kali pulang-pergi cukup untuk menyepakati versi, cipher, dan kunci hibrida pascakuantum. Rantai sertifikat membuktikan siapa server itu, dan setiap byte setelah Server Hello dienkripsi dan diautentikasi, sampai close_notify. Tekan ULANGI untuk menontonnya lagi.","1 round trip":"1 kali pulang-pergi","Everything the browser supports":"Semua yang didukung browser","After the TCP handshake the browser lists what it can do: TLS versions, cipher suites, and key shares for the groups it expects, including the post-quantum hybrid X25519MLKEM768. It also names the site (SNI) and the protocols it speaks (ALPN).":"Setelah handshake TCP, browser mendaftar apa yang bisa dilakukannya: versi TLS, cipher suite, dan key share untuk grup yang diharapkannya, termasuk hibrida pascakuantum X25519MLKEM768. Browser juga menyebut situsnya (SNI) dan protokol yang dipakainya (ALPN).",Versions:"Versi","versions, ciphers, key shares":"versi, cipher, key share","Choices made, keys computed":"Pilihan dibuat, kunci dihitung","The server picks TLS 1.3, the cipher suite and the hybrid group, and sends its own key share. From the two shares both sides compute the same secret without it ever crossing the network. Everything after this message is encrypted.":"Server memilih TLS 1.3, cipher suite, dan grup hibrida, lalu mengirim key share-nya sendiri. Dari kedua share itu, kedua pihak menghitung rahasia yang sama tanpa rahasia itu pernah melintasi jaringan. Semua setelah pesan ini terenkripsi.",Group:"Grup","From here on":"Mulai dari sini","its key share":"key share-nya",Certificate:"Sertifikat","Who the server is, proven":"Siapa server itu, terbukti","Now encrypted, the flight continues: the chosen protocol (http/1.1), the certificate chain, a signature made with the certificate’s private key, and Finished.":"Kini terenkripsi, kirimannya berlanjut: protokol yang dipilih (http/1.1), rantai sertifikat, tanda tangan yang dibuat dengan kunci privat sertifikat, dan Finished.",Chain:"Rantai","Site → intermediate → root":"Situs → perantara → root","Proves the private key":"Membuktikan kunci privat",Checked:"Diperiksa","Name, dates, trusted root":"Nama, tanggal, root tepercaya","encrypted: http/1.1, certificates,":"terenkripsi: http/1.1, sertifikat,","signature, Finished":"tanda tangan, Finished","One round trip, then data":"Satu kali pulang-pergi, lalu data","The browser sends its own Finished: a check value over everything both sides said, keyed with the new secret, so any tampering with the hellos would show. TLS 1.3 needs one round trip before data flows; TLS 1.2 needed two.":"Browser mengirim Finished-nya sendiri: nilai pemeriksa atas semua yang dikatakan kedua pihak, dihitung dengan rahasia baru, sehingga setiap utak-atik pada hello akan ketahuan. TLS 1.3 butuh satu kali pulang-pergi sebelum data mengalir; TLS 1.2 butuh dua.",Covers:"Mencakup","The whole handshake":"Seluruh handshake","For old middleboxes":"Untuk middlebox lama","check value over":"nilai pemeriksa atas","the whole handshake":"seluruh handshake","Encrypted Data":"Data terenkripsi","Records, tags and tickets":"Record, tag, dan tiket","HTTP now travels in encrypted records, each with a 16-byte tag that exposes any change. The server also sends two session tickets: next time the browser can resume with one and skip the certificate.":"HTTP kini berjalan dalam record terenkripsi, masing-masing dengan tag 16 byte yang membongkar setiap perubahan. Server juga mengirim dua tiket sesi: lain kali browser bisa melanjutkan dengan salah satunya dan melewati sertifikat.","Per record":"Per record","22 bytes of overhead":"22 byte overhead","2, for resuming later":"2, untuk melanjutkan nanti",Visible:"Terlihat","IPs, SNI, sizes, timing":"IP, SNI, ukuran, waktu","2 session tickets":"2 tiket sesi","for resuming later":"untuk melanjutkan nanti",Closing:"Penutupan","close_notify, then TCP":"close_notify, lalu TCP","After 75 idle seconds the server closes the connection. It first sends a close_notify alert, encrypted like everything else, so the browser knows the data ended on purpose and wasn’t cut short by an attacker. Then TCP closes as usual.":"Setelah 75 detik tanpa aktivitas, server menutup koneksi. Server lebih dulu mengirim alert close_notify, terenkripsi seperti semua yang lain, agar browser tahu bahwa data berakhir dengan sengaja dan tidak dipotong oleh penyerang. Lalu TCP ditutup seperti biasa.",Alert:"Alert","Shows nothing was cut off":"Menunjukkan tidak ada yang terpotong","TCP FIN from both sides":"TCP FIN dari kedua pihak","alert: close_notify":"alert: close_notify",encrypted:"terenkripsi","Server Hello, Change Cipher Spec (+ encrypted)":"Server Hello, Change Cipher Spec (+ terenkripsi)","Encrypted handshake (continued)":"Handshake terenkripsi (lanjutan)","Encrypted handshake (certificate, verify, Finished)":"Handshake terenkripsi (sertifikat, verifikasi, Finished)","Application Data (inside: close_notify alert)":"Application Data (di dalamnya: alert close_notify)","Alert: close_notify (the data ends here, on purpose)":"Alert: close_notify (data berakhir di sini, dengan sengaja)","No IP address":"Tanpa alamat IP","192.168.1.1 · DHCP server":"192.168.1.1 · server DHCP"},d={"Two-way web messaging":"Pesan web dua arah","Browser video calls":"Panggilan video di browser","HTTP/3 over UDP":"HTTP/3 lewat UDP","Routing between networks":"Rute antarjaringan","Address setup, neighbour discovery":"Penyiapan alamat, penemuan tetangga","Private DNS lookups":"Pencarian DNS yang privat","Signed DNS answers":"Jawaban DNS bertanda tangan","Network Time Protocol":"Protokol waktu jaringan","Joining a network (WPA2)":"Bergabung ke jaringan (WPA2)","Wi-Fi Protected Access 3":"Wi-Fi Protected Access 3","802.1X Enterprise Wi-Fi":"Wi-Fi perusahaan 802.1X","Hotel and café Wi-Fi logins":"Login Wi-Fi hotel dan kafe","Windows file sharing":"Berbagi file Windows","Forward proxy and CONNECT":"Proxy maju dan CONNECT","Socket Secure proxy":"Proxy Socket Secure","TLS offloading":"Pengalihan beban TLS","A modern VPN":"VPN modern","IKEv2 and ESP":"IKEv2 dan ESP","Industrial control (OT)":"Kendali industri (OT)",Proxy:"Proxy","App Server":"Server aplikasi","File Server":"Server file","ISP Router":"Router ISP","Transit Router":"Router transit","Hosting Router":"Router hosting","Their Router":"Router-nya","Their Laptop":"Laptop-nya",Transit:"Transit",Hosting:"Hosting","The router itself.":"Router itu sendiri.","Mail in Sync":"Surel yang selaras","Live Updates":"Pembaruan live","From the browser":"Dari browser","From the server":"Dari server","The WebSocket Protocol":"Protokol WebSocket","A WebSocket keeps one connection open between a web page and a server, so either side can send a message at any moment: chat, live scores, games, shared documents. It starts as an ordinary HTTP request asking to upgrade; after that, messages travel in small frames with a header of just a few bytes.":"WebSocket menjaga satu koneksi tetap terbuka antara halaman web dan server, sehingga kedua pihak bisa mengirim pesan kapan saja: obrolan, skor langsung, game, dokumen bersama. Ia dimulai sebagai permintaan HTTP biasa yang meminta upgrade; setelah itu, pesan berjalan dalam frame kecil dengan header hanya beberapa byte.","80 (ws://), 443 (wss://)":"80 (ws://), 443 (wss://)","An HTTP request (Upgrade)":"Permintaan HTTP (Upgrade)","Frames both ways, any time":"Frame dua arah, kapan saja","Frame header":"Header frame","2–14 bytes":"2–14 byte","One request, then messages":"Satu permintaan, lalu pesan","One HTTP request turned an ordinary TCP connection into a two-way channel. After that every message cost a few bytes of header, and the server could send whenever it had something to say. Press REPLAY to watch it again.":"Satu permintaan HTTP mengubah koneksi TCP biasa menjadi saluran dua arah. Setelah itu setiap pesan hanya memakan beberapa byte header, dan server bisa mengirim kapan pun ia punya sesuatu untuk disampaikan. Tekan ULANGI untuk menontonnya lagi.","GET with Upgrade, then 101":"GET dengan Upgrade, lalu 101","Smallest frame":"Frame terkecil","2 bytes (a ping)":"2 byte (sebuah ping)","Server push":"Kiriman server","Any time, unasked":"Kapan saja, tanpa diminta","Real sites":"Situs sungguhan","wss:// (inside TLS)":"wss:// (di dalam TLS)","TCP to the server, as for HTTP":"TCP ke server, seperti untuk HTTP",'The chat page is already open, loaded from www.example.com. Its script calls new WebSocket("ws://www.example.com/chat"), and the browser starts with an ordinary TCP connection to port 80. (Real sites use wss://, the same thing inside TLS; plain ws:// lets you read every byte.)':'Halaman obrolan sudah terbuka, dimuat dari www.example.com. Skripnya memanggil new WebSocket("ws://www.example.com/chat"), dan browser memulai dengan koneksi TCP biasa ke port 80. (Situs sungguhan memakai wss://, hal yang sama di dalam TLS; ws:// polos membuat Anda bisa membaca setiap byte.)',"ws://www.example.com/chat":"ws://www.example.com/chat","Ask to Upgrade":"Meminta upgrade","An HTTP request with Upgrade: websocket":"Permintaan HTTP dengan Upgrade: websocket","The browser sends an HTTP GET with Upgrade: websocket and Connection: Upgrade. Sec-WebSocket-Key is 16 random bytes written in base64, which the server has to answer correctly. The browser also offers to compress messages (permessage-deflate).":"Browser mengirim GET HTTP dengan Upgrade: websocket dan Connection: Upgrade. Sec-WebSocket-Key adalah 16 byte acak yang ditulis dalam base64, yang harus dijawab server dengan benar. Browser juga menawarkan untuk memampatkan pesan (permessage-deflate).","Asks for":"Meminta","16 random bytes, base64":"16 byte acak, base64",UPGRADE:"UPGRADE","Switch Protocols":"Ganti protokol","101: from now on, WebSocket":"101: mulai sekarang, WebSocket","The server answers 101 Switching Protocols. Its Sec-WebSocket-Accept is the key with a fixed string added, hashed with SHA-1 and written in base64: proof that it understood the request. It didn’t take up compression, so messages go as plain text. HTTP is finished on this connection; from now on both sides send WebSocket frames.":"Server menjawab 101 Switching Protocols. Sec-WebSocket-Accept miliknya adalah kunci yang ditambah string tetap, di-hash dengan SHA-1 dan ditulis dalam base64: bukti bahwa ia memahami permintaan. Ia tidak menerima pemampatan, jadi pesan dikirim sebagai teks biasa. HTTP selesai di koneksi ini; mulai sekarang kedua pihak mengirim frame WebSocket.",Accept:"Accept","SHA-1 of the key + a fixed string":"SHA-1 dari kunci + string tetap",Compression:"Pemampatan","Offered, not taken":"Ditawarkan, tidak diterima","NOW A WEBSOCKET":"SEKARANG WEBSOCKET","Small frames, from either side":"Frame kecil, dari kedua pihak",'You send "Hello": a 2-byte header, a 4-byte masking key and the 5 masked bytes, 11 bytes in all instead of a whole HTTP request. Seconds later the server pushes Bob’s message without being asked: the connection is still open, so it can. Frames from the browser are always masked; frames from the server never are.':'Anda mengirim "Hello": header 2 byte, kunci mask 4 byte, dan 5 byte yang di-mask, total 11 byte alih-alih satu permintaan HTTP utuh. Beberapa detik kemudian server mendorong pesan Bob tanpa diminta: koneksinya masih terbuka, jadi ia bisa. Frame dari browser selalu di-mask; frame dari server tidak pernah.',"You send":"Anda kirim","Server pushes":"Server mendorong",'"bob: hi there"':'"bob: hi there"',Masked:"Di-mask","From the browser only":"Hanya dari browser",TEXT:"TEKS",masked:"di-mask",unasked:"tanpa diminta","Keeping It Alive":"Menjaga tetap hidup","Ping and pong":"Ping dan pong","After half a minute with nothing to say, the server sends a ping, so routers and firewalls on the way don’t forget the quiet connection. The browser answers with a pong on its own; the page’s script never sees either.":"Setelah setengah menit tanpa ada yang dikatakan, server mengirim ping agar router dan firewall di jalur tidak melupakan koneksi yang sepi itu. Browser menjawab dengan pong sendiri; skrip halaman tidak melihat keduanya.","Opcode 9, from either side":"Opcode 9, dari kedua pihak",Pong:"Pong","Opcode 10, by itself":"Opcode 10, otomatis","How often":"Seberapa sering","Up to the server (30 s)":"Terserah server (30 dtk)","A close frame each way":"Frame penutup di tiap arah","When you leave the chat, the page’s script closes the WebSocket with status 1000 (normal closure): the browser sends a close frame and the server answers with its own. Then the server closes the TCP connection. (Simply closing the tab would send 1001, going away.)":"Saat Anda meninggalkan obrolan, skrip halaman menutup WebSocket dengan status 1000 (penutupan normal): browser mengirim frame penutup dan server menjawab dengan miliknya. Lalu server menutup koneksi TCP. (Sekadar menutup tab akan mengirim 1001, going away.)",Opcode:"Opcode","8 (close)":"8 (tutup)","1000 (normal closure)":"1000 (penutupan normal)","TCP closes":"TCP ditutup",CLOSE:"TUTUP","1000 normal closure":"1000 penutupan normal","FIN 1: this frame is a whole message. The opcode says what it carries.":"FIN 1: frame ini satu pesan utuh. Opcode menyebut apa yang dibawanya.","Mask, length":"Mask, panjang","Everything a browser sends is masked.":"Semua yang dikirim browser di-mask.","Masking key":"Kunci mask","Chosen at random for every frame.":"Dipilih acak untuk setiap frame.",Payload:"Muatan","Each byte XORed with the masking key in turn; the server XORs it back.":"Setiap byte di-XOR bergiliran dengan kunci mask; server membalik XOR-nya.","A server never masks what it sends.":"Server tidak pernah me-mask apa yang dikirimnya.","Status code":"Kode status","Joining a Network":"Masuk ke jaringan","From the access point":"Dari titik akses","4-way handshake":"Handshake 4 arah","Access Point":"Titik akses","Wi-Fi (802.11) with WPA2":"Wi-Fi (802.11) dengan WPA2","Wi-Fi carries a network over radio. Before a device can send anything, it has to find the network, join it and prove it knows the password. With WPA2-Personal that proof is the 4-way handshake: four short messages that turn the password into fresh encryption keys, without the password ever going over the air.":"Wi-Fi membawa jaringan lewat radio. Sebelum sebuah perangkat bisa mengirim apa pun, ia harus menemukan jaringan, bergabung, dan membuktikan bahwa ia tahu kata sandinya. Dengan WPA2-Personal bukti itu adalah handshake 4 arah: empat pesan pendek yang mengubah kata sandi menjadi kunci enkripsi baru, tanpa kata sandi itu pernah melewati udara.","Data Link (Layer 2)":"Data link (lapisan 2)",Standard:"Standar",Joining:"Bergabung","Probe, authenticate, associate":"Probe, autentikasi, asosiasi","Keys from":"Kunci dari","The 4-way handshake":"Handshake 4 arah",Connected:"Terhubung","Eleven frames to a secure link":"Sebelas frame menuju tautan aman","The laptop found the network, joined it with two formalities and proved it knew the password in a four-message handshake, without ever sending it. Everything after that was encrypted with keys made for this connection alone. Press REPLAY to watch it again.":"Laptop menemukan jaringan, bergabung dengan dua formalitas, dan membuktikan bahwa ia tahu kata sandi dalam handshake empat pesan, tanpa pernah mengirimkannya. Semua setelahnya dienkripsi dengan kunci yang dibuat khusus untuk koneksi ini. Tekan ULANGI untuk menontonnya lagi.","Frames to join":"Frame untuk bergabung","Password sent":"Kata sandi dikirim",Never:"Tidak pernah","Session keys":"Kunci sesi","New every time":"Baru setiap kali",Next:"Selanjutnya","DHCP, for an IP address":"DHCP, untuk alamat IP","Find the Network":"Menemukan jaringan","A beacon, then a probe":"Beacon, lalu probe",'About ten times a second the router’s Wi-Fi sends a beacon: here is "HomeNet", protected with WPA2, on channel 36. The laptop could simply wait to hear one; to be quicker it also asks out loud with a probe request, and the access point answers with a probe response.':'Sekitar sepuluh kali per detik Wi-Fi router mengirim beacon: ini "HomeNet", dilindungi WPA2, di kanal 36. Laptop bisa saja menunggu sampai mendengarnya; agar lebih cepat ia juga bertanya dengan lantang lewat probe request, dan titik akses menjawab dengan probe response.',"WPA2-Personal (password)":"WPA2-Personal (kata sandi)",BEACON:"BEACON","WPA2 · channel 36":"WPA2 · kanal 36",PROBE:"PROBE","any networks here?":"ada jaringan di sini?","PROBE RESPONSE":"JAWABAN PROBE","Join the Network":"Bergabung ke jaringan","Two formalities: hello, then join":"Dua formalitas: halo, lalu bergabung","Open System authentication lets anyone this far: no password yet. Then the laptop asks to associate, repeating the security it chose (CCMP, with a password), and the access point gives it association ID 1. The laptop is connected, but the only thing it may send is the handshake that comes next.":"Autentikasi Open System membiarkan siapa saja sampai sejauh ini: belum ada kata sandi. Lalu laptop meminta asosiasi, mengulang keamanan yang dipilihnya (CCMP, dengan kata sandi), dan titik akses memberinya ID asosiasi 1. Laptop sudah terhubung, tetapi satu-satunya yang boleh dikirimnya adalah handshake berikutnya.",Authentication:"Autentikasi","Open System (no password)":"Open System (tanpa kata sandi)","Association ID":"ID asosiasi","Allowed so far":"Diizinkan sejauh ini",success:"berhasil",ASSOCIATE:"ASOSIASI",'join "HomeNet"':'bergabung ke "HomeNet"',"CCMP, password":"CCMP, kata sandi",ASSOCIATED:"TERASOSIASI","association ID 1":"ID asosiasi 1","Messages 1 and 2":"Pesan 1 dan 2","The 4-way handshake: nonces":"Handshake 4 arah: nonce","Both sides already hold the same key, worked out from the password and the network’s name (the PMK); it never goes over the air. The access point sends a random number, the ANonce. The laptop sends its own, the SNonce, with a check value (MIC). From the PMK, the two nonces and both MAC addresses, each side now works out the same session keys.":"Kedua pihak sudah memegang kunci yang sama, dihitung dari kata sandi dan nama jaringan (PMK); kunci itu tidak pernah melewati udara. Titik akses mengirim angka acak, ANonce. Laptop mengirim miliknya, SNonce, dengan nilai pemeriksa (MIC). Dari PMK, kedua nonce, dan kedua alamat MAC, tiap pihak kini menghitung kunci sesi yang sama.","Shared key":"Kunci bersama","PMK, from the password":"PMK, dari kata sandi",Exchanged:"Dipertukarkan","Two random nonces":"Dua nonce acak","Worked out":"Dihitung","Session keys (PTK)":"Kunci sesi (PTK)","MESSAGE 1":"PESAN 1","MESSAGE 2":"PESAN 2","Messages 3 and 4":"Pesan 3 dan 4","The 4-way handshake: keys":"Handshake 4 arah: kunci","Message 3 shows the access point has the same keys (its MIC checks out) and brings the group key (GTK) for broadcasts, encrypted. Message 4 says the laptop is ready, and both ends start encrypting.":"Pesan 3 menunjukkan bahwa titik akses punya kunci yang sama (MIC-nya cocok) dan membawa kunci grup (GTK) untuk siaran, dalam keadaan terenkripsi. Pesan 4 mengatakan laptop siap, dan kedua ujung mulai mengenkripsi.","Group key":"Kunci grup","GTK, sent encrypted":"GTK, dikirim terenkripsi",Install:"Pasang","Both ends at once":"Kedua ujung sekaligus","MESSAGE 3":"PESAN 3","group key, encrypted":"kunci grup, terenkripsi","MESSAGE 4":"PESAN 4","keys installed":"kunci terpasang","Encrypted Now":"Kini terenkripsi","And what a listener could still do":"Dan apa yang masih bisa dilakukan penyadap","Every data frame is encrypted now, like this first one carrying a DHCP Discover: anyone nearby sees only the MAC addresses and the size. But someone who recorded the four handshake messages can try password guesses at home, as fast as their computer allows: a guess is right when it gives the same MIC. A long, random password makes that hopeless; WPA3 removes the weakness.":"Setiap frame data kini terenkripsi, seperti frame pertama ini yang membawa DHCP Discover: orang di dekatnya hanya melihat alamat MAC dan ukurannya. Tetapi orang yang merekam empat pesan handshake bisa mencoba tebakan kata sandi di rumah, secepat yang dimungkinkan komputernya: tebakan benar jika menghasilkan MIC yang sama. Kata sandi yang panjang dan acak membuatnya sia-sia; WPA3 menghapus kelemahan itu.","Others see":"Orang lain melihat","MAC addresses, sizes, timing":"Alamat MAC, ukuran, waktu","Weak point":"Titik lemah","Offline password guessing":"Menebak kata sandi secara offline",Defence:"Pertahanan","A long password, or WPA3":"Kata sandi panjang, atau WPA3","DHCP Discover inside":"di dalamnya DHCP Discover","ENCRYPTED FROM HERE ON":"TERENKRIPSI MULAI DARI SINI","QoS Data (encrypted)":"QoS Data (terenkripsi)","Seen over the air, on Wi-Fi channel 36":"Terlihat di udara, di kanal Wi-Fi 36","Frame type":"Jenis frame","Management, Beacon":"Manajemen, Beacon",Duration:"Durasi","Nobody acknowledges a broadcast, so nothing is booked.":"Tidak ada yang membalas siaran, jadi tidak ada yang dipesan.",Receiver:"Penerima","Broadcast: every device in range listens.":"Siaran: setiap perangkat dalam jangkauan mendengarkan.",Transmitter:"Pengirim","The access point.":"Titik akses.","The access point’s own address: which network this is about.":"Alamat titik akses itu sendiri: jaringan mana yang dimaksud.","Lets the receiver spot a repeat when a frame is sent again.":"Membuat penerima bisa mengenali pengulangan saat frame dikirim lagi.","The access point’s clock; devices on the network keep theirs in step with it.":"Jam titik akses; perangkat di jaringan menyelaraskan jamnya dengan jam ini.","Beacon interval":"Interval beacon","A beacon goes out about ten times a second.":"Beacon keluar sekitar sepuluh kali per detik.","0x0011: access point network, encrypted":"0x0011: jaringan titik akses, terenkripsi","Privacy bit set: joining takes a key.":"Bit privasi menyala: bergabung butuh kunci.","The network’s name.":"Nama jaringan.","Supported rates":"Kecepatan yang didukung","Only the oldest, slowest rates; the fast ones are in the elements that follow.":"Hanya kecepatan paling tua dan paling lambat; yang cepat ada di elemen berikutnya.","DTIM count 0, period 1":"Hitungan DTIM 0, periode 1","Tells sleeping devices whether frames are waiting for them.":"Memberi tahu perangkat yang sedang tidur apakah ada frame yang menunggunya.","Robust Security Network: how this network is protected.":"Robust Security Network: bagaimana jaringan ini dilindungi.","Element ID, length":"ID elemen, panjang","48, 20 bytes":"48, 20 byte","Group cipher":"Sandi grup","Encrypts broadcasts, which every device on the network can read.":"Mengenkripsi siaran, yang bisa dibaca setiap perangkat di jaringan.","Pairwise cipher":"Sandi berpasangan","Encrypts each device’s own traffic, with keys only it and the access point have.":"Mengenkripsi lalu lintas tiap perangkat, dengan kunci yang hanya dimiliki perangkat itu dan titik akses.","Key management":"Manajemen kunci","1: PSK (a shared password)":"1: PSK (kata sandi bersama)","More elements":"Elemen lainnya","Wi-Fi 4, 5 and 6 capabilities and settings (HT, VHT, HE: channel 36, 80 MHz wide), and vendor extras.":"Kemampuan dan pengaturan Wi-Fi 4, 5, dan 6 (HT, VHT, HE: kanal 36, lebar 80 MHz), serta tambahan vendor.","Management, Probe Request":"Manajemen, Probe Request","The laptop’s Wi-Fi card.":"Kartu Wi-Fi laptop.","empty (any network)":"kosong (jaringan apa pun)","Any access point may answer. (Devices used to ask for every network they had joined by name, telling anyone listening where they had been.)":"Titik akses mana pun boleh menjawab. (Dulu perangkat menanyakan setiap jaringan yang pernah diikutinya dengan nama, memberi tahu siapa pun yang mendengar ke mana saja ia pernah pergi.)","What the laptop’s radio can do: Wi-Fi 4, 5 and 6 capabilities, and vendor extras.":"Kemampuan radio laptop: kemampuan Wi-Fi 4, 5, dan 6, serta tambahan vendor.","Management, Probe Response":"Manajemen, Probe Response","How long the channel stays booked for this exchange; other devices wait.":"Berapa lama kanal tetap dipesan untuk pertukaran ini; perangkat lain menunggu.","The radio this frame is for.":"Radio yang menjadi tujuan frame ini.","Authentication · Open System":"Autentikasi · Open System","Management, Authentication":"Manajemen, Authentication",Algorithm:"Algoritme","Open: anyone may get this far. The password is checked later, in the 4-way handshake.":"Terbuka: siapa saja boleh sampai sejauh ini. Kata sandi diperiksa nanti, dalam handshake 4 arah.",Transaction:"Transaksi","0 (success)":"0 (berhasil)","Management, Association Request":"Manajemen, Association Request","Listen interval":"Interval mendengar","10 beacons":"10 beacon","How often the laptop wakes to check for waiting frames when saving power.":"Seberapa sering laptop bangun untuk memeriksa frame yang menunggu saat menghemat daya.","What the laptop’s radio can do (Wi-Fi 4, 5 and 6), and vendor extras.":"Kemampuan radio laptop (Wi-Fi 4, 5, dan 6) serta tambahan vendor.","Management, Association Response":"Manajemen, Association Response","The laptop’s number at this access point (the top two bits are always set).":"Nomor laptop di titik akses ini (dua bit teratas selalu menyala).","The settings the access point uses (Wi-Fi 4, 5 and 6), and vendor extras.":"Pengaturan yang dipakai titik akses (Wi-Fi 4, 5, dan 6) serta tambahan vendor.","Data, QoS Data":"Data, QoS Data","0x02 (from the access point)":"0x02 (dari titik akses)","Sent by the access point itself.":"Dikirim oleh titik akses itu sendiri.","QoS control":"Kontrol QoS","Priority 7, the highest: the handshake goes first.":"Prioritas 7, yang tertinggi: handshake didahulukan.",Organization:"Organisasi","0x888e (802.1X authentication)":"0x888e (autentikasi 802.1X)","What follows: plays the part an Ethernet type field does on a cable.":"Yang mengikuti: berperan seperti kolom jenis Ethernet di kabel.","Descriptor type":"Jenis deskriptor","Key information":"Informasi kunci","0x008a: pairwise, ACK":"0x008a: berpasangan, ACK","ACK: the laptop must answer.":"ACK: laptop harus menjawab.","Key length":"Panjang kunci","The pairwise key is 16 bytes (AES-128).":"Kunci berpasangan panjangnya 16 byte (AES-128).","Replay counter":"Penghitung ulang","Counts up with each message from the access point; an old one sent again is ignored.":"Bertambah dengan setiap pesan dari titik akses; pesan lama yang dikirim ulang diabaikan.","A random number from the access point.":"Angka acak dari titik akses.","Key IV":"IV kunci",zeros:"nol","Key RSC":"RSC kunci","No keys yet, so nothing to check with.":"Belum ada kunci, jadi belum ada yang bisa diperiksa.","Key data length":"Panjang data kunci","0x01 (to the access point)":"0x01 (ke titik akses)","The access point itself.":"Titik akses itu sendiri.","0x010a: pairwise, MIC":"0x010a: berpasangan, MIC","MIC: this message carries a check value.":"MIC: pesan ini membawa nilai pemeriksa.","A random number from the laptop. From both numbers, both MAC addresses and the key that comes from the password, each side works out the same session keys.":"Angka acak dari laptop. Dari kedua angka, kedua alamat MAC, dan kunci yang berasal dari kata sandi, tiap pihak menghitung kunci sesi yang sama.","Worked out with the new keys: it proves the sender knows the password, and that the message wasn’t changed.":"Dihitung dengan kunci baru: membuktikan bahwa pengirim tahu kata sandi, dan bahwa pesan tidak diubah.","0x13ca: pairwise, install, ACK, MIC, secure, key data encrypted":"0x13ca: berpasangan, pasang, ACK, MIC, aman, data kunci terenkripsi","Install: start using the keys. The group key comes encrypted.":"Pasang: mulai memakai kunci. Kunci grup datang terenkripsi.","Where the group key’s packet numbers start.":"Tempat nomor paket kunci grup dimulai.","Key data":"Data kunci","Encrypted with a key from the handshake.":"Dienkripsi dengan kunci dari handshake.","The access point’s RSN element":"Elemen RSN titik akses","GTK: the group key, for broadcasts":"GTK: kunci grup, untuk siaran","0x030a: pairwise, MIC, secure":"0x030a: berpasangan, MIC, aman","Secure: the keys are in place.":"Aman: kunci sudah terpasang.","CCMP · encrypted":"CCMP · terenkripsi","0x41 (protected, to the access point)":"0x41 (terlindungi, ke titik akses)","Protected: what follows the header is encrypted.":"Terlindungi: yang mengikuti header terenkripsi.","Where the access point should pass it on to: everyone on the network.":"Ke mana titik akses harus meneruskannya: ke semua orang di jaringan.","CCMP header":"Header CCMP","packet number 1, key 0":"nomor paket 1, kunci 0","Counts up with every frame; one seen before is thrown away.":"Bertambah setiap frame; frame yang pernah terlihat dibuang.","LLC/SNAP: an IPv4 packet":"LLC/SNAP: paket IPv4","Shows any change to the frame.":"Menunjukkan setiap perubahan pada frame.","Safer Wi-Fi":"Wi-Fi lebih aman","WPA3 is the current Wi-Fi security standard. Its Personal mode keeps the simple shared password but changes how it is checked: SAE, a password exchange that no recording can attack offline, gives every connection a fresh key. It also makes protected management frames compulsory.":"WPA3 adalah standar keamanan Wi-Fi saat ini. Mode Personal-nya mempertahankan kata sandi bersama yang sederhana, tetapi mengubah cara memeriksanya: SAE, pertukaran kata sandi yang tidak bisa diserang secara offline dari rekaman mana pun, memberi setiap koneksi kunci baru. WPA3 juga mewajibkan frame manajemen yang terlindungi.","Password check":"Pemeriksaan sandi",Required:"Wajib","Protected management frames":"Frame manajemen terlindungi",Since:"Sejak","Connected with WPA3":"Terhubung dengan WPA3","Same password, better protocol":"Kata sandi sama, protokol lebih baik","The laptop and the access point proved to each other that they know the password without giving anyone a way to test guesses offline, then made fresh keys exactly as WPA2 does. Press REPLAY to watch it again.":"Laptop dan titik akses saling membuktikan bahwa mereka tahu kata sandinya tanpa memberi siapa pun cara menguji tebakan secara offline, lalu membuat kunci baru persis seperti WPA2. Tekan ULANGI untuk menontonnya lagi.","SAE frames":"Frame SAE","4 (commit, confirm)":"4 (commit, confirm)","4 EAPOL-Key frames":"4 frame EAPOL-Key","Offline guessing":"Tebakan offline","Not possible":"Tidak mungkin","Forged disconnects":"Pemutusan palsu",Ignored:"Diabaikan","A WPA3 Network":"Jaringan WPA3","The beacon asks for SAE":"Beacon meminta SAE","The beacon looks like WPA2’s with two changes in its RSN element: the key management is SAE instead of PSK, and protected management frames are required. Everyone still uses one shared password.":"Beacon tampak seperti milik WPA2 dengan dua perubahan di elemen RSN-nya: manajemen kuncinya SAE, bukan PSK, dan frame manajemen terlindungi diwajibkan. Semua orang tetap memakai satu kata sandi bersama.","Management frames":"Frame manajemen","Protected (required)":"Terlindungi (wajib)","Still one for everyone":"Tetap satu untuk semua","SAE Commit":"SAE Commit","Each side commits to the password":"Tiap pihak berkomitmen pada kata sandi","Instead of Open System authentication, the two sides run SAE, a password exchange between equals. Each picks a random secret and sends a scalar and an element worked out from that secret and the password. The password is the same on both sides, the secrets are not, so every connection ends up with a new key.":"Alih-alih autentikasi Open System, kedua pihak menjalankan SAE, pertukaran kata sandi antara pihak yang setara. Masing-masing memilih rahasia acak dan mengirim skalar dan elemen yang dihitung dari rahasia itu dan kata sandi. Kata sandinya sama di kedua pihak, rahasianya tidak, jadi setiap koneksi berakhir dengan kunci baru.","19 (256-bit curve)":"19 (kurva 256-bit)","Each sends":"Masing-masing mengirim","A scalar and an element":"Skalar dan elemen",Replaces:"Menggantikan","Open System authentication":"Autentikasi Open System",COMMIT:"COMMIT","scalar + element":"skalar + elemen","SAE Confirm":"SAE Confirm","Proof, without the password":"Bukti, tanpa kata sandi","Each side now works out the shared key and sends a confirm, a value only someone with the right password could produce. Recording all four SAE frames doesn’t let an attacker test guesses at home: every guess takes a live exchange with the access point, which can slow them down or shut them out.":"Kini tiap pihak menghitung kunci bersama dan mengirim confirm, nilai yang hanya bisa dibuat oleh orang yang punya kata sandi yang benar. Merekam keempat frame SAE tidak membuat penyerang bisa menguji tebakan di rumah: setiap tebakan butuh pertukaran langsung dengan titik akses, yang bisa memperlambat atau menutup aksesnya.","A new key (PMK) each time":"Kunci baru (PMK) setiap kali",Guessing:"Menebak","Live only, never offline":"Hanya langsung, tak pernah offline","Password leaks":"Kata sandi bocor","Past traffic stays safe":"Lalu lintas lama tetap aman",CONFIRM:"CONFIRM","proof of the key":"bukti kunci","Join, Handshake":"Bergabung, handshake","Then the 4-way handshake, as in WPA2":"Lalu handshake 4 arah, seperti di WPA2","Association works as before, repeating the choice of SAE. The 4-way handshake that follows is WPA2’s, starting from the key SAE just made, except that message 3 also brings the IGTK, a key that signs broadcast management frames.":"Asosiasi berjalan seperti sebelumnya, mengulang pilihan SAE. Handshake 4 arah berikutnya adalah milik WPA2, berangkat dari kunci yang baru dibuat SAE, kecuali bahwa pesan 3 juga membawa IGTK, kunci yang menandatangani frame manajemen siaran.","Message 3 adds":"Pesan 3 menambahkan","Why It’s Safer":"Mengapa lebih aman","Forged disconnects stop working":"Pemutusan palsu tidak lagi berhasil","With WPA2, anyone in range could forge a “disconnect” frame and knock a device off the network, often to record its handshake when it joined again. WPA3 requires protected management frames, so forged disconnects are ignored. Many routers also offer a transition mode that lets WPA2 devices join too; those devices keep WPA2’s weaknesses.":"Dengan WPA2, siapa saja dalam jangkauan bisa memalsukan frame “putuskan” dan menendang perangkat dari jaringan, sering kali untuk merekam handshake-nya saat bergabung lagi. WPA3 mewajibkan frame manajemen terlindungi, jadi pemutusan palsu diabaikan. Banyak router juga menawarkan mode transisi yang membiarkan perangkat WPA2 ikut bergabung; perangkat itu tetap punya kelemahan WPA2.",Protected:"Terlindungi","Disconnects, other management":"Pemutusan, manajemen lainnya","WPA2/3 mode":"Mode WPA2/3","WPA2 devices stay at risk":"Perangkat WPA2 tetap berisiko","Stronger still":"Lebih kuat lagi","WPA3-Enterprise (192-bit)":"WPA3-Enterprise (192-bit)","MANAGEMENT FRAMES PROTECTED":"FRAME MANAJEMEN TERLINDUNGI","0x00c0: management frame protection required":"0x00c0: perlindungan frame manajemen wajib","Disconnect messages and other management frames are signed, so they can’t be forged.":"Pesan pemutusan dan frame manajemen lainnya ditandatangani, jadi tidak bisa dipalsukan.","Authentication · SAE Commit":"Autentikasi · SAE Commit","Simultaneous Authentication of Equals: WPA3’s password exchange.":"Simultaneous Authentication of Equals: pertukaran kata sandi WPA3.","19 (256-bit elliptic curve)":"19 (kurva eliptik 256-bit)",Scalar:"Skalar","Worked out from a random secret and the password.":"Dihitung dari rahasia acak dan kata sandi.",Element:"Elemen","A point on the curve, also tied to the password. Recording the scalar and element doesn’t let anyone test password guesses afterwards.":"Sebuah titik di kurva, juga terikat pada kata sandi. Merekam skalar dan elemen tidak membuat siapa pun bisa menguji tebakan kata sandi sesudahnya.","Authentication · SAE Confirm":"Autentikasi · SAE Confirm","Proves this side worked out the same key, without giving it away.":"Membuktikan bahwa pihak ini menghitung kunci yang sama, tanpa membocorkannya.","0x0088: pairwise, ACK":"0x0088: berpasangan, ACK","0x0108: pairwise, MIC":"0x0108: berpasangan, MIC","0x13c8: pairwise, install, ACK, MIC, secure, key data encrypted":"0x13c8: berpasangan, pasang, ACK, MIC, aman, data kunci terenkripsi","IGTK: the key that signs broadcast management frames":"IGTK: kunci yang menandatangani frame manajemen siaran","0x0308: pairwise, MIC, secure":"0x0308: berpasangan, MIC, aman","Sign-In":"Login","From the router":"Dari router","From the test server":"Dari server uji","Hotel Router":"Router hotel","192.168.1.1 · captive portal":"192.168.1.1 · captive portal","Wi-Fi login pages":"Halaman login Wi-Fi","Hotels, cafés, airports and trains often put a login page in front of their Wi-Fi. Until you accept the terms (or pay), the router lets nothing out to the internet. It catches your device’s first plain HTTP request and answers it with a redirect to its own page; your device notices because a test page it knows comes back wrong.":"Hotel, kafe, bandara, dan kereta sering memasang halaman login di depan Wi-Fi mereka. Sampai Anda menerima ketentuannya (atau membayar), router tidak mengizinkan apa pun keluar ke internet. Router menangkap permintaan HTTP tak terenkripsi pertama dari perangkat Anda dan menjawabnya dengan pengalihan ke halamannya sendiri; perangkat Anda menyadarinya karena halaman uji yang dikenalnya kembali dengan jawaban yang salah.",Where:"Di mana","Hotels, cafés, airports":"Hotel, kafe, bandara",How:"Caranya","Catches plain HTTP requests":"Menangkap permintaan HTTP tak terenkripsi","Noticed by":"Diketahui lewat","Your system’s test page":"Halaman uji sistem Anda","Logging in":"Saat login","Lets your MAC address through":"Meloloskan alamat MAC Anda","Newer way":"Cara lebih baru","DHCP option 114 (RFC 8910)":"Opsi DHCP 114 (RFC 8910)","Described In":"Dijelaskan di",Online:"Online","Noticed, logged in, let through":"Terdeteksi, login, diloloskan","Windows asked a test page for an answer it knows and got a redirect instead, so it knew a portal was in the way and opened the login page. Once the terms were accepted, the router let the laptop through, and the same check came back right. Press REPLAY to watch it again.":"Windows meminta jawaban yang sudah dikenalnya dari sebuah halaman uji dan malah mendapat pengalihan, jadi ia tahu ada portal di tengah jalan dan membuka halaman login. Setelah ketentuan diterima, router meloloskan laptop, dan pemeriksaan yang sama kembali benar. Tekan ULANGI untuk menontonnya lagi.","A plain HTTP test page":"Halaman uji HTTP tak terenkripsi","Faked by":"Dipalsukan oleh","The router (TTL 64)":"Router (TTL 64)","Let through":"Diloloskan","The laptop’s MAC address":"Alamat MAC laptop","Open Wi-Fi":"Wi-Fi terbuka","Use HTTPS, or a VPN":"Pakai HTTPS, atau VPN","Joined, Offline":"Terhubung, offline","An address, but no way out":"Punya alamat, tapi tak bisa keluar","The laptop has joined the hotel’s Wi-Fi, which has no password, and got an address from the router by DHCP. The router answers the laptop itself and passes on its DNS lookups, but drops anything else bound for the internet until the guest has logged in. (An open network also means anyone nearby can read whatever isn’t protected by HTTPS.)":"Laptop sudah bergabung ke Wi-Fi hotel yang tanpa kata sandi dan mendapat alamat dari router lewat DHCP. Router menjawab laptop sendiri dan meneruskan pencarian DNS-nya, tetapi membuang semua hal lain yang menuju internet sampai tamu login. (Jaringan terbuka juga berarti siapa pun di dekatnya bisa membaca apa saja yang tidak dilindungi HTTPS.)","192.168.1.10 (by DHCP)":"192.168.1.10 (lewat DHCP)","Wi-Fi password":"Kata sandi Wi-Fi","None (open network)":"Tidak ada (jaringan terbuka)","Blocked until you log in":"Diblokir sampai login","CONNECTED, NO INTERNET YET":"TERHUBUNG, BELUM ADA INTERNET","Internet Check":"Cek internet","Windows checks a test page":"Windows memeriksa halaman uji",'After joining any network, Windows looks up www.msftconnecttest.com (the router passes the lookup on) and asks it for /connecttest.txt over plain HTTP; the right answer is the text "Microsoft Connect Test". The router catches the connection and answers the handshake itself, in the test server’s name. The laptop can’t tell yet.':'Setelah bergabung ke jaringan mana pun, Windows mencari www.msftconnecttest.com (router meneruskan pencariannya) dan meminta /connecttest.txt lewat HTTP tak terenkripsi; jawaban yang benar adalah teks "Microsoft Connect Test". Router menangkap koneksi itu dan menjawab handshake-nya sendiri, atas nama server uji. Laptop belum bisa mengetahuinya.',"Test page":"Halaman uji","msftconnecttest.com/connecttest.txt":"msftconnecttest.com/connecttest.txt",Expected:"Diharapkan","Answered by":"Dijawab oleh","The router, posing as the server":"Router, yang menyamar sebagai server",'from "203.0.113.30"':'dari "203.0.113.30"',"/connecttest.txt":"/connecttest.txt",Redirected:"Dialihkan","The wrong answer gives it away":"Jawaban yang salah membongkarnya",'Instead of the test text, the "server" answers 302 Found, pointing to the router’s login page. Its TTL is 64, not lowered at all, because it came straight from the router. Windows sees the wrong answer, marks the network as needing action and opens the browser, whose first request the router redirects the same way, to its login page. This only works with plain HTTP: the router can’t fake an HTTPS page without a certificate error.':'Alih-alih teks uji, "server" menjawab 302 Found, yang menunjuk ke halaman login router. TTL-nya 64, sama sekali tidak berkurang, karena datang langsung dari router. Windows melihat jawaban yang salah, menandai jaringan sebagai perlu tindakan, dan membuka browser, yang permintaan pertamanya dialihkan router dengan cara yang sama ke halaman loginnya. Ini hanya berhasil dengan HTTP tak terenkripsi: router tidak bisa memalsukan halaman HTTPS tanpa galat sertifikat.',"302 → 192.168.1.1/login":"302 → 192.168.1.1/login","Give-away":"Petunjuknya","TTL 64, from one hop away":"TTL 64, dari satu hop","Why HTTP":"Mengapa HTTP","HTTPS can’t be faked":"HTTPS tak bisa dipalsukan","302 FOUND":"302 FOUND","ACTION NEEDED":"PERLU TINDAKAN","The Login Page":"Halaman login","Served by the router itself":"Disajikan oleh router sendiri","The browser opens http://192.168.1.1/login, a page the router serves itself: the hotel’s name, the terms of use and an Accept button. This connection really does go to the router.":"Browser membuka http://192.168.1.1/login, halaman yang disajikan router sendiri: nama hotel, ketentuan penggunaan, dan tombol Terima. Koneksi ini benar-benar menuju router.",Page:"Halaman","http://192.168.1.1/login":"http://192.168.1.1/login","Served by":"Disajikan oleh","The router":"Router",Size:"Ukuran","2,400 bytes of HTML":"2,400 byte HTML","/login":"/login","the login page":"halaman login","Accept the Terms":"Terima ketentuan","The router lets the laptop out":"Router meloloskan laptop","Clicking Accept posts a small form back to the router. It adds the laptop’s MAC address to the list of devices allowed out, often for the length of the stay, and redirects the browser on its way.":"Mengeklik Terima mengirim formulir kecil ke router. Router menambahkan alamat MAC laptop ke daftar perangkat yang boleh keluar, sering kali selama masa menginap, lalu mengalihkan browser ke tujuannya.",Form:"Formulir","terms=accepted":"terms=accepted","Router allows":"Router mengizinkan","302 to where you were going":"302 ke tujuan Anda semula","you’re online":"Anda sudah online","MAC ADDRESS ALLOWED":"ALAMAT MAC DIIZINKAN","The same check, now real":"Pemeriksaan yang sama, kini sungguhan","Windows checks again. This time the router lets the connection through to the real test server, twelve routers away (its replies arrive with TTL 52), and the answer is the expected text. The network is marked as connected to the internet.":"Windows memeriksa lagi. Kali ini router meloloskan koneksi ke server uji yang sebenarnya, dua belas router jauhnya (balasannya tiba dengan TTL 52), dan jawabannya adalah teks yang diharapkan. Jaringan ditandai terhubung ke internet.","Connected to the internet":"Terhubung ke internet",ONLINE:"ONLINE","www.msftconnecttest.com, type A, class IN":"www.msftconnecttest.com, tipe A, kelas IN","www.msftconnecttest.com A 203.0.113.30 (TTL 46 s)":"www.msftconnecttest.com A 203.0.113.30 (TTL 46 s)","Sent with 64 and not lowered at all: it came from the router next door, not from a server 12 routers away.":"Dikirim dengan 64 dan sama sekali tidak berkurang: datang dari router di sebelah, bukan dari server 12 router jauhnya.","2,400 bytes: the login page":"2,400 byte: halaman login","Via a Proxy":"Lewat proxy","TLS, through the tunnel":"TLS, lewat terowongan","Forward proxy, and CONNECT for HTTPS":"Proxy maju, dan CONNECT untuk HTTPS","A forward proxy fetches web pages on your behalf. Companies and schools use one to filter sites, keep copies of popular pages and log what goes out; the sites you visit see the proxy, not you. Plain HTTP passes through it in the clear. For HTTPS the browser asks the proxy for a tunnel, and the encrypted connection runs through it unread.":"Proxy maju mengambil halaman web atas nama Anda. Perusahaan dan sekolah memakainya untuk menyaring situs, menyimpan salinan halaman populer, dan mencatat apa yang keluar; situs yang Anda kunjungi melihat proxy, bukan Anda. HTTP tak terenkripsi melewatinya secara terbuka. Untuk HTTPS, browser meminta proxy membuat terowongan, dan koneksi terenkripsi melewatinya tanpa dibaca.","Common ports":"Port umum","http:// pages":"Halaman http://","Fetched by the proxy":"Diambil oleh proxy","https:// pages":"Halaman https://","Tunnelled with CONNECT":"Lewat terowongan CONNECT","Used for":"Dipakai untuk","Filtering, caching, logging":"Menyaring, menyimpan cache, mencatat","Two ways through":"Dua jalan lewat","Fetched for you, or tunnelled":"Diambilkan untuk Anda, atau lewat terowongan","For the plain page, the proxy did the work: it read the request, fetched the page on its own connection and could have kept, changed or refused it. For HTTPS it only opened a tunnel and copied encrypted bytes, knowing nothing but the site’s name. Press REPLAY to watch it again.":"Untuk halaman tak terenkripsi, proxy yang bekerja: ia membaca permintaan, mengambil halaman lewat koneksinya sendiri, dan bisa saja menyimpan, mengubah, atau menolaknya. Untuk HTTPS ia hanya membuka terowongan dan menyalin byte terenkripsi, tanpa tahu apa pun selain nama situsnya. Tekan ULANGI untuk menontonnya lagi.","Server sees":"Server melihat","The proxy (192.0.2.80)":"Proxy (192.0.2.80)","Plain HTTP":"HTTP tak terenkripsi","The proxy reads it all":"Proxy membaca semuanya","Name and sizes only":"Hanya nama dan ukuran","DNS for the site":"DNS untuk situs","Done by the proxy":"Dilakukan proxy","Proxy Settings":"Pengaturan proxy","The browser sends everything there":"Browser mengirim semuanya ke sana","The browser is set to send everything through a proxy at 192.0.2.80, port 8080, as many companies and schools require. You open http://www.example.com. The browser doesn’t look up www.example.com itself: it connects to the proxy and leaves the rest to it.":"Browser diatur untuk mengirim semuanya lewat proxy di 192.0.2.80, port 8080, seperti yang diwajibkan banyak perusahaan dan sekolah. Anda membuka http://www.example.com. Browser tidak mencari www.example.com sendiri: ia terhubung ke proxy dan menyerahkan sisanya.","Left to the proxy":"Diserahkan ke proxy","To the Proxy":"Ke proxy","TCP to port 8080":"TCP ke port 8080","The laptop opens an ordinary TCP connection, not to the website, but to the proxy’s port 8080.":"Laptop membuka koneksi TCP biasa, bukan ke situs web, tetapi ke port 8080 milik proxy.","192.0.2.80, port 8080":"192.0.2.80, port 8080","Not to":"Bukan ke","The Whole URL":"URL lengkap","Sent to a proxy, the request line carries the whole address, not just the path: GET http://www.example.com/ HTTP/1.1. That is how the proxy knows where to go. Chrome adds Proxy-Connection: keep-alive, a header only proxies read.":"Saat dikirim ke proxy, baris permintaan membawa alamat lengkap, bukan hanya path-nya: GET http://www.example.com/ HTTP/1.1. Dengan itulah proxy tahu harus ke mana. Chrome menambahkan Proxy-Connection: keep-alive, header yang hanya dibaca proxy.","Request line":"Baris permintaan","To a server":"Ke server","Readable by":"Bisa dibaca oleh","The proxy (plain HTTP)":"Proxy (HTTP tak terenkripsi)","to the proxy":"ke proxy","Proxy Fetches It":"Proxy mengambilnya","Its own connection to the server":"Koneksinya sendiri ke server","The proxy looks up www.example.com itself (not shown) and opens its own connection to the server. Its request is the ordinary kind, GET /, with headers of its own: Via names the proxy, and X-Forwarded-For gives the address the request came from (the home router’s public address, since the laptop is behind NAT).":"Proxy mencari www.example.com sendiri (tidak ditampilkan) dan membuka koneksinya sendiri ke server. Permintaannya yang biasa, GET /, dengan header miliknya sendiri: Via menyebut proxy, dan X-Forwarded-For memberi alamat asal permintaan (alamat publik router rumah, karena laptop berada di balik NAT).","The proxy’s own":"Milik proxy sendiri","1.1 proxy.example.net":"1.1 proxy.example.net","Forwarded for":"Diteruskan untuk","Page Passed On":"Halaman diteruskan","The page, passed on":"Halaman, diteruskan","The server answers the proxy, and the proxy passes the page on to the laptop with a Via header of its own. It could keep a copy and give it to the next person who asks without troubling the server (X-Cache: MISS says it had none yet), and it can refuse sites that aren’t allowed.":"Server menjawab proxy, dan proxy meneruskan halaman ke laptop dengan header Via miliknya sendiri. Proxy bisa menyimpan salinan dan memberikannya ke orang berikutnya yang meminta tanpa merepotkan server (X-Cache: MISS berarti belum ada salinan), dan bisa menolak situs yang tidak diizinkan.","The proxy, not the laptop":"Proxy, bukan laptop",Cache:"Cache","MISS (first request)":"MISS (permintaan pertama)","Proxy can":"Proxy bisa","Cache, filter, log, change":"Cache, filter, catat, ubah","CONNECT www.example.com:443":"CONNECT www.example.com:443","Now you open https://www.example.com. A proxy can’t fetch an HTTPS page for you without breaking its encryption, so the browser asks for a tunnel instead: CONNECT www.example.com:443. The proxy opens a TCP connection to port 443 and answers 200 Connection established.":"Sekarang Anda membuka https://www.example.com. Proxy tidak bisa mengambil halaman HTTPS untuk Anda tanpa membobol enkripsinya, jadi browser meminta terowongan: CONNECT www.example.com:443. Proxy membuka koneksi TCP ke port 443 dan menjawab 200 Connection established.","Proxy opens":"Proxy membuka","TCP to port 443":"TCP ke port 443","200 Connection established":"200 Connection established","Connection established":"Koneksi terjalin","In the Tunnel":"Di dalam terowongan","The proxy copies, unread":"Proxy menyalin tanpa membaca","From now on the proxy copies bytes both ways without reading them. The browser’s TLS Client Hello goes in on the laptop’s connection and comes out, byte for byte the same, on the proxy’s connection to the server. TLS runs from end to end, so the proxy learns the site’s name and the sizes, never the pages. (Some company proxies do open HTTPS, using a certificate authority installed on every company laptop; then they see everything.)":"Mulai sekarang proxy menyalin byte ke dua arah tanpa membacanya. Client Hello TLS dari browser masuk lewat koneksi laptop dan keluar, sama persis byte demi byte, lewat koneksi proxy ke server. TLS berjalan dari ujung ke ujung, jadi proxy mengetahui nama situs dan ukurannya, tidak pernah halamannya. (Sebagian proxy kantor memang membuka HTTPS, memakai otoritas sertifikat yang dipasang di setiap laptop kantor; dengan begitu mereka melihat semuanya.)","Proxy sees":"Proxy melihat","Site name, sizes, timing":"Nama situs, ukuran, waktu","Hidden from it":"Tersembunyi darinya","Pages, passwords, cookies":"Halaman, kata sandi, cookie","TLS, laptop to server":"TLS, laptop ke server","the same bytes":"byte yang sama","COPIES BYTES, CAN’T READ THEM":"MENYALIN BYTE, TAK BISA MEMBACANYA","Any Connection":"Koneksi apa pun","From the proxy":"Dari proxy","SOCKS Proxy":"Proxy SOCKS","Socket Secure, version 5":"Socket Secure, versi 5","SOCKS is a general-purpose proxy. Where an HTTP proxy understands web requests, a SOCKS proxy simply opens a connection on your behalf and copies the bytes, whatever the protocol: web, email, games, SSH. Apps use it to reach a network through one gateway, or to hide their own address; ssh -D and Tor both offer one.":"SOCKS adalah proxy serbaguna. Jika proxy HTTP memahami permintaan web, proxy SOCKS sekadar membuka koneksi atas nama Anda dan menyalin byte-nya, apa pun protokolnya: web, email, game, SSH. Aplikasi memakainya untuk menjangkau jaringan lewat satu gateway, atau untuk menyembunyikan alamatnya sendiri; ssh -D dan Tor sama-sama menyediakannya.","Session (Layer 5)":"Sesi (Lapisan 5)","Any TCP, and UDP":"TCP apa pun, dan UDP",Logins:"Login","None, or user and password":"Tidak ada, atau nama pengguna dan kata sandi","Offered by":"Disediakan oleh","ssh -D, Tor, proxy servers":"ssh -D, Tor, server proxy","Tunnel open":"Terowongan terbuka","A few bytes, then just copying":"Beberapa byte, lalu hanya menyalin","Four tiny messages told the proxy where to connect; after that it only copied bytes. The website saw the proxy’s address, and because the laptop sent a name rather than an address, even the DNS lookup happened at the proxy. Press REPLAY to watch it again.":"Empat pesan kecil memberi tahu proxy ke mana harus terhubung; setelah itu proxy hanya menyalin byte. Situs web melihat alamat proxy, dan karena laptop mengirim nama, bukan alamat, bahkan pencarian DNS pun terjadi di proxy. Tekan ULANGI untuk menontonnya lagi.","4 messages, 37 bytes":"4 pesan, 37 byte","DNS lookup":"Pencarian DNS","At the proxy":"Di proxy","Only the TLS inside":"Hanya TLS di dalamnya","TCP to port 1080":"TCP ke port 1080","An app set to use a SOCKS proxy (a browser, a game launcher, or a tunnel made with ssh -D) opens a TCP connection to it, port 1080. SOCKS doesn’t care what will travel inside: it can carry any TCP connection.":"Aplikasi yang disetel untuk memakai proxy SOCKS (browser, peluncur game, atau terowongan yang dibuat dengan ssh -D) membuka koneksi TCP ke proxy itu, port 1080. SOCKS tidak peduli apa yang akan lewat di dalamnya: ia bisa membawa koneksi TCP apa pun.","Any TCP connection":"Koneksi TCP apa pun","Wants to reach":"Ingin menjangkau","https://www.example.com":"https://www.example.com","Version 5, and how to log in":"Versi 5, dan cara login","The laptop sends three bytes: version 5, one login method offered, and that method, 0: no login. The proxy answers with two: version 5, method 0. Had it chosen method 2, the app would next send a user name and password, in plain text.":"Laptop mengirim tiga byte: versi 5, satu metode login yang ditawarkan, dan metode itu, 0: tanpa login. Proxy menjawab dengan dua: versi 5, metode 0. Seandainya ia memilih metode 2, aplikasi berikutnya akan mengirim nama pengguna dan kata sandi, dalam teks biasa.","Laptop sends":"Laptop mengirim","05 01 00 (3 bytes)":"05 01 00 (3 byte)","Proxy answers":"Proxy menjawab","05 00 (2 bytes)":"05 00 (2 byte)","None needed here":"Tidak perlu di sini",GREETING:"SALAM","no login, please":"tanpa login, ya",METHOD:"METODE","no login needed":"tidak perlu login","Where To?":"Ke mana?","Connect to www.example.com:443":"Hubungkan ke www.example.com:443","The laptop asks the proxy to connect to www.example.com, port 443. It gives the name rather than an address, so the proxy does the DNS lookup and the laptop needs none. The proxy opens its own TCP connection to the server, then replies: succeeded, and the address and port it connected from.":"Laptop meminta proxy terhubung ke www.example.com, port 443. Ia memberikan nama, bukan alamat, jadi proxy yang melakukan pencarian DNS dan laptop tidak perlu sama sekali. Proxy membuka koneksi TCP-nya sendiri ke server, lalu menjawab: berhasil, beserta alamat dan port asal koneksinya.","www.example.com (a name)":"www.example.com (sebuah nama)","Succeeded, from 192.0.2.80:40220":"Berhasil, dari 192.0.2.80:40220",SUCCEEDED:"BERHASIL","from 192.0.2.80:40220":"dari 192.0.2.80:40220","Copied both ways, unread":"Disalin ke dua arah, tanpa dibaca","Now the proxy just copies. The app starts TLS with the server: its Client Hello goes in on the laptop’s connection and comes out unchanged on the proxy’s, and the server’s answer comes back the same way. The server only ever sees the proxy’s address; the proxy sees only encrypted bytes.":"Sekarang proxy hanya menyalin. Aplikasi memulai TLS dengan server: Client Hello-nya masuk lewat koneksi laptop dan keluar tanpa berubah lewat koneksi proxy, dan jawaban server kembali lewat jalan yang sama. Server hanya pernah melihat alamat proxy; proxy hanya melihat byte terenkripsi.","The proxy’s address":"Alamat proxy","Encrypted bytes":"Byte terenkripsi","Same bytes":"Byte yang sama","On both connections":"Di kedua koneksi",unchanged:"tanpa berubah","+ encrypted handshake":"+ handshake terenkripsi","Version 5, 1 method: no login":"Versi 5, 1 metode: tanpa login","Version 5, method chosen: no login":"Versi 5, metode dipilih: tanpa login","Succeeded, bound to 192.0.2.80:40220":"Berhasil, terikat ke 192.0.2.80:40220","SOCKS5 · greeting":"SOCKS5 · salam","Methods offered":"Metode yang ditawarkan","0 (no login)":"0 (tanpa login)","SOCKS5 · method chosen":"SOCKS5 · metode dipilih","Method chosen":"Metode dipilih","SOCKS5 · connect request":"SOCKS5 · permintaan koneksi","Open a TCP connection on my behalf.":"Buka koneksi TCP atas nama saya.","Address type":"Jenis alamat","3 (domain name)":"3 (nama domain)","The proxy looks the name up itself, so the laptop needs no DNS lookup of its own.":"Proxy mencari nama itu sendiri, jadi laptop tidak perlu melakukan pencarian DNS sendiri.","SOCKS5 · reply":"SOCKS5 · balasan","0 (succeeded)":"0 (berhasil)","The address the proxy connects from.":"Alamat asal koneksi proxy.",Offloading:"Offloading","Reverse Proxy":"Reverse proxy","TLS (SSL) offloading":"Offloading TLS (SSL)","A reverse proxy stands in front of a website’s servers: visitors connect to it, and it passes their requests on to an app server behind it. It can spread the load over many servers, keep copies of pages and turn away attacks. Often it also does the TLS work, decrypting HTTPS at the edge so the servers behind it speak plain HTTP. That is SSL (or TLS) offloading.":"Reverse proxy berdiri di depan server-server sebuah situs web: pengunjung terhubung kepadanya, dan ia meneruskan permintaan mereka ke server aplikasi di belakangnya. Ia bisa membagi beban ke banyak server, menyimpan salinan halaman, dan menangkis serangan. Sering kali ia juga mengerjakan TLS, mendekripsi HTTPS di tepi sehingga server di belakangnya berbicara HTTP tak terenkripsi. Itulah offloading SSL (atau TLS).","Visitors reach":"Pengunjung menjangkau","The proxy, never the app":"Proxy, tidak pernah aplikasinya","TLS ends":"TLS berakhir","At the proxy (offloading)":"Di proxy (offloading)","Plain HTTP (or TLS again)":"HTTP tak terenkripsi (atau TLS lagi)",Adds:"Menambahkan","For example":"Misalnya","nginx, HAProxy, cloud LBs":"nginx, HAProxy, load balancer cloud","Served from the edge":"Dilayani dari tepi","Encrypted outside, plain inside":"Terenkripsi di luar, terbuka di dalam","The laptop saw one HTTPS website. Behind it, the reverse proxy decrypted the request, asked an app server in plain HTTP over the private network and encrypted the answer for the trip back. Press REPLAY to watch it again.":"Laptop melihat satu situs web HTTPS. Di belakangnya, reverse proxy mendekripsi permintaan, meminta ke server aplikasi dengan HTTP tak terenkripsi lewat jaringan privat, dan mengenkripsi jawabannya untuk perjalanan pulang. Tekan ULANGI untuk menontonnya lagi.","Laptop ↔ proxy only":"Hanya laptop ↔ proxy","App learns visitor":"Aplikasi tahu pengunjung","From X-Forwarded-For":"Dari X-Forwarded-For","Certificate kept":"Sertifikat disimpan","On the proxy":"Di proxy","The Front Door":"Pintu depan","The proxy holds the certificate":"Proxy memegang sertifikat","The laptop opens https://www.example.com. The address DNS gives for the name belongs to the reverse proxy, which holds the site’s certificate and does the TLS handshake. Nothing tells the laptop there is another server behind it.":"Laptop membuka https://www.example.com. Alamat yang diberikan DNS untuk nama itu milik reverse proxy, yang memegang sertifikat situs dan melakukan handshake TLS. Tidak ada yang memberi tahu laptop bahwa ada server lain di belakangnya.","Laptop connects to":"Laptop terhubung ke","On the reverse proxy":"Di reverse proxy","Also called":"Disebut juga","Load balancer, edge":"Load balancer, tepi","TLS Ends Here":"TLS berakhir di sini","Offloading: the proxy does the TLS work":"Offloading: proxy mengerjakan TLS","The request arrives encrypted, and the reverse proxy decrypts it. That is the offloading: the TLS work is done here, once, instead of on every app server. Now the proxy can read the URL, headers and cookies, and pick a server by them.":"Permintaan tiba terenkripsi, dan reverse proxy mendekripsinya. Itulah offloading: pekerjaan TLS dilakukan di sini, sekali, bukan di setiap server aplikasi. Sekarang proxy bisa membaca URL, header, dan cookie, lalu memilih server berdasarkan itu.","At the reverse proxy":"Di reverse proxy","Proxy can read":"Proxy bisa membaca","URL, headers, cookies":"URL, header, cookie","Then picks":"Lalu memilih","An app server":"Sebuah server aplikasi","TLS ENDS HERE":"TLS BERAKHIR DI SINI","In the Clear":"Tanpa enkripsi","Passed on to the app server":"Diteruskan ke server aplikasi","The proxy passes the request on over the data centre’s private network, as plain HTTP to port 8080. It adds X-Forwarded-For, the visitor’s address, and X-Forwarded-Proto: https, how the visitor came in; otherwise the app would see only the proxy. Anyone able to watch this private network could read it all.":"Proxy meneruskan permintaan lewat jaringan privat pusat data, sebagai HTTP tak terenkripsi ke port 8080. Ia menambahkan X-Forwarded-For, alamat pengunjung, dan X-Forwarded-Proto: https, cara pengunjung masuk; tanpa itu aplikasi hanya akan melihat proxy. Siapa pun yang bisa mengamati jaringan privat ini bisa membaca semuanya.","The App Answers":"Aplikasi menjawab","In plain HTTP too":"Juga dengan HTTP tak terenkripsi","The app server builds the page and answers the proxy, in plain HTTP: it never deals with TLS or certificates at all.":"Server aplikasi menyusun halaman dan menjawab proxy dengan HTTP tak terenkripsi: ia tidak pernah berurusan dengan TLS atau sertifikat sama sekali.","text/html, 12,500 bytes":"text/html, 12,500 byte","readable inside":"terbaca di dalam","Encrypted Again":"Dienkripsi lagi","An ordinary HTTPS answer":"Jawaban HTTPS biasa","The reverse proxy encrypts the answer in the TLS session it holds with the laptop and sends it on. From outside, it is an ordinary HTTPS site.":"Reverse proxy mengenkripsi jawaban dalam sesi TLS yang ia pegang dengan laptop lalu mengirimkannya. Dari luar, ini situs HTTPS biasa.","Laptop sees":"Laptop melihat","One HTTPS server":"Satu server HTTPS","App servers":"Server aplikasi","Never handle TLS":"Tak pernah mengurus TLS",Certificates:"Sertifikat","Renewed in one place":"Diperbarui di satu tempat","Three Options":"Tiga pilihan","Offload, re-encrypt or pass through":"Offload, enkripsi ulang, atau teruskan","Offloading, as here, is simple and fast but leaves the inside traffic readable. Re-encrypting opens a second TLS connection from the proxy to the app server, so it stays encrypted inside too. Passing through forwards the TLS bytes without opening them: the certificate lives on the app servers, and the proxy can only choose a server by address and the name in the Client Hello, not by URL.":"Offloading, seperti di sini, sederhana dan cepat tetapi membuat lalu lintas di dalam bisa dibaca. Enkripsi ulang membuka koneksi TLS kedua dari proxy ke server aplikasi, jadi di dalam pun tetap terenkripsi. Meneruskan apa adanya mengirim byte TLS tanpa membukanya: sertifikat berada di server aplikasi, dan proxy hanya bisa memilih server berdasarkan alamat dan nama di Client Hello, bukan berdasarkan URL.",Offload:"Offload","Plain HTTP inside":"HTTP tak terenkripsi di dalam","Re-encrypt":"Enkripsi ulang","TLS inside as well":"TLS juga di dalam","Pass through":"Teruskan","Proxy can’t read it":"Proxy tak bisa membacanya","PLAIN HTTP INSIDE":"HTTP TAK TERENKRIPSI DI DALAM","A Modern VPN":"VPN modern","WireGuard (encrypted)":"WireGuard (terenkripsi)","TCP beyond the VPN":"TCP di luar VPN",Keepalive:"Keepalive","VPN Server":"Server VPN","A VPN carries your traffic inside an encrypted tunnel to a VPN server, which sends it on to the internet. On a café’s Wi-Fi, others see only encrypted packets going to the VPN server; websites see the VPN server’s address instead of yours. WireGuard is a modern VPN: a small amount of code, one fixed set of modern algorithms and a handshake of two messages.":"VPN membawa lalu lintas Anda di dalam terowongan terenkripsi ke server VPN, yang meneruskannya ke internet. Di Wi-Fi kafe, orang lain hanya melihat paket terenkripsi menuju server VPN; situs web melihat alamat server VPN, bukan alamat Anda. WireGuard adalah VPN modern: kodenya sedikit, satu set algoritme modern yang tetap, dan handshake dua pesan.","UDP (51820 by default)":"UDP (bawaan 51820)","2 messages, 1 round trip":"2 pesan, 1 kali bolak-balik",Crypto:"Kripto",Identity:"Identitas","Public keys, like SSH":"Kunci publik, seperti SSH","The WireGuard whitepaper":"Whitepaper WireGuard","Tunnel up":"Terowongan aktif","Encrypted to the VPN, plain beyond it":"Terenkripsi sampai VPN, terbuka setelahnya","Two handshake messages made the keys. After that every packet the laptop sent was sealed whole inside a UDP packet to the VPN server, and the website saw only the VPN server’s address. Beyond the VPN server traffic is no better protected than without one, so HTTPS still matters. Press REPLAY to watch it again.":"Dua pesan handshake membuat kunci. Setelah itu setiap paket yang dikirim laptop disegel utuh di dalam paket UDP ke server VPN, dan situs web hanya melihat alamat server VPN. Setelah server VPN, lalu lintas tidak lebih terlindungi daripada tanpa VPN, jadi HTTPS tetap penting. Tekan ULANGI untuk menontonnya lagi.","Others nearby see":"Orang sekitar melihat","UDP to 192.0.2.51":"UDP ke 192.0.2.51","Websites see":"Situs web melihat","The VPN server":"Server VPN","Beyond the VPN":"Setelah VPN","Only HTTPS protects":"Hanya HTTPS yang melindungi",Overhead:"Overhead","60 bytes + padding":"60 byte + padding","Set Up Once":"Disiapkan sekali","Keys, not passwords":"Kunci, bukan kata sandi","The laptop runs the WireGuard app with a short configuration: its own private key, the server’s public key and address (192.0.2.51, UDP port 51820), and AllowedIPs = 0.0.0.0/0, which means everything goes through the tunnel. Inside the tunnel the laptop’s address is 10.8.0.2.":"Laptop menjalankan aplikasi WireGuard dengan konfigurasi singkat: kunci privatnya sendiri, kunci publik dan alamat server (192.0.2.51, port UDP 51820), dan AllowedIPs = 0.0.0.0/0, yang berarti semuanya lewat terowongan. Di dalam terowongan, alamat laptop adalah 10.8.0.2.","Inside address":"Alamat di dalam","Through the tunnel":"Lewat terowongan","Everything (0.0.0.0/0)":"Semuanya (0.0.0.0/0)","TUNNEL ADDRESS 10.8.0.2":"ALAMAT TEROWONGAN 10.8.0.2","Two messages, one round trip":"Dua pesan, satu kali bolak-balik","When the laptop first has something to send, it starts a handshake: 148 bytes with a fresh public key, its own long-term key (encrypted, so only the server learns who is calling) and the time (encrypted, so a recording can’t be replayed). The server answers only keys it knows, here with 92 bytes. One round trip, and both sides have new session keys.":"Saat laptop pertama kali punya sesuatu untuk dikirim, ia memulai handshake: 148 byte berisi kunci publik baru, kunci jangka panjangnya sendiri (terenkripsi, jadi hanya server yang tahu siapa yang memanggil) dan waktu (terenkripsi, jadi rekaman tidak bisa diputar ulang). Server hanya menjawab kunci yang ia kenal, di sini dengan 92 byte. Satu kali bolak-balik, dan kedua pihak punya kunci sesi baru.",Initiation:"Inisiasi","Server answers":"Server menjawab","Only keys it knows":"Hanya kunci yang dikenal",INITIATION:"INISIASI","fresh key + identity":"kunci baru + identitas",RESPONSE:"RESPONS","keys agreed":"kunci disepakati","Into the Tunnel":"Masuk terowongan","A packet inside a packet":"Paket di dalam paket","You open https://www.example.com; its address was looked up through the tunnel too (not shown). The first packet of the connection, a TCP SYN from 10.8.0.2 to the web server, is encrypted whole and sent inside a UDP packet to the VPN server. On the café’s Wi-Fi only the outer packet shows: from the laptop to 192.0.2.51, port 51820.":"Anda membuka https://www.example.com; alamatnya juga dicari lewat terowongan (tidak ditampilkan). Paket pertama koneksi, TCP SYN dari 10.8.0.2 ke server web, dienkripsi utuh dan dikirim di dalam paket UDP ke server VPN. Di Wi-Fi kafe hanya paket luar yang terlihat: dari laptop ke 192.0.2.51, port 51820.",Outside:"Di luar","UDP to 192.0.2.51:51820":"UDP ke 192.0.2.51:51820","inside: TCP SYN to :443":"di dalam: TCP SYN ke :443","Out to the Web":"Keluar ke web","Decrypted, then sent on":"Didekripsi, lalu diteruskan","The VPN server decrypts the packet, swaps 10.8.0.2 for its own public address (NAT) and sends the SYN on, one hop older (TTL 127). The SYN offers a maximum segment of 1380 bytes, not 1460: the tunnel adds 60 bytes to every packet. The web server sees a visitor at 192.0.2.51 and answers there.":"Server VPN mendekripsi paket, menukar 10.8.0.2 dengan alamat publiknya sendiri (NAT) dan meneruskan SYN, satu hop lebih tua (TTL 127). SYN menawarkan segmen maksimum 1380 byte, bukan 1460: terowongan menambahkan 60 byte ke setiap paket. Server web melihat pengunjung di 192.0.2.51 dan menjawab ke sana.","Website sees":"Situs web melihat","192.0.2.51 (the VPN)":"192.0.2.51 (VPN)","Hidden from the site":"Tersembunyi dari situs","127 (one hop, the VPN)":"127 (satu hop, VPN)","from 192.0.2.51":"dari 192.0.2.51","The Way Back":"Jalan pulang","Sealed again, for the laptop":"Disegel lagi, untuk laptop","The answer goes back the same way. The VPN server seals the SYN-ACK in a WireGuard packet for the laptop, which opens it and hands it to Windows as if it had come straight from the web server.":"Jawaban kembali lewat jalan yang sama. Server VPN menyegel SYN-ACK dalam paket WireGuard untuk laptop, yang membukanya dan menyerahkannya ke Windows seolah-olah datang langsung dari server web.",Counter:"Penghitung","Each side counts its own":"Tiap pihak menghitung sendiri",Replays:"Pemutaran ulang","Thrown away":"Dibuang","inside: TCP SYN-ACK":"di dalam: TCP SYN-ACK","Keeping It Open":"Menjaga tetap terbuka","A keepalive, and new keys":"Keepalive, dan kunci baru","With nothing to send, a WireGuard tunnel goes quiet. Because the laptop is behind NAT, it is set to send an empty packet every 25 seconds (PersistentKeepalive), a keepalive of 32 bytes, so the router doesn’t forget the connection. Every two minutes a new handshake makes fresh keys, and if the laptop moves to another network, the tunnel simply carries on from its new address.":"Jika tidak ada yang dikirim, terowongan WireGuard menjadi senyap. Karena laptop berada di balik NAT, ia disetel mengirim paket kosong setiap 25 detik (PersistentKeepalive), keepalive sebesar 32 byte, supaya router tidak melupakan koneksinya. Setiap dua menit handshake baru membuat kunci segar, dan jika laptop pindah ke jaringan lain, terowongan langsung berlanjut dari alamat barunya.","Every 25 s, 32 bytes":"Setiap 25 dtk, 32 byte","New keys":"Kunci baru","Every 2 minutes":"Setiap 2 menit","New network":"Jaringan baru","The tunnel carries on":"Terowongan berlanjut",KEEPALIVE:"KEEPALIVE","empty, 32 bytes":"kosong, 32 byte","Message type":"Jenis pesan","Sender index":"Indeks pengirim","A number this side picked for the session; the other side puts it in every packet it sends back.":"Angka yang dipilih pihak ini untuk sesi; pihak lain mencantumkannya di setiap paket yang dikirim balik.","Ephemeral key":"Kunci sementara","A new public key, made just for this handshake.":"Kunci publik baru, dibuat khusus untuk handshake ini.","Encrypted static key":"Kunci statis terenkripsi","The laptop’s long-term public key (32 bytes) and a 16-byte tag, encrypted: only the server learns who is calling.":"Kunci publik jangka panjang laptop (32 byte) dan tag 16 byte, terenkripsi: hanya server yang tahu siapa yang memanggil.","Encrypted timestamp":"Stempel waktu terenkripsi","The time (12 bytes) and a tag, encrypted. An old initiation sent again is refused.":"Waktu (12 byte) dan sebuah tag, terenkripsi. Inisiasi lama yang dikirim lagi akan ditolak.","Keyed with the server’s public key: without it, the server doesn’t answer at all.":"Dihitung dengan kunci publik server: tanpanya, server sama sekali tidak menjawab.","Used only when the server is busy and asks for a cookie first.":"Hanya dipakai saat server sibuk dan meminta cookie lebih dulu.","Receiver index":"Indeks penerima","The other side’s index: which session this packet belongs to.":"Indeks pihak lain: milik sesi mana paket ini.","The server’s new public key for this handshake.":"Kunci publik baru server untuk handshake ini.","Encrypted nothing":"Kekosongan terenkripsi","Only a tag: it proves the server holds its private key.":"Hanya tag: membuktikan bahwa server memegang kunci privatnya.","Counts up with every packet; one seen before is thrown away.":"Bertambah setiap paket; paket yang pernah terlihat dibuang.","The whole inner packet, padded to a multiple of 16 bytes, then a 16-byte tag.":"Seluruh paket dalam, diberi padding hingga kelipatan 16 byte, lalu tag 16 byte.","then 12 bytes of padding, and the tag":"lalu 12 byte padding, dan tag","The laptop sent it with 128; the VPN server took 1 when it passed it on.":"Laptop mengirimnya dengan 128; server VPN mengurangi 1 saat meneruskannya.","Nothing but the 16-byte tag: an empty packet that keeps the tunnel open.":"Hanya tag 16 byte: paket kosong yang menjaga terowongan tetap terbuka.","ESP (encrypted)":"ESP (terenkripsi)","TCP beyond the gateway":"TCP di luar gateway","VPN Gateway":"Gateway VPN","IP Security":"Keamanan IP","IPsec protects IP packets themselves. IKEv2 sets things up: the two sides agree on algorithms, make keys and prove who they are with certificates or other credentials. Then ESP carries each packet encrypted inside another. IPsec links offices together and brings laptops into company networks, and it is built into most operating systems and firewalls.":"IPsec melindungi paket IP itu sendiri. IKEv2 menyiapkan semuanya: kedua pihak menyepakati algoritme, membuat kunci, dan membuktikan siapa mereka dengan sertifikat atau kredensial lain. Lalu ESP membawa setiap paket terenkripsi di dalam paket lain. IPsec menghubungkan kantor-kantor dan memasukkan laptop ke jaringan perusahaan, dan sudah tertanam di sebagian besar sistem operasi dan firewall.","Behind NAT":"Di balik NAT","ESP (IP protocol 50)":"ESP (protokol IP 50)","Certificates, EAP, keys":"Sertifikat, EAP, kunci","IKE to set up, ESP to carry":"IKE untuk menyiapkan, ESP untuk membawa","Four IKE messages agreed on algorithms, found the NAT, proved both identities and set up the tunnel. After that each packet travelled whole inside ESP, encrypted and checked, and wrapped in UDP to get through the home router. Press REPLAY to watch it again.":"Empat pesan IKE menyepakati algoritme, menemukan NAT, membuktikan kedua identitas, dan menyiapkan terowongan. Setelah itu setiap paket berjalan utuh di dalam ESP, terenkripsi dan diperiksa, serta dibungkus UDP agar bisa melewati router rumah. Tekan ULANGI untuk menontonnya lagi.","IKE messages":"Pesan IKE","4 (2 exchanges)":"4 (2 pertukaran)","NAT traversal":"Penembusan NAT","One SPI each way":"Satu SPI tiap arah","Agree on algorithms, swap keys":"Sepakati algoritme, tukar kunci","The VPN client opens with IKE on UDP port 500. Its first message proposes the algorithms (AES-GCM with 256-bit keys, SHA-256, Curve25519) and carries a public key and a random nonce; the gateway picks the proposal and sends its own key and nonce. Both now share a secret, but neither has proved who it is yet.":"Klien VPN memulai dengan IKE di port UDP 500. Pesan pertamanya mengusulkan algoritme (AES-GCM dengan kunci 256 bit, SHA-256, Curve25519) dan membawa kunci publik serta nonce acak; gateway memilih usulan itu dan mengirim kunci serta nonce-nya sendiri. Keduanya kini berbagi rahasia, tetapi belum ada yang membuktikan siapa dirinya.",Proposed:"Diusulkan","After this":"Setelah ini","Shared keys, no identities":"Kunci bersama, tanpa identitas","proposal, key, nonce":"usulan, kunci, nonce","NAT detection":"Deteksi NAT","chosen proposal, key, nonce":"usulan terpilih, kunci, nonce","A NAT in the Way":"Ada NAT di tengah","So everything moves to port 4500":"Jadi semuanya pindah ke port 4500","Both messages also carried hashes of the address and port each side sent from. At the gateway they don’t match what arrived: the home router rewrote the laptop’s address on the way (NAT). ESP has no port numbers, so a NAT can’t pass it; both sides move to UDP port 4500 and wrap ESP in UDP from now on.":"Kedua pesan juga membawa hash dari alamat dan port asal pengiriman masing-masing pihak. Di gateway, hash itu tidak cocok dengan yang tiba: router rumah menulis ulang alamat laptop di tengah jalan (NAT). ESP tidak punya nomor port, jadi NAT tidak bisa meneruskannya; kedua pihak pindah ke port UDP 4500 dan mulai sekarang membungkus ESP dalam UDP.","Hashes of":"Hash dari","Address and port sent from":"Alamat dan port asal",Mismatch:"Tidak cocok","The router rewrote them":"Router menulis ulang keduanya",Fix:"Solusi","Everything over UDP 4500":"Semuanya lewat UDP 4500","NAT DETECTED":"NAT TERDETEKSI","Prove who you are, encrypted":"Buktikan siapa Anda, terenkripsi","Now encrypted, each side sends its identity, its certificate and a signature over everything said so far, so anyone in the middle would be caught. The laptop asks for an address inside the network and gets 10.8.0.2. The same exchange sets up the ESP tunnel itself, with its own keys and an SPI for each direction.":"Kini terenkripsi, tiap pihak mengirim identitasnya, sertifikatnya, dan tanda tangan atas semua yang sudah dikatakan, sehingga siapa pun yang menyusup di tengah akan ketahuan. Laptop meminta alamat di dalam jaringan dan mendapat 10.8.0.2. Pertukaran yang sama juga menyiapkan terowongan ESP itu sendiri, dengan kuncinya sendiri dan satu SPI untuk tiap arah.","UDP 4500 (NAT traversal)":"UDP 4500 (penembusan NAT)","Identity, by certificate":"Identitas, dengan sertifikat","Laptop gets":"Laptop mendapat","10.8.0.2, and a DNS server":"10.8.0.2, dan server DNS","identity, certificate":"identitas, sertifikat",signature:"tanda tangan","address 10.8.0.2":"alamat 10.8.0.2","The whole packet, encrypted":"Seluruh paket, terenkripsi","You open https://www.example.com, looked up through the tunnel at the DNS server the gateway gave (not shown). The SYN from 10.8.0.2 is encrypted whole into an ESP packet: an SPI that names the tunnel, a sequence number, then the encrypted packet and a check value, all inside UDP port 4500. Its UDP checksum is zero: ESP checks its own contents.":"Anda membuka https://www.example.com, yang dicari lewat terowongan di server DNS yang diberikan gateway (tidak ditampilkan). SYN dari 10.8.0.2 dienkripsi utuh ke dalam paket ESP: SPI yang menamai terowongan, nomor urut, lalu paket terenkripsi dan nilai pemeriksaan, semuanya di dalam UDP port 4500. Checksum UDP-nya nol: ESP memeriksa isinya sendiri.","Names the tunnel":"Menamai terowongan","The whole IP packet":"Seluruh paket IP","62 bytes + padding":"62 byte + padding","Out and Back":"Pergi dan pulang","Through the gateway and home again":"Lewat gateway lalu kembali ke rumah","The gateway decrypts the packet and sends the SYN on from its own address, one hop older. The answer comes back to the gateway and returns through the tunnel as another ESP packet, with the SPI for the laptop’s direction and its own sequence numbers.":"Gateway mendekripsi paket dan meneruskan SYN dari alamatnya sendiri, satu hop lebih tua. Jawaban kembali ke gateway lalu pulang lewat terowongan sebagai paket ESP lain, dengan SPI untuk arah laptop dan nomor urutnya sendiri.","192.0.2.51 (the gateway)":"192.0.2.51 (gateway)","Each direction":"Tiap arah","Its own SPI and keys":"SPI dan kunci sendiri","Which VPN?":"VPN yang mana?","IPsec or WireGuard":"IPsec atau WireGuard","IPsec is older and very flexible: it negotiates its algorithms, takes many kinds of credentials and is built into Windows, macOS, iOS, Android and most firewalls, which makes it the usual way to join a company network or link two offices. WireGuard does less, with far less code and one fixed set of algorithms.":"IPsec lebih tua dan sangat fleksibel: ia menegosiasikan algoritmenya, menerima banyak jenis kredensial, dan tertanam di Windows, macOS, iOS, Android, serta sebagian besar firewall, sehingga menjadi cara umum untuk bergabung ke jaringan perusahaan atau menghubungkan dua kantor. WireGuard melakukan lebih sedikit, dengan kode yang jauh lebih sedikit dan satu set algoritme yang tetap.","Built into":"Tertanam di","Also links":"Juga menghubungkan","Office to office":"Kantor ke kantor",Negotiates:"Menegosiasikan","Its algorithms (WireGuard: no)":"Algoritmenya (WireGuard: tidak)","Initiator SPI":"SPI inisiator","Picked by the laptop: which IKE session this is.":"Dipilih laptop: sesi IKE yang mana ini.","Responder SPI":"SPI responder","0 (not known yet)":"0 (belum diketahui)","Next payload":"Muatan berikutnya","Exchange type":"Jenis pertukaran","0x08 (initiator)":"0x08 (inisiator)","Message ID":"ID pesan","Each request and its response share a number; the next exchange counts up.":"Setiap permintaan dan responsnya berbagi satu nomor; pertukaran berikutnya menambah satu.","SA payload":"Muatan SA","Next payload, length":"Muatan berikutnya, panjang",Proposal:"Usulan","What the laptop offers; a real client often offers several.":"Yang ditawarkan laptop; klien sungguhan sering menawarkan beberapa.","KE payload":"Muatan KE","DH group":"Grup DH","This side’s public key. From the two, both work out the same secret.":"Kunci publik pihak ini. Dari keduanya, kedua pihak menghitung rahasia yang sama.","Nonce payload":"Muatan Nonce","Notify payload":"Muatan Notify",Notify:"Notify",Hash:"Hash","A hash of the SPIs and the address and port this side sent from. If what arrives doesn’t match, a NAT changed it on the way.":"Hash dari SPI serta alamat dan port asal pengiriman pihak ini. Jika yang tiba tidak cocok, NAT telah mengubahnya di jalan.","The same for the address and port it sent to.":"Hal yang sama untuk alamat dan port tujuan.","0x20 (response)":"0x20 (respons)","The one the server chose from the laptop’s offer.":"Usulan yang dipilih server dari tawaran laptop.","Non-ESP marker":"Penanda non-ESP","Four zero bytes: an IKE message, not an ESP packet (they share port 4500).":"Empat byte nol: pesan IKE, bukan paket ESP (keduanya berbagi port 4500).","Encrypted payload":"Muatan terenkripsi","Encrypted payloads":"Muatan-muatan terenkripsi","Everything else in this message, encrypted with the keys from IKE_SA_INIT.":"Semua sisa pesan ini, dienkripsi dengan kunci dari IKE_SA_INIT.","IDi, CERT, AUTH: who the laptop is, proven":"IDi, CERT, AUTH: siapa laptop itu, terbukti","CP: asks for an inside address and DNS":"CP: meminta alamat dalam dan DNS","SA: what to use for ESP (AES-GCM)":"SA: apa yang dipakai untuk ESP (AES-GCM)","TSi, TSr: which traffic goes in the tunnel":"TSi, TSr: lalu lintas mana yang masuk terowongan","Integrity check":"Pemeriksaan integritas","IDr, CERT, AUTH: who the gateway is, proven":"IDr, CERT, AUTH: siapa gateway itu, terbukti","CP: inside address 10.8.0.2, DNS 10.8.0.1":"CP: alamat dalam 10.8.0.2, DNS 10.8.0.1","SA: ESP with AES-GCM, and the SPIs":"SA: ESP dengan AES-GCM, dan SPI-nya","TSi, TSr: everything (0.0.0.0/0)":"TSi, TSr: semuanya (0.0.0.0/0)","0 (not used)":"0 (tidak dipakai)","ESP checks its own contents, so ESP carried in UDP leaves this at zero.":"ESP memeriksa isinya sendiri, jadi ESP yang dibawa dalam UDP membiarkan ini nol.","Which tunnel (security association) this belongs to; the receiving side chose it during IKE_AUTH.":"Milik terowongan (security association) mana ini; pihak penerima memilihnya saat IKE_AUTH.","Different for every packet.":"Berbeda untuk setiap paket.","The whole inner packet, then padding, the pad length and the next header (4: an IPv4 packet).":"Seluruh paket dalam, lalu padding, panjang padding, dan header berikutnya (4: paket IPv4).","then padding, pad length and next header (4)":"lalu padding, panjang padding, dan header berikutnya (4)","Shows any change to the packet.":"Menunjukkan setiap perubahan pada paket.","The laptop sent it with 128; the gateway took 1 when it passed it on.":"Laptop mengirimnya dengan 128; gateway mengurangi 1 saat meneruskannya.","HTTP/3 over QUIC":"HTTP/3 lewat QUIC","QUIC is a newer transport that runs over UDP and has TLS 1.3 built in. Its first packets do the transport and the encryption handshakes together, so a page request can leave after one round trip. It carries many streams at once, so one lost packet doesn’t hold up the rest, and it survives a change of network. HTTP/3 is HTTP running over QUIC.":"QUIC adalah transport yang lebih baru yang berjalan di atas UDP dan sudah menyertakan TLS 1.3. Paket-paket pertamanya mengerjakan handshake transport dan enkripsi sekaligus, sehingga permintaan halaman bisa berangkat setelah satu kali bolak-balik. Ia membawa banyak stream sekaligus, jadi satu paket yang hilang tidak menahan yang lain, dan ia bertahan saat jaringan berganti. HTTP/3 adalah HTTP yang berjalan di atas QUIC.","Runs over":"Berjalan di atas","UDP, port 443":"UDP, port 443","TLS 1.3, always":"TLS 1.3, selalu","1 round trip (0 when returning)":"1 kali bolak-balik (0 saat kembali)",Streams:"Stream","Many, independent":"Banyak, independen","One round trip, then the request":"Satu kali bolak-balik, lalu permintaan","QUIC folded the transport and TLS handshakes into one round trip, so the request left 36 ms after the first packet; over TCP and TLS it would have waited twice as long. Everything after the first packets was encrypted, even most of each packet’s header. Press REPLAY to watch it again.":"QUIC melipat handshake transport dan TLS menjadi satu kali bolak-balik, jadi permintaan berangkat 36 ms setelah paket pertama; lewat TCP dan TLS ia akan menunggu dua kali lebih lama. Semua setelah paket-paket pertama terenkripsi, bahkan sebagian besar header setiap paket. Tekan ULANGI untuk menontonnya lagi.","1 before the request (TCP + TLS: 2)":"1 sebelum permintaan (TCP + TLS: 2)","Lost packet":"Paket hilang","Holds up one stream only":"Hanya menahan satu stream","Choosing HTTP/3":"Memilih HTTP/3","An earlier visit said it can":"Kunjungan sebelumnya bilang bisa",'On an earlier visit the server answered with Alt-Svc: h3=":443", meaning it also speaks HTTP/3 on UDP port 443 (DNS can say the same in an HTTPS record). So this time the browser skips TCP and talks QUIC.':'Pada kunjungan sebelumnya server menjawab dengan Alt-Svc: h3=":443", yang berarti ia juga berbicara HTTP/3 di port UDP 443 (DNS bisa menyatakan hal yang sama dalam record HTTPS). Jadi kali ini browser melewatkan TCP dan berbicara QUIC.',"Learned from":"Diketahui dari","Alt-Svc header, or DNS":"Header Alt-Svc, atau DNS","QUIC over UDP 443":"QUIC lewat UDP 443","TLS 1.3, built in":"TLS 1.3, bawaan","Initial Packets":"Paket Initial","The Client Hello, straight away":"Client Hello, langsung","There is no separate TCP handshake: the very first packets carry the TLS Client Hello. With its post-quantum key share it is 1,880 bytes, too big for one packet, so it fills two Initial packets. Each datagram is padded to at least 1,200 bytes; a server may send back only three times what it has received, so a forged sender address can’t turn it into an amplifier.":"Tidak ada handshake TCP terpisah: paket-paket paling awal sudah membawa Client Hello TLS. Dengan key share pascakuantumnya, ukurannya 1,880 byte, terlalu besar untuk satu paket, jadi ia mengisi dua paket Initial. Setiap datagram diberi padding hingga minimal 1,200 byte; server hanya boleh mengirim balik tiga kali yang ia terima, supaya alamat pengirim palsu tidak bisa menjadikannya penguat.","2 × 1,250 bytes":"2 × 1,250 byte","The TLS Client Hello":"Client Hello TLS","Readable?":"Bisa dibaca?","Yes (Initial keys are public)":"Ya (kunci Initial bersifat publik)","Client Hello, part 1":"Client Hello, bagian 1","Client Hello, part 2":"Client Hello, bagian 2",padding:"padding","Then the certificate, encrypted":"Lalu sertifikat, terenkripsi","The server answers with its Server Hello in an Initial packet. Both sides can now work out handshake keys, so the rest (the certificate, its signature and Finished) comes in Handshake packets that only the laptop can read. Four datagrams, well under three times what the laptop sent.":"Server menjawab dengan Server Hello dalam paket Initial. Kini kedua pihak bisa menghitung kunci handshake, jadi sisanya (sertifikat, tanda tangannya, dan Finished) datang dalam paket Handshake yang hanya bisa dibaca laptop. Empat datagram, jauh di bawah tiga kali yang dikirim laptop.","Certificate, signature, Finished":"Sertifikat, tanda tangan, Finished","Server limit":"Batas server","3× the bytes received":"3× byte yang diterima","certificate, Finished":"sertifikat, Finished","The request, one round trip in":"Permintaan, setelah satu kali bolak-balik","The laptop checks the certificate and sends its Finished, and in the same moment its first HTTP/3 request in a 1-RTT packet: a HEADERS frame on stream 0, its headers compressed with QPACK. One round trip after the first packet, the request is on its way; TCP and TLS together would need two.":"Laptop memeriksa sertifikat dan mengirim Finished-nya, dan pada saat yang sama permintaan HTTP/3 pertamanya dalam paket 1-RTT: frame HEADERS di stream 0, dengan header yang dikompresi QPACK. Satu kali bolak-balik setelah paket pertama, permintaan sudah berangkat; TCP dan TLS bersama butuh dua.","1 (TCP + TLS: 2)":"1 (TCP + TLS: 2)","HEADERS on stream 0":"HEADERS di stream 0",Headers:"Header","Compressed (QPACK)":"Dikompresi (QPACK)","HTTP/3, stream 0":"HTTP/3, stream 0","The Response":"Respons","On its own stream":"Di stream sendiri","The server confirms the handshake is over (HANDSHAKE_DONE) and answers on stream 0: headers, then the page. Every request gets its own stream, so a lost packet holds up only the stream it belonged to. Over TCP one missing segment stalls everything behind it.":"Server mengonfirmasi handshake selesai (HANDSHAKE_DONE) dan menjawab di stream 0: header, lalu halaman. Setiap permintaan punya stream sendiri, jadi paket yang hilang hanya menahan stream tempat ia berada. Lewat TCP, satu segmen yang hilang menahan semua yang ada di belakangnya.","Frames on QUIC streams":"Frame di stream QUIC","Holds up one stream":"Menahan satu stream","All but a few header bits":"Semua kecuali beberapa bit header","the page":"halaman","New Network":"Jaringan baru","Known by ID, not by address":"Dikenali dari ID, bukan alamat","A QUIC connection is known by its connection IDs, not by addresses and ports. If the laptop moves from Wi-Fi to a phone’s hotspot, its address changes but the connection carries on: the server checks the new path and continues. And on the next visit the browser can send its request in its very first packets (0-RTT).":"Koneksi QUIC dikenali dari ID koneksinya, bukan dari alamat dan port. Jika laptop pindah dari Wi-Fi ke hotspot ponsel, alamatnya berubah tetapi koneksi berlanjut: server memeriksa jalur baru dan meneruskan. Dan pada kunjungan berikutnya browser bisa mengirim permintaannya di paket-paket paling awal (0-RTT).","Known by":"Dikenali dari","Connection ID":"ID koneksi","New address":"Alamat baru","The connection carries on":"Koneksi berlanjut","Next visit":"Kunjungan berikutnya","0-RTT: request at once":"0-RTT: permintaan langsung","SAME CONNECTION ON ANY NETWORK":"KONEKSI YANG SAMA DI JARINGAN MANA PUN","Initial, CRYPTO (Client Hello, part 1)":"Initial, CRYPTO (Client Hello, bagian 1)","Initial, CRYPTO (Client Hello, part 2), PADDING":"Initial, CRYPTO (Client Hello, bagian 2), PADDING","Handshake, CRYPTO (Certificate, part 1)":"Handshake, CRYPTO (sertifikat, bagian 1)","Handshake, CRYPTO (Certificate, part 2)":"Handshake, CRYPTO (sertifikat, bagian 2)","Initial packet":"Paket Initial","Header type":"Jenis header","long header, Initial":"header panjang, Initial","The top bits say what kind of packet this is; the last bits are disguised (header protection).":"Bit teratas menyatakan jenis paket ini; bit terakhir disamarkan (perlindungan header).","Destination connection ID":"ID koneksi tujuan","Which connection this belongs to. Each side picks its own ID; the other writes it here.":"Koneksi mana pemilik paket ini. Tiap pihak memilih ID-nya sendiri; pihak lain menuliskannya di sini.","Source connection ID":"ID koneksi sumber","Token length":"Panjang token","No token: the server hasn’t asked this client to prove its address first.":"Tanpa token: server belum meminta klien ini membuktikan alamatnya lebih dulu.","The packet number and payload. Whatever follows is another packet in the same datagram.":"Nomor paket dan muatan. Apa pun yang menyusul adalah paket lain dalam datagram yang sama.","Packet number":"Nomor paket","Hidden by header protection, so nobody on the way can read or change it.":"Disembunyikan oleh perlindungan header, jadi tak seorang pun di jalan bisa membaca atau mengubahnya.","Encrypted with keys anyone can work out from the connection ID, so it stops accidents, not eavesdroppers: the Client Hello inside can be read on the way.":"Dienkripsi dengan kunci yang bisa dihitung siapa saja dari ID koneksi, jadi ini mencegah kecelakaan, bukan penyadap: Client Hello di dalamnya bisa dibaca di jalan.","CRYPTO: Client Hello, bytes 1–1,203 of 1,880":"CRYPTO: Client Hello, byte 1–1,203 dari 1,880","SNI www.example.com, ALPN h3, X25519MLKEM768 key share":"SNI www.example.com, ALPN h3, key share X25519MLKEM768","CRYPTO: Client Hello, bytes 1,204–1,880":"CRYPTO: Client Hello, byte 1,204–1,880","PADDING, up to 1,250 bytes":"PADDING, hingga 1,250 byte","ACK: packets 0–1 arrived":"ACK: paket 0–1 sudah tiba","CRYPTO: Server Hello, with its half of the key (1,120 bytes)":"CRYPTO: Server Hello, dengan separuh kuncinya (1,120 byte)","Handshake packet":"Paket Handshake","long header, Handshake":"header panjang, Handshake","Encrypted with keys from the key exchange so far.":"Dienkripsi dengan kunci dari pertukaran kunci sejauh ini.","CRYPTO: Encrypted Extensions, Certificate (start)":"CRYPTO: Encrypted Extensions, Certificate (awal)","CRYPTO: Certificate (continued)":"CRYPTO: Certificate (lanjutan)","CRYPTO: Certificate Verify, Finished":"CRYPTO: Certificate Verify, Finished","ACK: the server’s Initial arrived":"ACK: Initial dari server sudah tiba","ACK: the Handshake packets arrived":"ACK: paket Handshake sudah tiba","1-RTT packet":"Paket 1-RTT","short header":"header pendek","Only the receiver’s ID, and no length: it knows how long its own IDs are. It stays the same if the laptop changes network.":"Hanya ID penerima, dan tanpa panjang: penerima tahu panjang ID-nya sendiri. ID ini tetap sama walau laptop berganti jaringan.","Encrypted with the session keys.":"Dienkripsi dengan kunci sesi.","STREAM 2: SETTINGS (the control stream)":"STREAM 2: SETTINGS (stream kontrol)","STREAM 0: HEADERS, GET / (QPACK-compressed)":"STREAM 0: HEADERS, GET / (dikompresi QPACK)","HANDSHAKE_DONE: the handshake is over":"HANDSHAKE_DONE: handshake selesai","STREAM 0: HEADERS 200, then DATA: the page (1,000 bytes)":"STREAM 0: HEADERS 200, lalu DATA: halaman (1,000 byte)","ACK: the response arrived":"ACK: respons sudah tiba","Address Setup":"Pengaturan alamat","No IPv6 address":"Tanpa alamat IPv6","IPv6: SLAAC and neighbour discovery":"IPv6: SLAAC dan penemuan tetangga","IPv6 addresses are 128 bits long, enough for every device to have its own. A device can usually set itself up with no DHCP server: it makes a link-local address, asks for a router, and builds its global address from the prefix the router advertises (SLAAC). Neighbour discovery, part of ICMPv6, finds MAC addresses and does the work ARP does for IPv4.":"Alamat IPv6 panjangnya 128 bit, cukup untuk setiap perangkat punya alamat sendiri. Biasanya perangkat bisa mengatur dirinya sendiri tanpa server DHCP: ia membuat alamat link-local, menanyakan router, dan menyusun alamat globalnya dari prefiks yang diumumkan router (SLAAC). Penemuan tetangga, bagian dari ICMPv6, menemukan alamat MAC dan mengerjakan tugas ARP pada IPv4.","128 bits":"128 bit",Addresses:"Alamat","SLAAC: no server needed":"SLAAC: tanpa server","Replaces ARP":"Menggantikan ARP","Neighbour discovery":"Penemuan tetangga",Optional:"Opsional","Two addresses, no DHCP":"Dua alamat, tanpa DHCP","Made by the laptop itself":"Dibuat oleh laptop sendiri","The laptop made a link-local address and a global one, checked that nobody else had either, and learned its router, MTU and DNS server from a single advertisement. When packets came for it, neighbour discovery found its MAC address. Press REPLAY to watch it again.":"Laptop membuat alamat link-local dan alamat global, memeriksa bahwa tidak ada pihak lain yang memakai keduanya, dan mengetahui router, MTU, serta server DNS-nya dari satu pengumuman. Ketika ada paket untuknya, penemuan tetangga menemukan alamat MAC-nya. Tekan ULANGI untuk menontonnya lagi.","Link-local":"Link-local",Global:"Global","2001:db8:1234:5678::/64 + its own ID":"2001:db8:1234:5678::/64 + ID-nya sendiri","Router, DNS":"Router, DNS","From one advertisement":"Dari satu pengumuman","6, all ICMPv6":"6, semuanya ICMPv6","Link-Local First":"Link-local lebih dulu","Every IPv6 interface gets a link-local address, usable only on its own network. The laptop makes one from fe80:: and a random-looking 64-bit interface ID. First it checks nobody already has it: a Neighbor Solicitation asking for that address, sent from :: because it can’t use the address yet. Nobody answers, so it’s the laptop’s.":"Setiap antarmuka IPv6 mendapat alamat link-local, yang hanya bisa dipakai di jaringannya sendiri. Laptop membuatnya dari fe80:: dan ID antarmuka 64 bit yang tampak acak. Mula-mula ia memeriksa bahwa belum ada yang memakainya: Neighbor Solicitation yang menanyakan alamat itu, dikirim dari :: karena ia belum boleh memakai alamat tersebut. Tidak ada yang menjawab, jadi alamat itu milik laptop.",Check:"Pemeriksaan","Duplicate address detection":"Deteksi alamat ganda","None: the address is free":"Tidak ada: alamat masih bebas","IS IT TAKEN?":"SUDAH DIPAKAI?","from ::":"dari ::","target fe80::8d2e:4f61:a9b0:7c13":"target fe80::8d2e:4f61:a9b0:7c13","NO ANSWER: ADDRESS IS FREE":"TAK ADA JAWABAN: ALAMAT BEBAS","Any Routers?":"Ada router?","A Router Solicitation":"Router Solicitation","Link-local addresses can’t reach the internet. The laptop sends a Router Solicitation to ff02::2, the address every router on the network listens to, with its own MAC address attached.":"Alamat link-local tidak bisa menjangkau internet. Laptop mengirim Router Solicitation ke ff02::2, alamat yang didengarkan setiap router di jaringan, dengan alamat MAC-nya sendiri terlampir.","ff02::2 (all routers)":"ff02::2 (semua router)",Includes:"Berisi","ROUTERS?":"ADA ROUTER?","Router Answers":"Router menjawab","Prefix, MTU and DNS in one message":"Prefiks, MTU, dan DNS dalam satu pesan","The router answers to ff02::1, every device on the network, with a Router Advertisement: use me as your way out for 30 minutes, here is my MAC address, the MTU is 1500, the network’s prefix is 2001:db8:1234:5678::/64 and you may make your own address in it, and ask 2001:4860:4860::8888 for DNS. Routers also send these on their own every few minutes.":"Router menjawab ke ff02::1, semua perangkat di jaringan, dengan Router Advertisement: pakai saya sebagai jalan keluar selama 30 menit, ini alamat MAC saya, MTU-nya 1500, prefiks jaringan ini 2001:db8:1234:5678::/64 dan Anda boleh membuat alamat sendiri di dalamnya, dan tanyakan DNS ke 2001:4860:4860::8888. Router juga mengirim ini sendiri setiap beberapa menit.",Prefix:"Prefiks","Make your own":"Buat sendiri","Yes (flag A)":"Ya (flag A)",ADVERTISEMENT:"PENGUMUMAN","prefix 2001:db8:1234:5678::/64":"prefiks 2001:db8:1234:5678::/64","A Global Address":"Alamat global","Prefix + interface ID":"Prefiks + ID antarmuka","The laptop joins the prefix and its interface ID into a global address, 2001:db8:1234:5678:8d2e:4f61:a9b0:7c13, and checks it the same way. Windows also makes a temporary address with a random ID that changes every day, used for outgoing connections so websites can’t follow one device by its address.":"Laptop menggabungkan prefiks dan ID antarmukanya menjadi alamat global, 2001:db8:1234:5678:8d2e:4f61:a9b0:7c13, dan memeriksanya dengan cara yang sama. Windows juga membuat alamat sementara dengan ID acak yang berganti setiap hari, dipakai untuk koneksi keluar agar situs web tidak bisa mengikuti satu perangkat dari alamatnya.","Also made":"Juga dibuat","A temporary address":"Alamat sementara","target the global address":"target alamat global","Neighbour Lookup":"Mencari tetangga","Who has this address? (ARP’s job)":"Siapa pemilik alamat ini? (tugas ARP)","A reply from the internet arrives at the router for the laptop’s global address. To deliver it, the router needs the MAC address that goes with it: it sends a Neighbor Solicitation to the address’s solicited-node group, so only devices whose address ends the same way even look. The laptop answers with a Neighbor Advertisement carrying its MAC address.":"Balasan dari internet tiba di router untuk alamat global laptop. Untuk mengantarkannya, router butuh alamat MAC yang sesuai: ia mengirim Neighbor Solicitation ke grup solicited-node alamat itu, jadi hanya perangkat yang alamatnya berakhiran sama yang memperhatikan. Laptop menjawab dengan Neighbor Advertisement yang membawa alamat MAC-nya.","Asked to":"Ditanyakan ke","Instead of":"Sebagai ganti","ARP broadcasts to everyone":"ARP menyiarkan ke semua","WHO HAS?":"SIAPA PEMILIKNYA?","the global address":"alamat global","Ready, No DHCP":"Siap, tanpa DHCP","And no NAT either":"Dan tanpa NAT juga","The laptop is on the internet with its own global address, and no NAT changes it on the way: the address a website sees is the laptop’s. The home router’s firewall still turns away connections nobody inside asked for. Networks that want to hand out addresses centrally can use DHCPv6 instead.":"Laptop ada di internet dengan alamat globalnya sendiri, dan tidak ada NAT yang mengubahnya di jalan: alamat yang dilihat situs web adalah milik laptop. Firewall router rumah tetap menolak koneksi yang tidak diminta siapa pun dari dalam. Jaringan yang ingin membagikan alamat secara terpusat bisa memakai DHCPv6.","Not needed":"Tidak perlu",Incoming:"Masuk","Blocked by the firewall":"Diblokir firewall","Optional (flags M, O)":"Opsional (flag M, O)","ONLINE OVER IPv6":"ONLINE LEWAT IPv6","A multicast MAC address: 33:33, then the last four bytes of the IPv6 address.":"Alamat MAC multicast: 33:33, lalu empat byte terakhir alamat IPv6.","Version, class, flow":"Versi, kelas, aliran","IPv6, ordinary traffic, no flow label.":"IPv6, lalu lintas biasa, tanpa label aliran.","Payload length":"Panjang muatan","What follows this 40-byte header.":"Apa yang mengikuti header 40 byte ini.","Next header":"Header berikutnya","Hop limit":"Batas hop","Neighbour discovery must arrive with 255, proof that no router passed it on: it came from this network.":"Penemuan tetangga harus tiba dengan 255, bukti bahwa tidak ada router yang meneruskannya: ia berasal dari jaringan ini.","Unspecified: the laptop has no address it may use yet.":"Tidak ditentukan: laptop belum punya alamat yang boleh dipakai.","Solicited-node multicast: only devices whose address ends in the same 24 bits are listening.":"Multicast solicited-node: hanya perangkat yang alamatnya berakhiran 24 bit yang sama yang mendengarkan.","Covers the message and both IPv6 addresses.":"Mencakup pesan dan kedua alamat IPv6.",Target:"Target","The address the laptop wants to use. If anyone answers, it’s taken.":"Alamat yang ingin dipakai laptop. Jika ada yang menjawab, alamat itu sudah dipakai.","A link-local address: usable only on this network.":"Alamat link-local: hanya bisa dipakai di jaringan ini.","Every router on this network.":"Setiap router di jaringan ini.","Source link-layer address":"Alamat link-layer sumber","The sender’s MAC address, so nobody has to ask for it.":"Alamat MAC pengirim, jadi tidak ada yang perlu menanyakannya.","Every device on this network.":"Setiap perangkat di jaringan ini.","The hop limit devices here should put on their packets.":"Batas hop yang harus dipasang perangkat di sini pada paketnya.","M: take addresses from DHCPv6. O: take other settings from DHCPv6. Both off: this advertisement has everything.":"M: ambil alamat dari DHCPv6. O: ambil pengaturan lain dari DHCPv6. Keduanya mati: pengumuman ini sudah berisi semuanya.","Router lifetime":"Masa berlaku router","How long the laptop may use this router as its way out.":"Berapa lama laptop boleh memakai router ini sebagai jalan keluar.","Reachable time":"Waktu terjangkau","0 (not set)":"0 (tidak diatur)","Retransmit timer":"Pewaktu pengiriman ulang","The largest packet this network carries.":"Paket terbesar yang dibawa jaringan ini.","2001:db8:1234:5678::/64, valid 86,400 s, preferred 14,400 s":"2001:db8:1234:5678::/64, berlaku 86,400 s, diutamakan 14,400 s","Flags L and A: addresses in this prefix are on this network, and devices may make their own (SLAAC).":"Flag L dan A: alamat dalam prefiks ini ada di jaringan ini, dan perangkat boleh membuat alamatnya sendiri (SLAAC).","2001:4860:4860::8888, for 3,600 s":"2001:4860:4860::8888, selama 3,600 s","Recursive DNS server: which resolver to ask, so no DHCP is needed for that either.":"Server DNS rekursif: resolver mana yang ditanya, jadi untuk itu pun tidak perlu DHCP.","Whose MAC address is wanted.":"Alamat MAC siapa yang dicari.","The device this frame is for.":"Perangkat tujuan frame ini.","0x60000000: solicited, override":"0x60000000: diminta, timpa","Solicited: this answers a question. Override: replace any older entry for this address.":"Diminta: ini menjawab pertanyaan. Timpa: ganti entri lama untuk alamat ini.","Target link-layer address":"Alamat link-layer target","The answer: the MAC address that goes with the target.":"Jawabannya: alamat MAC yang sesuai dengan target.","Setting the Clock":"Mengatur jam","Computer clocks drift by seconds a week, and a lot depends on them: certificates have dates, logins and payments expire, logs from different machines must line up. NTP sets a clock from a time server over the internet. One small request and answer carry four timestamps, enough to work out how far off the clock is and how long the network took.":"Jam komputer bergeser beberapa detik per minggu, dan banyak hal bergantung padanya: sertifikat punya tanggal, login dan pembayaran kedaluwarsa, log dari mesin berbeda harus selaras. NTP mengatur jam dari server waktu lewat internet. Satu permintaan kecil dan jawabannya membawa empat stempel waktu, cukup untuk menghitung seberapa melenceng jam itu dan berapa lama jaringan memakan waktu.",Accuracy:"Akurasi","A few milliseconds online":"Beberapa milidetik lewat internet","Clock set":"Jam diatur","Four timestamps, one answer":"Empat stempel waktu, satu jawaban","One request and one answer gave four timestamps. From them the laptop worked out that its clock was 0.25 s slow and that the network took 24 ms there and back, and it began easing its clock into line. Press REPLAY to watch it again.":"Satu permintaan dan satu jawaban memberi empat stempel waktu. Dari situ laptop menghitung bahwa jamnya terlambat 0.25 s dan jaringan butuh 24 ms pulang-pergi, lalu mulai menyesuaikan jamnya perlahan. Tekan ULANGI untuk menontonnya lagi.",Offset:"Selisih","250.0 ms (slow)":"250.0 ms (terlambat)","Stratum 2":"Stratum 2","Next check":"Pemeriksaan berikutnya","Minutes to days later":"Beberapa menit hingga hari kemudian","Clocks Drift":"Jam bergeser","The laptop’s clock is a little slow":"Jam laptop sedikit terlambat","A computer keeps time with a quartz crystal that runs a little fast or slow, so clocks drift apart by seconds a week. This laptop’s clock is a quarter of a second behind. Windows sets it from time.windows.com, whose address it has already looked up by DNS.":"Komputer menjaga waktu dengan kristal kuarsa yang berjalan sedikit cepat atau lambat, jadi jam saling menjauh beberapa detik per minggu. Jam laptop ini terlambat seperempat detik. Windows mengaturnya dari time.windows.com, yang alamatnya sudah dicari lewat DNS.","Laptop clock":"Jam laptop","0.25 s slow":"Terlambat 0.25 s","Time server":"Server waktu","Why it matters":"Mengapa penting","Certificates, logins, logs":"Sertifikat, login, log","CLOCK 0.250 s SLOW":"JAM TERLAMBAT 0.250 s","Ask for the Time":"Menanyakan waktu","T1: when the request leaves":"T1: saat permintaan berangkat","The laptop sends a 48-byte request to port 123. It writes in the time by its own clock as the request leaves: T1, 09:40:59.750. Everything else is empty.":"Laptop mengirim permintaan 48 byte ke port 123. Ia menuliskan waktu menurut jamnya sendiri saat permintaan berangkat: T1, 09:40:59.750. Sisanya kosong.","T1 (laptop)":"T1 (laptop)",Mode:"Mode","3 (client)":"3 (klien)","The Answer":"Jawaban","T2 and T3 from the server, T4 on arrival":"T2 dan T3 dari server, T4 saat tiba","The server copies T1 back, adds T2, when the request arrived, and T3, when its answer leaves, both by its own accurate clock. When the answer arrives, the laptop notes T4 by its own clock. The server is stratum 2: it sets its clock from a stratum 1 server, which has a GPS receiver or an atomic clock.":"Server menyalin balik T1, menambahkan T2, saat permintaan tiba, dan T3, saat jawabannya berangkat, keduanya menurut jamnya sendiri yang akurat. Saat jawaban tiba, laptop mencatat T4 menurut jamnya sendiri. Server ini stratum 2: ia mengatur jamnya dari server stratum 1, yang punya penerima GPS atau jam atom.","T4 (laptop)":"T4 (laptop)",Stratum:"Stratum","The Offset":"Selisihnya","Four times, two answers":"Empat waktu, dua jawaban","The time on the network, there and back, is (T4 − T1) − (T3 − T2) = 24.0 ms. The offset assumes the trip takes as long each way: ((T2 − T1) + (T3 − T4)) / 2 = 250.0 ms. The laptop’s clock is a quarter of a second slow. An uneven route (slower one way than the other) would skew the result by up to half the difference.":"Waktu di jaringan, pulang-pergi, adalah (T4 − T1) − (T3 − T2) = 24.0 ms. Selisih mengandaikan perjalanan memakan waktu sama ke tiap arah: ((T2 − T1) + (T3 − T4)) / 2 = 250.0 ms. Jam laptop terlambat seperempat detik. Rute yang tidak seimbang (lebih lambat ke satu arah) akan menggeser hasil hingga separuh selisihnya.",Assumes:"Mengandaikan","Equal time each way":"Waktu sama ke tiap arah","OFFSET +250.0 ms":"SELISIH +250.0 ms","Ease It In":"Disesuaikan perlahan","No jumps backwards":"Tak ada lompatan mundur","A small error is not fixed in one jump: the clock is run slightly fast until it catches up, so time never stops or goes backwards for running programs. Only a big error is set straight away. As a clock settles, an NTP client asks less often, from every 64 seconds up to every 17 minutes or so; Windows on its own checks time.windows.com far less often, every several hours or less.":"Kesalahan kecil tidak diperbaiki dengan satu lompatan: jam dijalankan sedikit lebih cepat sampai menyusul, supaya waktu tidak pernah berhenti atau mundur bagi program yang sedang berjalan. Hanya kesalahan besar yang langsung diatur. Saat jam makin stabil, klien NTP bertanya makin jarang, dari setiap 64 detik hingga kira-kira setiap 17 menit; Windows sendiri memeriksa time.windows.com jauh lebih jarang, setiap beberapa jam atau lebih jarang.","Small offsets":"Selisih kecil","Eased in gradually":"Disesuaikan bertahap","Large offsets":"Selisih besar","Set at once":"Langsung diatur","Asks again":"Bertanya lagi","Less often as it settles":"Makin jarang saat stabil","CLOCK IN STEP":"JAM SUDAH TEPAT","Leap, version, mode":"Leap, versi, mode","Mode 3: a client asking for the time.":"Mode 3: klien yang menanyakan waktu.",Poll:"Interval poll","How often the client means to ask (2 to the power 6 seconds). It grows as the clock settles.":"Seberapa sering klien berniat bertanya (2 pangkat 6 detik). Makin besar saat jam makin stabil.",Precision:"Presisi","How finely this clock can be read.":"Seberapa halus jam ini bisa dibaca.","Root delay":"Root delay","Root dispersion":"Root dispersion","Reference ID":"ID referensi","Reference time":"Waktu referensi","Origin time":"Waktu asal","Receive time":"Waktu terima","Transmit time":"Waktu kirim","T1: when the request left, by the laptop’s own (wrong) clock.":"T1: saat permintaan berangkat, menurut jam laptop sendiri (yang salah).","Mode 4: an answer from a server.":"Mode 4: jawaban dari server.","Two steps from a reference clock: it follows a stratum 1 server, which has its own GPS or atomic clock.":"Dua langkah dari jam referensi: ia mengikuti server stratum 1, yang punya GPS atau jam atom sendiri.","Round-trip time from this server to the reference clock.":"Waktu pulang-pergi dari server ini ke jam referensi.","How far off this server could be, at most.":"Seberapa jauh server ini bisa melenceng, paling banyak.","192.0.2.123 (its own time source)":"192.0.2.123 (sumber waktunya sendiri)","When this server last set its own clock.":"Kapan server ini terakhir mengatur jamnya sendiri.","T1, copied from the request: the client can match the answer to its question.":"T1, disalin dari permintaan: klien bisa mencocokkan jawaban dengan pertanyaannya.","T2: when the request arrived, by the server’s clock.":"T2: saat permintaan tiba, menurut jam server.","T3: when this answer left.":"T3: saat jawaban ini berangkat.",Private:"Privat","Plain DNS":"DNS tanpa enkripsi","DNS inside HTTPS":"DNS di dalam HTTPS","DNS queries inside HTTPS":"Kueri DNS di dalam HTTPS","Ordinary DNS travels in the clear: anyone on the same Wi-Fi, and your internet provider, can read every name you look up and even change the answers. DNS over HTTPS (DoH) sends the same DNS messages inside an encrypted HTTPS connection to the resolver, so on the way they look like any other web traffic. Browsers and operating systems can turn it on.":"DNS biasa berjalan tanpa enkripsi: siapa pun di Wi-Fi yang sama, dan penyedia internet Anda, bisa membaca setiap nama yang Anda cari, bahkan mengubah jawabannya. DNS over HTTPS (DoH) mengirim pesan DNS yang sama di dalam koneksi HTTPS terenkripsi ke resolver, jadi di jalan pesan itu tampak seperti lalu lintas web biasa. Browser dan sistem operasi bisa mengaktifkannya.","Ordinary DNS messages":"Pesan DNS biasa",Hides:"Menyembunyikan","Which names you look up":"Nama apa yang Anda cari",Similar:"Mirip","DNS over TLS (port 853)":"DNS over TLS (port 853)","Looked up in private":"Dicari secara privat","Same question, sealed":"Pertanyaan sama, tersegel","The plain lookup could be read by anyone on the path. Over HTTPS the same DNS message was sealed inside TLS, readable only by the resolver. The resolver still sees every question, so the trust moves to it, and the site you then visit can still be seen by its address. Press REPLAY to watch it again.":"Pencarian tanpa enkripsi bisa dibaca siapa pun di jalan. Lewat HTTPS, pesan DNS yang sama disegel di dalam TLS, hanya bisa dibaca resolver. Resolver tetap melihat setiap pertanyaan, jadi kepercayaan pindah kepadanya, dan situs yang kemudian Anda kunjungi tetap terlihat dari alamatnya. Tekan ULANGI untuk menontonnya lagi.","On the way":"Di jalan","Only “HTTPS to dns.google”":"Hanya “HTTPS ke dns.google”","The resolver":"Resolver","Still sees every name":"Tetap melihat setiap nama","The site’s address you then visit":"Alamat situs yang kemudian Anda kunjungi","Can’t be changed on the way":"Tak bisa diubah di jalan","Readable by anyone on the way":"Bisa dibaca siapa pun di jalan","This is the lookup from the other lessons: a UDP packet to port 53 asking for www.example.com, and the answer. Neither is encrypted, so everyone on the café’s Wi-Fi, and the internet provider, can see which names the laptop looks up, and could even answer with a false address.":"Ini pencarian dari pelajaran lain: paket UDP ke port 53 yang menanyakan www.example.com, beserta jawabannya. Keduanya tidak terenkripsi, jadi semua orang di Wi-Fi kafe, dan penyedia internet, bisa melihat nama apa yang dicari laptop, bahkan bisa menjawab dengan alamat palsu.","UDP port 53":"Port UDP 53","Can be changed":"Bisa diubah","Yes, on the way":"Ya, di jalan",readable:"terbaca","ANYONE HERE CAN READ IT":"SIAPA PUN DI SINI BISA MEMBACANYA","An HTTPS Link":"Tautan HTTPS","TCP and TLS to dns.google":"TCP dan TLS ke dns.google","With DNS over HTTPS on, the browser opens an HTTPS connection to the resolver instead: TCP to port 443 and a TLS handshake for dns.google. It keeps this connection open and sends every lookup down it.":"Dengan DNS over HTTPS aktif, browser malah membuka koneksi HTTPS ke resolver: TCP ke port 443 dan handshake TLS untuk dns.google. Koneksi ini dibiarkan terbuka dan setiap pencarian dikirim lewat situ.","dns.google (8.8.8.8)":"dns.google (8.8.8.8)","443, like any website":"443, seperti situs web mana pun","Kept open":"Tetap terbuka","For every lookup":"Untuk setiap pencarian","Sealed Question":"Pertanyaan tersegel","A DNS message in an HTTP request":"Pesan DNS dalam permintaan HTTP","The question is the same DNS message as before. It goes in an HTTP/2 request, GET /dns-query?dns= followed by the message in base64url, asking for an answer in the type application/dns-message. Inside TLS, nobody on the way can read it.":"Pertanyaannya adalah pesan DNS yang sama seperti tadi. Pesan itu masuk dalam permintaan HTTP/2, GET /dns-query?dns= diikuti pesan dalam base64url, yang meminta jawaban bertipe application/dns-message. Di dalam TLS, tak seorang pun di jalan bisa membacanya.",Format:"Format","application/dns-message":"application/dns-message","Encrypted (TLS)":"Terenkripsi (TLS)","DoH QUERY":"KUERI DoH","inside: GET /dns-query?dns=…":"di dalam: GET /dns-query?dns=…","Sealed Answer":"Jawaban tersegel","The DNS answer in an HTTP response":"Jawaban DNS dalam respons HTTP","The resolver answers 200 with a body of type application/dns-message: the same DNS answer as the plain lookup, A 203.0.113.10. Because it arrives through TLS from dns.google, nobody on the way could have changed it.":"Resolver menjawab 200 dengan body bertipe application/dns-message: jawaban DNS yang sama dengan pencarian tanpa enkripsi, A 203.0.113.10. Karena tiba lewat TLS dari dns.google, tak seorang pun di jalan bisa mengubahnya.","200, application/dns-message":"200, application/dns-message","The DNS answer (49 bytes)":"Jawaban DNS (49 byte)",Tampering:"Pengubahan","Impossible on the way":"Mustahil di jalan","DoH ANSWER":"JAWABAN DoH","inside: A 203.0.113.10":"di dalam: A 203.0.113.10","What Still Shows":"Yang masih terlihat","Hidden on the way, not from the resolver":"Tersembunyi di jalan, bukan dari resolver","On the way, the lookups now look like any HTTPS traffic to dns.google. But the resolver itself reads every question, so you are trusting it instead of whoever runs your network. And the site you then visit is still seen by its IP address, and by its name in the TLS Client Hello unless it supports Encrypted Client Hello. DNS over TLS does the same job on port 853.":"Di jalan, pencarian kini tampak seperti lalu lintas HTTPS biasa ke dns.google. Tetapi resolver sendiri membaca setiap pertanyaan, jadi Anda memercayainya, bukan siapa pun yang mengelola jaringan Anda. Dan situs yang kemudian Anda kunjungi tetap terlihat dari alamat IP-nya, dan dari namanya di Client Hello TLS kecuali situs itu mendukung Encrypted Client Hello. DNS over TLS melakukan tugas yang sama di port 853.","Sees every name":"Melihat setiap nama","Then visible":"Lalu terlihat","The site’s IP, maybe its name":"IP situs, mungkin namanya",Alternative:"Alternatif","TRUST MOVES TO THE RESOLVER":"KEPERCAYAAN PINDAH KE RESOLVER","Application Data (HTTP/2: DNS query)":"Application Data (HTTP/2: kueri DNS)","Application Data (HTTP/2: DNS answer)":"Application Data (HTTP/2: jawaban DNS)","HTTP/2: the connection preface and settings, then the request":"HTTP/2: pembuka koneksi dan pengaturan, lalu permintaan","HTTP/2: settings, the response headers, then the DNS answer":"HTTP/2: pengaturan, header respons, lalu jawaban DNS","Signed Answers":"Jawaban diteken","Question and answer":"Pertanyaan dan jawaban","To the name servers":"Ke server nama","Signed answers":"Jawaban bertanda tangan","DNS Security Extensions":"Ekstensi Keamanan DNS","Plain DNS answers can be forged: whoever answers first, or sits in the middle, can send a false address. DNSSEC lets a resolver check that an answer really comes from the domain’s owner. Every set of records is signed; each zone’s key is vouched for by its parent, up to the root, whose key resolvers have built in. DNSSEC proves answers are genuine; it doesn’t hide them.":"Jawaban DNS biasa bisa dipalsukan: siapa pun yang menjawab lebih dulu, atau berada di tengah, bisa mengirim alamat palsu. DNSSEC memungkinkan resolver memeriksa bahwa jawaban benar-benar berasal dari pemilik domain. Setiap kumpulan record ditandatangani; kunci setiap zona dijamin oleh zona induknya, hingga ke root, yang kuncinya sudah tertanam di resolver. DNSSEC membuktikan jawaban itu asli; ia tidak menyembunyikannya.","Adds records":"Menambah record","Checked by":"Diperiksa oleh","Trust anchor":"Jangkar kepercayaan","The root’s key (built in)":"Kunci root (tertanam)","Hides queries":"Menyembunyikan kueri","No (that’s DoH)":"Tidak (itu tugas DoH)","Answer checked":"Jawaban diperiksa","A chain of signatures to the root":"Rantai tanda tangan hingga ke root","The resolver followed a chain: the address was signed by example.com’s key, that key by its key-signing key, which .com vouched for with a signed DS record, and .com’s key is vouched for by the root, whose key the resolver has built in. A forged answer would have broken the chain. Press REPLAY to watch it again.":"Resolver mengikuti rantai: alamat ditandatangani dengan kunci example.com, kunci itu dengan kunci penanda kuncinya, yang dijamin .com dengan record DS bertanda tangan, dan kunci .com dijamin oleh root, yang kuncinya tertanam di resolver. Jawaban palsu akan memutus rantai itu. Tekan ULANGI untuk menontonnya lagi.","Signatures checked":"Tanda tangan diperiksa","3 here (plus cached ones)":"3 di sini (plus yang ada di cache)","The AD flag":"Flag AD","Forged answer":"Jawaban palsu","Fails the check":"Gagal pemeriksaan","Ask as Usual":"Bertanya seperti biasa","The laptop’s question doesn’t change":"Pertanyaan laptop tidak berubah","The laptop asks its resolver for www.example.com as always. The checking happens at the resolver, which asks the name servers with the DNSSEC OK flag set: send the signatures too.":"Laptop menanyakan www.example.com ke resolvernya seperti biasa. Pemeriksaan terjadi di resolver, yang bertanya ke server nama dengan flag DNSSEC OK aktif: kirim tanda tangannya juga.","Checking done by":"Pemeriksaan oleh","The resolver (8.8.8.8)":"Resolver (8.8.8.8)","Resolver sets":"Resolver mengaktifkan","Signed Answer":"Jawaban bertanda tangan","An RRSIG comes with the A record":"RRSIG menyertai record A","The resolver already knows example.com’s name server from earlier lookups. That server sends the address with an RRSIG record: a signature over the A record, made with the zone’s private key. The RRSIG says which key signed it (key 47362, the zone-signing key) and when the signature expires. To check it the resolver needs that key.":"Resolver sudah tahu server nama example.com dari pencarian sebelumnya. Server itu mengirim alamat beserta record RRSIG: tanda tangan atas record A, dibuat dengan kunci privat zona. RRSIG menyebutkan kunci mana yang menandatanganinya (kunci 47362, kunci penanda zona) dan kapan tanda tangan itu kedaluwarsa. Untuk memeriksanya, resolver butuh kunci itu.","RRSIG by key 47362":"RRSIG oleh kunci 47362",Valid:"Berlaku","31 Oct to 21 Nov 2026":"31 Okt sampai 21 Nov 2026","signed by key 47362":"ditandatangani kunci 47362","The Zone’s Keys":"Kunci-kunci zona","DNSKEY records, signed too":"Record DNSKEY, juga bertanda tangan","The resolver asks for example.com’s keys. There are two: the zone-signing key (flags 256) that signed the A record, and the key-signing key (flags 257), which signs only the set of keys. With them the resolver checks both signatures. But who says these keys belong to example.com?":"Resolver meminta kunci example.com. Ada dua: kunci penanda zona (flag 256) yang menandatangani record A, dan kunci penanda kunci (flag 257), yang hanya menandatangani kumpulan kunci. Dengan keduanya resolver memeriksa kedua tanda tangan. Tapi siapa yang menjamin kunci ini milik example.com?","47362, zone-signing (256)":"47362, penanda zona (256)","61845, key-signing (257)":"61845, penanda kunci (257)","Keys signed by":"Kunci diteken oleh","The key-signing key":"Kunci penanda kunci","two keys":"dua kunci","signed by key 61845":"ditandatangani kunci 61845","Vouched by .com":"Dijamin oleh .com","The parent’s DS record":"Record DS milik zona induk","The parent zone answers that. The .com servers hold a DS record for example.com: a hash of its key-signing key, signed with .com’s own key. If the hash matches key 61845, the keys are example.com’s, as far as .com is concerned.":"Zona induk yang menjawabnya. Server .com menyimpan record DS untuk example.com: hash dari kunci penanda kuncinya, ditandatangani dengan kunci .com sendiri. Jika hash cocok dengan kunci 61845, kunci-kunci itu milik example.com, setidaknya menurut .com.","Hash of key 61845":"Hash kunci 61845","Signed by":"Ditandatangani oleh",".com (key 19718)":".com (kunci 19718)",Matches:"Cocok dengan","hash of key 61845":"hash kunci 61845","signed by .com":"ditandatangani .com","Up to the Root":"Hingga ke root","Where the chain ends":"Tempat rantai berakhir","The same goes on above: .com’s keys are vouched for by a DS record in the root zone, signed by the root’s key, and that key is built into every validating resolver: the trust anchor. The resolver had those links cached, so the chain is complete: root → .com → example.com → the address.":"Hal yang sama berlanjut ke atas: kunci .com dijamin oleh record DS di zona root, ditandatangani dengan kunci root, dan kunci itu tertanam di setiap resolver yang memvalidasi: jangkar kepercayaan. Resolver sudah punya mata rantai itu di cache, jadi rantainya lengkap: root → .com → example.com → alamat.",".com’s key":"Kunci .com","Vouched for by the root":"Dijamin oleh root","Root’s key":"Kunci root","Built in (trust anchor)":"Tertanam (jangkar kepercayaan)","Root → .com → example.com":"Root → .com → example.com","CHAIN OF TRUST CHECKED":"RANTAI KEPERCAYAAN DIPERIKSA","A Checked Answer":"Jawaban yang diperiksa","With the AD flag":"Dengan flag AD","The resolver answers the laptop with the address and the AD flag: authenticated data. Had any signature failed, the laptop would have got an error (SERVFAIL) instead of a forged address. DNSSEC doesn’t hide the question or the answer; for that there is DNS over HTTPS.":"Resolver menjawab laptop dengan alamat dan flag AD: data terautentikasi. Seandainya ada tanda tangan yang gagal, laptop akan menerima galat (SERVFAIL), bukan alamat palsu. DNSSEC tidak menyembunyikan pertanyaan maupun jawaban; untuk itu ada DNS over HTTPS.",Flag:"Flag","AD (authenticated data)":"AD (data terautentikasi)","Bad signature":"Tanda tangan buruk","SERVFAIL, no address":"SERVFAIL, tanpa alamat","AD: checked":"AD: diperiksa","UDP size 1232, DNSSEC OK = 1":"Ukuran UDP 1232, DNSSEC OK = 1","Says how big a UDP answer can be, and DNSSEC OK: send the signatures too.":"Menyatakan seberapa besar jawaban UDP boleh, dan DNSSEC OK: kirim tanda tangannya juga.","www.example.com RRSIG A, signed by example.com key 47362, valid 2026-10-31 to 2026-11-21 (TTL 3,600 s)":"www.example.com RRSIG A, ditandatangani kunci example.com 47362, berlaku 2026-10-31 sampai 2026-11-21 (TTL 3,600 s)","A signature over the records above it, made with the zone’s private key.":"Tanda tangan atas record di atasnya, dibuat dengan kunci privat zona.","example.com, type DNSKEY, class IN":"example.com, tipe DNSKEY, kelas IN","example.com DNSKEY 256 (zone-signing key 47362), ECDSA P-256 (TTL 3,600 s)":"example.com DNSKEY 256 (kunci penanda zona 47362), ECDSA P-256 (TTL 3,600 s)","One of the zone’s public keys; whoever checks a signature needs it.":"Salah satu kunci publik zona; siapa pun yang memeriksa tanda tangan membutuhkannya.","example.com DNSKEY 257 (key-signing key 61845), ECDSA P-256 (TTL 3,600 s)":"example.com DNSKEY 257 (kunci penanda kunci 61845), ECDSA P-256 (TTL 3,600 s)","example.com RRSIG DNSKEY, signed by example.com key 61845, valid 2026-10-31 to 2026-11-21 (TTL 3,600 s)":"example.com RRSIG DNSKEY, ditandatangani kunci example.com 61845, berlaku 2026-10-31 sampai 2026-11-21 (TTL 3,600 s)","example.com, type DS, class IN":"example.com, tipe DS, kelas IN","example.com DS key 61845, SHA-256 digest (TTL 86,400 s)":"example.com DS kunci 61845, digest SHA-256 (TTL 86,400 s)","A hash of the child zone’s key-signing key, kept and signed by the parent zone.":"Hash dari kunci penanda kunci zona anak, disimpan dan ditandatangani oleh zona induk.","example.com RRSIG DS, signed by com key 19718, valid 2026-10-31 to 2026-11-21 (TTL 86,400 s)":"example.com RRSIG DS, ditandatangani kunci com 19718, berlaku 2026-10-31 sampai 2026-11-21 (TTL 86,400 s)","0x81a0: response, RD (recursion desired), RA (recursion available), AD (authenticated data)":"0x81a0: respons, RD (rekursi diminta), RA (rekursi tersedia), AD (data terautentikasi)","Wi-Fi Logins":"Login Wi-Fi","EAP over Wi-Fi":"EAP lewat Wi-Fi","RADIUS Server":"Server RADIUS","RADIUS and 802.1X (Enterprise Wi-Fi)":"RADIUS dan 802.1X (Wi-Fi perusahaan)","At home everyone shares one Wi-Fi password. Offices, universities and eduroam use WPA2- or WPA3-Enterprise instead: each person or device logs in with its own account or certificate, checked by a RADIUS server. The access point knows no passwords. It passes the login, a series of EAP messages, between the laptop and the server, and lets the laptop in only when the server says yes.":"Di rumah semua orang memakai satu kata sandi Wi-Fi. Kantor, universitas, dan eduroam memakai WPA2- atau WPA3-Enterprise: setiap orang atau perangkat login dengan akun atau sertifikatnya sendiri, yang diperiksa server RADIUS. Titik akses tidak tahu kata sandi apa pun. Ia meneruskan proses login, serangkaian pesan EAP, antara laptop dan server, dan baru membolehkan laptop masuk saat server berkata ya.","EAP (here EAP-TLS)":"EAP (di sini EAP-TLS)",Keys:"Kunci","Different for every login":"Berbeda setiap login","Let in":"Diizinkan masuk","Its own login, its own keys":"Login sendiri, kunci sendiri","The laptop proved who it was with its certificate. The RADIUS server checked it and told the access point to let it in, on VLAN 20, with a key for this login alone. The access point never saw a password: it only passed the messages on. Press REPLAY to watch it again.":"Laptop membuktikan siapa dirinya dengan sertifikatnya. Server RADIUS memeriksanya dan menyuruh titik akses membolehkannya masuk, di VLAN 20, dengan kunci khusus untuk login ini. Titik akses tidak pernah melihat kata sandi: ia hanya meneruskan pesan. Tekan ULANGI untuk menontonnya lagi.","EAP-TLS (certificates)":"EAP-TLS (sertifikat)","17, then the 4-way handshake":"17, lalu handshake 4 arah","20 (staff)":"20 (staf)","A user leaves":"Seseorang keluar","Disable one account":"Nonaktifkan satu akun","Who Are You?":"Siapa Anda?","The access point asks for an identity":"Titik akses meminta identitas","The laptop has joined “Office”, a WPA2-Enterprise network, but until it has logged in the access point passes on nothing except login messages. It asks who the laptop is with an EAP Identity request, and the laptop answers alex@example.org. The access point knows no accounts: it will pass the answer on to the RADIUS server.":"Laptop sudah bergabung dengan “Office”, jaringan WPA2-Enterprise, tetapi sampai ia login, titik akses tidak meneruskan apa pun kecuali pesan login. Titik akses menanyakan siapa laptop itu dengan permintaan EAP Identity, dan laptop menjawab alex@example.org. Titik akses tidak tahu akun apa pun: ia akan meneruskan jawaban itu ke server RADIUS.","Before login":"Sebelum login","Only EAP gets through":"Hanya EAP yang lewat","IDENTITY?":"IDENTITAS?","EAP Identity request":"Permintaan EAP Identity",IDENTITY:"IDENTITAS","Ask RADIUS":"Tanya RADIUS","The login goes to the server":"Login dikirim ke server","The access point copies the EAP message into a RADIUS Access-Request and sends it to the RADIUS server on UDP port 1812, with the laptop’s MAC address and the network’s name. A secret that only the two of them share protects every packet. The server answers with an Access-Challenge: the next message for the laptop, which is “start EAP-TLS”.":"Titik akses menyalin pesan EAP ke dalam RADIUS Access-Request dan mengirimnya ke server RADIUS di port UDP 1812, beserta alamat MAC laptop dan nama jaringan. Rahasia yang hanya dimiliki keduanya melindungi setiap paket. Server menjawab dengan Access-Challenge: pesan berikutnya untuk laptop, yaitu “mulai EAP-TLS”.","RADIUS server, UDP 1812":"Server RADIUS, UDP 1812","A shared secret":"Rahasia bersama","from the access point":"dari titik akses","EAP-TLS start":"mulai EAP-TLS","TLS START":"MULAI TLS","TLS Inside EAP":"TLS di dalam EAP","The server proves who it is":"Server membuktikan siapa dirinya","The laptop and the server now run a TLS 1.3 handshake inside EAP; the access point repacks each message, EAPOL over the air and RADIUS on the wire. The server sends its certificate and asks for the laptop’s. The laptop checks that it was issued by the company’s own certificate authority to radius.example.org. That check is what stops a fake access point from catching the login.":"Laptop dan server kini menjalankan handshake TLS 1.3 di dalam EAP; titik akses mengemas ulang setiap pesan, EAPOL lewat udara dan RADIUS lewat kabel. Server mengirim sertifikatnya dan meminta sertifikat laptop. Laptop memeriksa bahwa sertifikat itu diterbitkan oleh otoritas sertifikat milik perusahaan untuk radius.example.org. Pemeriksaan itulah yang mencegah titik akses palsu menangkap login.","TLS 1.3, inside EAP":"TLS 1.3, di dalam EAP","Its certificate":"Sertifikatnya","Laptop checks":"Laptop memeriksa","Issuer and name":"Penerbit dan nama","TLS inside EAP":"TLS di dalam EAP","certificate (encrypted)":"sertifikat (terenkripsi)","Laptop’s Proof":"Bukti dari laptop","Its own certificate":"Sertifikatnya sendiri","The laptop answers with its own certificate, which the company issued for this user, and a signature made with its private key; the key never leaves the laptop. No password is involved. The server checks the certificate and the signature and looks up the account. Many networks, eduroam among them, use a password instead, sent inside the TLS tunnel (PEAP or EAP-TTLS).":"Laptop menjawab dengan sertifikatnya sendiri, yang diterbitkan perusahaan untuk pengguna ini, dan tanda tangan yang dibuat dengan kunci privatnya; kunci itu tidak pernah keluar dari laptop. Tidak ada kata sandi yang terlibat. Server memeriksa sertifikat dan tanda tangan lalu mencari akunnya. Banyak jaringan, termasuk eduroam, memakai kata sandi sebagai gantinya, yang dikirim di dalam terowongan TLS (PEAP atau EAP-TTLS).","Its certificate, a signature":"Sertifikatnya, tanda tangan","None with EAP-TLS":"Tidak ada dengan EAP-TLS","Or instead":"Atau sebagai gantinya","PEAP: a password in TLS":"PEAP: kata sandi di dalam TLS",CERTIFICATE:"SERTIFIKAT","laptop’s certificate":"sertifikat laptop","Handshake Done":"Handshake selesai","Nothing more to send":"Tak ada lagi yang dikirim","With TLS 1.3 the server then sends one tiny encrypted message, a single zero byte, to say the handshake is over, and the laptop answers with an empty EAP message. Both ends now hold the same 64 bytes of key material, worked out during the handshake. Nobody on the way has seen it, not even the access point.":"Dengan TLS 1.3, server lalu mengirim satu pesan terenkripsi yang sangat kecil, satu byte nol, untuk menyatakan handshake selesai, dan laptop menjawab dengan pesan EAP kosong. Kedua ujung kini memegang 64 byte material kunci yang sama, yang dihitung selama handshake. Tak seorang pun di jalan melihatnya, bahkan titik akses pun tidak.","Server sends":"Server mengirim","One encrypted 0 byte":"Satu byte 0 terenkripsi","An empty EAP-TLS reply":"Balasan EAP-TLS kosong","Both hold":"Keduanya memegang","64 bytes of key material":"64 byte material kunci","handshake over":"handshake selesai","one encrypted byte":"satu byte terenkripsi",EMPTY:"KOSONG","nothing more":"tak ada lagi","empty EAP-TLS":"EAP-TLS kosong","And a key for the access point":"Dan kunci untuk titik akses","The server answers Access-Accept. Inside are EAP Success for the laptop; the first 32 bytes of the key material for the access point, encrypted with the shared secret (MS-MPPE-Recv-Key); and VLAN 20, so this user lands on the staff network. The same access point could put another user on another VLAN.":"Server menjawab Access-Accept. Di dalamnya ada EAP Success untuk laptop; 32 byte pertama material kunci untuk titik akses, dienkripsi dengan rahasia bersama (MS-MPPE-Recv-Key); dan VLAN 20, supaya pengguna ini masuk ke jaringan staf. Titik akses yang sama bisa menempatkan pengguna lain di VLAN lain.","AP gets":"Titik akses mendapat","The key (MS-MPPE-Recv-Key)":"Kuncinya (MS-MPPE-Recv-Key)","key, VLAN 20":"kunci, VLAN 20","4-Way Handshake":"Handshake 4 arah","As at home, from a different key":"Seperti di rumah, dari kunci yang berbeda","The access point and the laptop now hold the same 32-byte key, the PMK. What follows is the 4-way handshake from the Wi-Fi lesson; only the PMK’s origin differs. At home it comes from the shared password, here from this one login, so every user gets different keys.":"Titik akses dan laptop kini memegang kunci 32 byte yang sama, yaitu PMK. Selanjutnya adalah handshake 4 arah dari pelajaran Wi-Fi; hanya asal PMK yang berbeda. Di rumah PMK berasal dari kata sandi bersama, di sini dari login yang satu ini, jadi setiap pengguna mendapat kunci yang berbeda.","PMK from":"PMK dari","This login":"Login ini","At home":"Di rumah","From the shared password":"Dari kata sandi bersama","Encrypted data (CCMP)":"Data terenkripsi (CCMP)","group key, MIC":"kunci grup, MIC","Why Enterprise":"Mengapa Enterprise","One account per person":"Satu akun per orang","When someone leaves, their account is disabled and nobody else changes a password. Every login gets its own keys, so users can’t read each other’s traffic, and the RADIUS server records who connected and when. eduroam works the same way: a visitor’s login for user@their-university is passed from RADIUS server to RADIUS server until it reaches their own university.":"Saat seseorang keluar, akunnya dinonaktifkan dan tak ada orang lain yang perlu mengganti kata sandi. Setiap login mendapat kuncinya sendiri, jadi pengguna tidak bisa membaca lalu lintas satu sama lain, dan server RADIUS mencatat siapa yang terhubung dan kapan. eduroam bekerja dengan cara yang sama: login tamu sebagai user@their-university diteruskan dari server RADIUS ke server RADIUS hingga sampai ke universitasnya sendiri.","Different for every user":"Berbeda untuk setiap pengguna",eduroam:"eduroam","Login passed home":"Login diteruskan pulang","ONE ACCOUNT PER PERSON":"SATU AKUN PER ORANG","Access-Challenge id=82: Server Hello, certificate":"Access-Challenge id=82: Server Hello, sertifikat","Request, TLS EAP: Server Hello, encrypted handshake":"Request, TLS EAP: Server Hello, handshake terenkripsi","Response, TLS EAP: encrypted handshake":"Response, TLS EAP: handshake terenkripsi","Access-Request id=83: encrypted handshake":"Access-Request id=83: handshake terenkripsi","0 (EAP packet)":"0 (paket EAP)","Carries an EAP message. The access point copies it into a RADIUS packet for the server, and back.":"Membawa pesan EAP. Titik akses menyalinnya ke paket RADIUS untuk server, dan sebaliknya.","A response carries the same number as the request it answers.":"Respons membawa nomor yang sama dengan permintaan yang dijawabnya.","Who are you?":"Siapa Anda?","Who is logging in. The realm after the @ tells the RADIUS server (or the servers that pass requests on) where the account lives.":"Siapa yang login. Realm setelah @ memberi tahu server RADIUS (atau server yang meneruskan permintaan) di mana akun itu berada.","Seen on the office network":"Terlihat di jaringan kantor","The server. It is on the same network, so the frame goes straight to it, not through the router.":"Server. Ia ada di jaringan yang sama, jadi frame langsung menuju ke sana, tidak lewat router.","The access point’s wired port.":"Port kabel titik akses.","Should this device be let in?":"Haruskah perangkat ini diizinkan masuk?","A reply carries the number of the request it answers.":"Balasan membawa nomor permintaan yang dijawabnya.",Authenticator:"Authenticator","Random, new in every request.":"Acak, baru di setiap permintaan.",Attributes:"Atribut","An HMAC-MD5 of the whole packet, keyed with the shared secret. Every packet that carries EAP must have one; since the Blast-RADIUS attack of 2024, it goes first.":"HMAC-MD5 dari seluruh paket, dengan rahasia bersama sebagai kunci. Setiap paket yang membawa EAP harus punya satu; sejak serangan Blast-RADIUS tahun 2024, atribut ini ditaruh paling depan.","The identity the laptop gave.":"Identitas yang diberikan laptop.","The access point asking.":"Titik akses yang bertanya.","The access point’s MAC address and the network’s name.":"Alamat MAC titik akses dan nama jaringan.","The laptop’s MAC address.":"Alamat MAC laptop.","Keep each EAP message small enough for one frame.":"Jaga setiap pesan EAP cukup kecil untuk satu frame.","The EAP packet, passed on unchanged.":"Paket EAP, diteruskan tanpa diubah.","The server’s network card.":"Kartu jaringan server.","Not yet: here is the next message for the device.":"Belum: ini pesan berikutnya untuk perangkat.","A hash of this reply, the request’s authenticator and the shared secret: only the real server could have made it.":"Hash dari balasan ini, authenticator permintaan, dan rahasia bersama: hanya server asli yang bisa membuatnya.","A TLS handshake, carried inside EAP.":"Handshake TLS, dibawa di dalam EAP.","0x20 (start)":"0x20 (mulai)","Start: the server is ready for the laptop’s Client Hello.":"Mulai: server siap menerima Client Hello dari laptop.","The server’s bookmark for this login: the access point sends it back with the next request.":"Penanda server untuk login ini: titik akses mengirimkannya kembali bersama permintaan berikutnya.","0x80 (length included)":"0x80 (dengan panjang)","TLS length":"Panjang TLS","Longer TLS messages are split into pieces of about 1,000 bytes, each one acknowledged.":"Pesan TLS yang lebih panjang dipecah menjadi bagian sekitar 1,000 byte, masing-masing dikonfirmasi.","TLS records":"Record TLS","The same TLS records as over TCP, only carried in EAP.":"Record TLS yang sama seperti lewat TCP, hanya dibawa dalam EAP.","Client Hello: TLS 1.3, the laptop’s key share":"Client Hello: TLS 1.3, key share laptop","The EAP packet (1,008 bytes), split over 4 attributes of up to 253 bytes.":"Paket EAP (1,008 byte), dibagi ke 4 atribut berukuran hingga 253 byte.","EAP-Message, continued":"EAP-Message, lanjutan","TLS records, continued":"Record TLS, lanjutan","Server Hello: TLS 1.3, the server’s key share":"Server Hello: TLS 1.3, key share server","Encrypted: certificate for radius.example.org, a request for the laptop’s certificate, signature, Finished":"Terenkripsi: sertifikat untuk radius.example.org, permintaan sertifikat laptop, tanda tangan, Finished","Encrypted: the laptop’s certificate (for alex@example.org), its signature, Finished":"Terenkripsi: sertifikat laptop (untuk alex@example.org), tanda tangannya, Finished","The EAP packet (822 bytes), split over 4 attributes of up to 253 bytes.":"Paket EAP (822 byte), dibagi ke 4 atribut berukuran hingga 253 byte.","Encrypted: one 0 byte, the “commitment message”: no more handshake messages":"Terenkripsi: satu byte 0, “pesan komitmen”: tidak ada pesan handshake lagi","0x00 (no data)":"0x00 (tanpa data)","Nothing to send: an empty answer that keeps the conversation going.":"Tak ada yang dikirim: jawaban kosong yang menjaga percakapan tetap berjalan.","Yes: let it in.":"Ya: izinkan masuk.","Put this device on VLAN 20, the staff network.":"Tempatkan perangkat ini di VLAN 20, jaringan staf.","The first 32 bytes of the key material that both ends of the TLS handshake worked out. The access point uses it as the PMK, the starting key for the 4-way handshake.":"32 byte pertama material kunci yang dihitung kedua ujung handshake TLS. Titik akses memakainya sebagai PMK, kunci awal untuk handshake 4 arah.","Salt, encrypted key":"Salt, kunci terenkripsi","Encrypted with the shared secret, so only the access point can read the key.":"Dienkripsi dengan rahasia bersama, jadi hanya titik akses yang bisa membaca kuncinya.","The next 32 bytes of the key material. Wi-Fi doesn’t need them.":"32 byte berikutnya dari material kunci. Wi-Fi tidak membutuhkannya.","The RADIUS server accepted the login.":"Server RADIUS menerima login tersebut.","1: 802.1X (logins checked by a RADIUS server)":"1: 802.1X (login diperiksa oleh server RADIUS)","Shared Folders":"Folder bersama",Responses:"Respons","nas (File Server)":"nas (server file)","Server Message Block (SMB 3)":"Server Message Block (SMB 3)","SMB is how Windows shares files and printers: \\\\server\\share in File Explorer, a mapped network drive, a NAS at home. macOS and Linux speak it too. Over one TCP connection to port 445 the client agrees on a version, logs in and connects to a share, then opens, reads, writes and closes files with numbered requests.":"SMB adalah cara Windows berbagi file dan printer: \\\\server\\share di File Explorer, drive jaringan yang dipetakan, NAS di rumah. macOS dan Linux juga memakainya. Lewat satu koneksi TCP ke port 445, klien menyepakati versi, login, dan terhubung ke share, lalu membuka, membaca, menulis, dan menutup file dengan permintaan bernomor.","TCP 445":"TCP 445","NTLM or Kerberos":"NTLM atau Kerberos",Protection:"Perlindungan","Signing, optional encryption":"Penandatanganan, enkripsi opsional","File read":"File terbaca","Seven requests, one connection":"Tujuh permintaan, satu koneksi","Over one TCP connection the laptop agreed on SMB 3.1.1, logged in with NTLM without sending its password, connected to the share and read a 240 KB file with a single request. Every message after the login was signed. Press REPLAY to watch it again.":"Lewat satu koneksi TCP, laptop menyepakati SMB 3.1.1, login dengan NTLM tanpa mengirim kata sandinya, terhubung ke share, dan membaca file 240 KB dengan satu permintaan. Setiap pesan setelah login ditandatangani. Tekan ULANGI untuk menontonnya lagi.","7 on one connection":"7 di satu koneksi","NTLMv2, no password sent":"NTLMv2, tanpa mengirim kata sandi","240 KB in 169 segments":"240 KB dalam 169 segmen",Signed:"Ditandatangani","Every message after login":"Setiap pesan setelah login","Port 445":"Port 445","A TCP connection to the NAS":"Koneksi TCP ke NAS","The laptop opens \\\\nas\\Documents, a shared folder on the NAS. It finds nas’s address with a local name lookup and opens a TCP connection to port 445. The packets pass through the home router to the NAS and never leave the home network.":"Laptop membuka \\\\nas\\Documents, folder bersama di NAS. Ia menemukan alamat nas dengan pencarian nama lokal dan membuka koneksi TCP ke port 445. Paket lewat router rumah menuju NAS dan tidak pernah keluar dari jaringan rumah.","nas, 192.168.1.20":"nas, 192.168.1.20",Stays:"Tetap","On the home network":"Di jaringan rumah",Negotiate:"Negosiasi","Agree on a version":"Menyepakati versi","The laptop lists every SMB version it speaks, from 2.0.2 to 3.1.1, and says it requires signing. The NAS picks 3.1.1, the newest. Both sides keep a SHA-512 hash of everything exchanged from here until the login is done. It goes into the keys, so if anyone changed these messages on the way, to force an older version for instance, the login would fail.":"Laptop mendaftar setiap versi SMB yang ia pahami, dari 2.0.2 hingga 3.1.1, dan menyatakan bahwa ia mewajibkan penandatanganan. NAS memilih 3.1.1, yang terbaru. Kedua pihak menyimpan hash SHA-512 dari semua yang dipertukarkan dari sini sampai login selesai. Hash itu masuk ke dalam kunci, jadi jika ada yang mengubah pesan-pesan ini di jalan, misalnya untuk memaksakan versi lama, login akan gagal.",Chosen:"Dipilih","Tamper check":"Pemeriksaan pengubahan","SHA-512 of the exchange":"SHA-512 dari pertukaran","signing required":"tanda tangan wajib","NTLM Challenge":"Tantangan NTLM","The NAS sends a random number":"NAS mengirim angka acak","A home NAS has no domain, so there is no Kerberos: the laptop logs in with NTLM. Its first SESSION_SETUP says it wants to log in, and the NAS answers “more processing required” with a challenge of 8 random bytes. It also gives this login a session ID.":"NAS rumahan tidak punya domain, jadi tidak ada Kerberos: laptop login dengan NTLM. SESSION_SETUP pertamanya menyatakan ingin login, dan NAS menjawab “perlu pemrosesan lebih lanjut” dengan tantangan berupa 8 byte acak. NAS juga memberi login ini sebuah ID sesi.","NTLMv2 (in a domain: Kerberos)":"NTLMv2 (di domain: Kerberos)",Challenge:"Tantangan","More processing required":"Perlu pemrosesan lebih lanjut","NTLM: let me log in":"NTLM: izinkan saya login","a session ID":"sebuah ID sesi","NTLM Response":"Respons NTLM","Proof, not the password":"Bukti, bukan kata sandi","The laptop answers with the user name, alex, and an NTLMv2 response: an HMAC of the challenge and a few other values, keyed with a hash of the password. The NAS has the same hash and works out the same value. The password itself never crosses the network, and both sides now have a session key to sign messages with.":"Laptop menjawab dengan nama pengguna, alex, dan respons NTLMv2: HMAC dari tantangan dan beberapa nilai lain, dengan hash kata sandi sebagai kunci. NAS punya hash yang sama dan menghitung nilai yang sama. Kata sandinya sendiri tidak pernah melintasi jaringan, dan kedua pihak kini punya kunci sesi untuk menandatangani pesan.",User:"Pengguna",alex:"alex",Sends:"Mengirim","An HMAC of the challenge":"HMAC dari tantangan","Never sent":"Tak pernah dikirim","user alex":"pengguna alex","NTLMv2 response":"respons NTLMv2","LOGGED IN":"SUDAH LOGIN",signed:"ditandatangani","Connect a Share":"Menghubungkan share","\\\\nas\\Documents":"\\\\nas\\Documents","TREE_CONNECT asks for the share by its full name, \\\\nas\\Documents. The answer gives it a tree ID and says what this user may do there. Every message is now signed: each carries a tag over the whole message, made with a key from the login, so a changed or forged message would be caught.":"TREE_CONNECT meminta share dengan nama lengkapnya, \\\\nas\\Documents. Jawabannya memberi share itu tree ID dan menyatakan apa yang boleh dilakukan pengguna ini di sana. Kini setiap pesan ditandatangani: masing-masing membawa tag atas seluruh pesan, dibuat dengan kunci dari login, jadi pesan yang diubah atau dipalsukan akan ketahuan.",Share:"Share","Every message":"Setiap pesan","Signed (AES-GMAC)":"Ditandatangani (AES-GMAC)","tree ID 0x2a51":"tree ID 0x2a51","Open the File":"Membuka file","With CREATE":"Dengan CREATE","SMB opens files with CREATE, which can also make new ones. This one opens report.pdf to read it, and fails if it doesn’t exist. The answer gives the file’s size and dates, and a file ID that the read and the close will use.":"SMB membuka file dengan CREATE, yang juga bisa membuat file baru. Permintaan ini membuka report.pdf untuk dibaca, dan gagal jika file itu tidak ada. Jawabannya memberi ukuran dan tanggal file, serta file ID yang akan dipakai untuk membaca dan menutup.",Handle:"Handle","A 16-byte file ID":"File ID 16 byte","open to read":"buka untuk dibaca","file ID":"file ID","Read It":"Membacanya","The whole file in one request":"Seluruh file dalam satu permintaan","One READ asks for the whole file, 245,760 bytes from offset 0. It costs 4 credits, one for every 64 KB. The answer is 80 bytes of headers and then the file, in 169 TCP segments. A bigger file is read with several requests, many on their way at once, as far as the credits allow.":"Satu READ meminta seluruh file, 245,760 byte dari offset 0. Biayanya 4 kredit, satu per 64 KB. Jawabannya berupa header 80 byte lalu file itu, dalam 169 segmen TCP. File yang lebih besar dibaca dengan beberapa permintaan, banyak yang sedang berjalan sekaligus, sejauh kredit mengizinkan.","245,760 bytes from 0":"245,760 byte dari 0",Credits:"Kredit","4 (one per 64 KB)":"4 (satu per 64 KB)","Arrives in":"Tiba dalam","from offset 0":"dari offset 0","Close the File":"Menutup file","And keep 445 at home":"Dan jaga port 445 tetap di rumah","CLOSE hands the file ID back; the connection stays open for the next file. SMB 3 can also encrypt every message with AES-GCM, for one share or a whole server. Here only signing protects the messages, so anyone on the network could read the file as it passed. Port 445 should never be reachable from the internet: the WannaCry worm (2017) spread through a flaw in the old SMB1.":"CLOSE mengembalikan file ID; koneksi tetap terbuka untuk file berikutnya. SMB 3 juga bisa mengenkripsi setiap pesan dengan AES-GCM, untuk satu share atau seluruh server. Di sini hanya penandatanganan yang melindungi pesan, jadi siapa pun di jaringan bisa membaca file saat lewat. Port 445 tidak boleh bisa dijangkau dari internet: worm WannaCry (2017) menyebar lewat celah di SMB1 yang lama.","SMB 3: AES-GCM, optional":"SMB 3: AES-GCM, opsional","Switched off: old, unsafe":"Dimatikan: lama, tidak aman","Never open to the internet":"Jangan pernah dibuka ke internet",done:"selesai","KEEP PORT 445 OFF THE INTERNET":"JAUHKAN PORT 445 DARI INTERNET","On port 445 every SMB message starts with its length, a leftover from NetBIOS.":"Di port 445 setiap pesan SMB diawali panjangnya, sisa dari NetBIOS.",'0xFE "SMB" (SMB2 or 3)':'0xFE "SMB" (SMB2 atau 3)','SMB1 messages started 0xFF "SMB". SMB1 is switched off in Windows today.':'Pesan SMB1 diawali 0xFF "SMB". SMB1 kini dimatikan di Windows.',"Header size":"Ukuran header","Credit charge":"Biaya kredit","Channel sequence":"Urutan kanal","Credits asked for":"Kredit yang diminta","Credits limit how many requests the laptop may have waiting at once. The server hands them out.":"Kredit membatasi berapa banyak permintaan yang boleh ditunggu laptop sekaligus. Server yang membagikannya.","Next command":"Perintah berikutnya","0 (none chained)":"0 (tidak ada yang dirangkai)","Counts up with each request; the response carries the same number.":"Bertambah setiap permintaan; respons membawa nomor yang sama.","0 (no share yet)":"0 (belum ada share)","Session ID":"ID sesi","0 (not logged in yet)":"0 (belum login)","zeros (not signed)":"nol (tidak ditandatangani)","Structure size":"Ukuran struktur","Dialect count":"Jumlah dialek","Security mode":"Mode keamanan","0x0002 (signing required)":"0x0002 (tanda tangan wajib)","Recent versions of Windows 11 require signing by default.":"Versi terbaru Windows 11 mewajibkan penandatanganan secara bawaan.","DFS, leases, large reads and writes, multichannel, persistent handles, directory leases, encryption.":"DFS, lease, baca dan tulis besar, multichannel, handle persisten, lease direktori, enkripsi.","Client GUID":"GUID klien","A random ID for this computer.":"ID acak untuk komputer ini.","Negotiate contexts":"Konteks negosiasi","at offset 112, 4 of them":"di offset 112, sebanyak 4",Dialects:"Dialek","Every version the laptop speaks. The server picks the newest it also knows.":"Setiap versi yang dipahami laptop. Server memilih yang terbaru yang juga ia pahami.",Contexts:"Konteks","SMB 3.1.1 extras, each in its own small block.":"Tambahan SMB 3.1.1, masing-masing dalam blok kecilnya sendiri.","Pre-authentication integrity: SHA-512, and a 32-byte random salt":"Integritas pra-autentikasi: SHA-512, dan salt acak 32 byte","Encryption: AES-128-GCM, AES-128-CCM, AES-256-GCM, AES-256-CCM":"Enkripsi: AES-128-GCM, AES-128-CCM, AES-256-GCM, AES-256-CCM","Signing: AES-GMAC, AES-CMAC, HMAC-SHA256":"Penandatanganan: AES-GMAC, AES-CMAC, HMAC-SHA256","The server’s name: nas":"Nama server: nas","Credits granted":"Kredit yang diberikan","0x00000001 (response)":"0x00000001 (respons)","0x0001 (signing enabled)":"0x0001 (penandatanganan aktif)",Dialect:"Dialek","The newest version both sides speak.":"Versi terbaru yang dipahami kedua pihak.","Context count":"Jumlah konteks","Server GUID":"GUID server","Leases, large reads and writes.":"Lease, baca dan tulis besar.","Largest read, write":"Baca, tulis terbesar","8 MB each":"masing-masing 8 MB","The most data one request may carry: transactions, reads and writes.":"Data terbanyak yang boleh dibawa satu permintaan: transaksi, baca, dan tulis.","System time":"Waktu sistem","7 Nov 2026, 09:41:00":"7 Nov 2026, 09:41:00","Security buffer":"Buffer keamanan","Context offset":"Offset konteks","Security blob":"Blob keamanan","GSS-API and SPNEGO wrapping, around NTLMSSP.":"Pembungkus GSS-API dan SPNEGO di sekitar NTLMSSP.","The login methods the server accepts: NTLMSSP":"Metode login yang diterima server: NTLMSSP","Pre-authentication integrity: SHA-512, and the server’s own salt":"Integritas pra-autentikasi: SHA-512, dan salt milik server","Encryption: AES-128-GCM":"Enkripsi: AES-128-GCM","Signing: AES-GMAC":"Penandatanganan: AES-GMAC","0x02 (signing required)":"0x02 (tanda tangan wajib)","Previous session":"Sesi sebelumnya","NTLMSSP NEGOTIATE: the NTLM options the laptop supports":"NTLMSSP NEGOTIATE: opsi NTLM yang didukung laptop","Not an error: the login needs another round.":"Bukan galat: login butuh satu putaran lagi.","The server’s number for this login, from now on in every message.":"Nomor dari server untuk login ini, mulai sekarang ada di setiap pesan.","Session flags":"Flag sesi","NTLMSSP CHALLENGE: an 8-byte random challenge":"NTLMSSP CHALLENGE: tantangan acak 8 byte","The NAS’s names and its clock":"Nama-nama NAS dan jamnya","NTLMSSP AUTH: user alex, computer ALEX-PC":"NTLMSSP AUTH: pengguna alex, komputer ALEX-PC","NTLMv2 response: an HMAC of the challenge, keyed with a hash of the password":"Respons NTLMv2: HMAC dari tantangan, dengan hash kata sandi sebagai kunci","A key for signing, encrypted":"Kunci penandatanganan, terenkripsi","0x00000009 (response, signed)":"0x00000009 (respons, ditandatangani)","AES-GMAC over the whole message, with a key from the login: a changed or forged message would be caught.":"AES-GMAC atas seluruh pesan, dengan kunci dari login: pesan yang diubah atau dipalsukan akan ketahuan.","The login is complete.":"Login selesai.","0x00000008 (signed)":"0x00000008 (ditandatangani)","Server and share name, in UTF-16.":"Nama server dan share, dalam UTF-16.","The number for this share; later requests carry it.":"Nomor untuk share ini; permintaan selanjutnya membawanya.","Share type":"Jenis share","1 (disk)":"1 (disk)","Share flags":"Flag share","Encryption not required for this share; signing still protects every message.":"Enkripsi tidak diwajibkan untuk share ini; penandatanganan tetap melindungi setiap pesan.","0x001f01ff (full control)":"0x001f01ff (kontrol penuh)","What this user may do in the share.":"Apa yang boleh dilakukan pengguna ini di share.","Oplock, impersonation":"Oplock, peniruan identitas","none, 2 (impersonation)":"tidak ada, 2 (peniruan identitas)","Desired access":"Akses yang diinginkan","0x00120089 (read)":"0x00120089 (baca)","Read the data, its attributes and its permissions.":"Membaca data, atributnya, dan izinnya.","File attributes":"Atribut file","Share access":"Akses bersama","0x00000001 (read)":"0x00000001 (baca)","Others may read the file while it is open, but not change it.":"Pihak lain boleh membaca file selama terbuka, tetapi tidak mengubahnya.",Disposition:"Disposisi","1 (open, fail if missing)":"1 (buka, gagal jika tidak ada)","0x00000040 (a file, not a folder)":"0x00000040 (file, bukan folder)",Name:"Nama","Create contexts":"Konteks pembuatan","File name":"Nama file","Relative to the share.":"Relatif terhadap share.","Oplock, flags":"Oplock, flag","none, 0":"tidak ada, 0",Action:"Tindakan","1 (opened)":"1 (dibuka)",Times:"Waktu","created, accessed, written, changed":"dibuat, diakses, ditulis, diubah","Windows FILETIME: 100-nanosecond steps since 1601.":"FILETIME Windows: langkah 100 nanodetik sejak 1601.","Allocation size":"Ukuran alokasi","File size":"Ukuran file","0x00000020 (archive)":"0x00000020 (arsip)","File ID":"File ID","The handle for the open file: reads and the close name it.":"Handle untuk file yang terbuka: pembacaan dan penutupan menyebutnya.","A big read costs one credit per 64 KB.":"Pembacaan besar memakan satu kredit per 64 KB.","Padding, flags":"Padding, flag","Where the server should put the data in its answer: 80 bytes in, right after the headers.":"Di mana server harus menaruh data dalam jawabannya: 80 byte ke dalam, tepat setelah header.","The whole file in one request.":"Seluruh file dalam satu permintaan.","Minimum, channel, remaining":"Minimum, kanal, sisa","Channel info":"Info kanal","Data offset":"Offset data","Data length":"Panjang data","Remaining, flags":"Sisa, flag","The file itself; its contents are not part of the lesson.":"File itu sendiri; isinya bukan bagian dari pelajaran.","The laptop didn’t ask for the file’s details, so the rest is zeros.":"Laptop tidak meminta rincian file, jadi sisanya nol.","Times, sizes, attributes":"Waktu, ukuran, atribut","Talking to a PLC":"Bicara dengan PLC",Switch:"Switch","Plant network":"Jaringan pabrik","Modbus/TCP, for industrial control":"Modbus/TCP, untuk kontrol industri","Modbus is one of the oldest and most widely used protocols in industrial control (OT, operational technology): PLCs, sensors, motor drives and meters in factories, water works and buildings speak it. A client reads and writes numbered registers and coils on a device. Modbus/TCP carries the same small messages over TCP port 502, with no login and no encryption.":"Modbus adalah salah satu protokol tertua dan paling banyak dipakai dalam kontrol industri (OT, teknologi operasional): PLC, sensor, penggerak motor, dan meter di pabrik, instalasi air, dan gedung memakainya. Klien membaca dan menulis register dan coil bernomor di sebuah perangkat. Modbus/TCP membawa pesan kecil yang sama lewat port TCP 502, tanpa login dan tanpa enkripsi.","1979, by Modicon":"1979, oleh Modicon","16-bit registers, on/off coils":"Register 16 bit, coil nyala/mati","None built in":"Tidak ada bawaan","Modbus.org specifications":"Spesifikasi Modbus.org","Pump running":"Pompa menyala","Simple, and wide open":"Sederhana, dan terbuka lebar","The laptop read four registers, changed a setpoint and started a pump, each with a 12-byte request and a short answer. No message carried a password and none was encrypted: Modbus trusts whoever can reach it, so the network around it has to do the protecting. Press REPLAY to watch it again.":"Laptop membaca empat register, mengubah setpoint, dan menyalakan pompa, masing-masing dengan permintaan 12 byte dan jawaban singkat. Tidak ada pesan yang membawa kata sandi dan tidak ada yang terenkripsi: Modbus memercayai siapa pun yang bisa menjangkaunya, jadi jaringan di sekitarnyalah yang harus melindunginya. Tekan ULANGI untuk menontonnya lagi.","4 requests, 4 answers":"4 permintaan, 4 jawaban",Biggest:"Terbesar","17 bytes (the read answer)":"17 byte (jawaban pembacaan)","Protect with":"Dilindungi dengan","Separate networks":"Jaringan terpisah","Port 502":"Port 502","A TCP connection to the PLC":"Koneksi TCP ke PLC","A PLC (programmable logic controller) runs a small pumping station: it reads the sensors and switches the pumps. An engineer’s laptop on the plant network talks to it in Modbus/TCP, so it opens a TCP connection to port 502. In Modbus terms the laptop is the client and the PLC the server.":"PLC (programmable logic controller) menjalankan sebuah stasiun pompa kecil: ia membaca sensor dan menyalakan atau mematikan pompa. Laptop seorang insinyur di jaringan pabrik berbicara dengannya dalam Modbus/TCP, jadi laptop membuka koneksi TCP ke port 502. Dalam istilah Modbus, laptop adalah klien dan PLC adalah server.",Roles:"Peran","Client asks, server answers":"Klien bertanya, server menjawab","Read Registers":"Membaca register","Function 3: four numbers":"Fungsi 3: empat angka","The laptop asks for 4 holding registers starting at address 0, with function code 3. The PLC answers with 8 bytes: four 16-bit numbers. What they mean (the tank level in centimetres, the temperature in tenths of a degree) is written only in the PLC’s documentation; the message carries no names and no units. An HMI screen sends reads like this every second or so.":"Laptop meminta 4 holding register mulai dari alamat 0, dengan kode fungsi 3. PLC menjawab dengan 8 byte: empat angka 16 bit. Artinya (ketinggian tangki dalam sentimeter, suhu dalam sepersepuluh derajat) hanya tertulis di dokumentasi PLC; pesannya tidak membawa nama maupun satuan. Layar HMI mengirim pembacaan seperti ini kira-kira setiap detik.",Function:"Fungsi","4 registers from 0":"4 register dari 0","function 3":"fungsi 3","registers 0–3":"register 0–3",VALUES:"NILAI","Write a Setpoint":"Menulis setpoint","Function 6: one register":"Fungsi 6: satu register","The engineer raises the tank’s level setpoint from 4.50 m to 5.00 m: function 6, write single register, register 3, value 500. The PLC answers by repeating the request, which means done. From now on its program keeps the tank fuller.":"Insinyur menaikkan setpoint ketinggian tangki dari 4.50 m menjadi 5.00 m: fungsi 6, tulis satu register, register 3, nilai 500. PLC menjawab dengan mengulang permintaan, yang berarti selesai. Mulai sekarang programnya menjaga tangki lebih penuh.","Register 3":"Register 3","The request, repeated":"Permintaan, diulang",WRITE:"TULIS","register 3 = 500":"register 3 = 500","Start a Pump":"Menyalakan pompa","Function 5: a coil":"Fungsi 5: sebuah coil","Coils are single on/off outputs. Function 5 writes one: coil 0, pump 2, value 0xFF00, which means on. The PLC switches the pump on and echoes the request. In a real plant the PLC’s own program usually decides this, with safety interlocks.":"Coil adalah keluaran nyala/mati tunggal. Fungsi 5 menulis satu: coil 0, pompa 2, nilai 0xFF00, yang berarti nyala. PLC menyalakan pompa dan memantulkan permintaan. Di pabrik sungguhan, biasanya program PLC sendiri yang memutuskan ini, dengan interlock keselamatan.","Coil 0":"Coil 0","Pump 2: on":"Pompa 2: nyala","0xFF00 (off: 0x0000)":"0xFF00 (mati: 0x0000)","COIL ON":"COIL NYALA","coil 0: pump 2":"coil 0: pompa 2","pump 2 on":"pompa 2 nyala","PUMP 2 RUNNING":"POMPA 2 MENYALA","An Exception":"Sebuah pengecualian","No such register":"Register itu tidak ada","A request for registers that don’t exist, here 100 and 101, gets an exception: the function code with its top bit set (3 + 128 = 131) and exception code 2, illegal data address. Other codes say the function isn’t supported or the device is busy.":"Permintaan untuk register yang tidak ada, di sini 100 dan 101, mendapat pengecualian: kode fungsi dengan bit teratas dinyalakan (3 + 128 = 131) dan kode pengecualian 2, alamat data tidak sah. Kode lain menyatakan bahwa fungsinya tidak didukung atau perangkatnya sibuk.",Exception:"Pengecualian",Means:"Artinya","No register there":"Tidak ada register di sana","registers 100–101":"register 100–101",EXCEPTION:"PENGECUALIAN","code 2: no such register":"kode 2: register itu tidak ada","No Security":"Tanpa keamanan","Anyone who can reach it":"Siapa pun yang bisa menjangkaunya","Nothing in these messages says who sent them: Modbus, from 1979, has no login and no encryption, so any device that can reach port 502 can read the values and start the pump. Plants protect it with separate networks, firewalls between office and plant, lists of who may talk to each PLC, and monitoring. Modbus/TCP Security wraps the same messages in TLS, on port 802.":"Tidak ada apa pun dalam pesan-pesan ini yang menyatakan siapa pengirimnya: Modbus, dari tahun 1979, tidak punya login maupun enkripsi, jadi perangkat apa pun yang bisa menjangkau port 502 bisa membaca nilai-nilainya dan menyalakan pompa. Pabrik melindunginya dengan jaringan terpisah, firewall antara kantor dan pabrik, daftar siapa yang boleh berbicara dengan setiap PLC, dan pemantauan. Modbus/TCP Security membungkus pesan yang sama dalam TLS, di port 802.","Separate networks, TLS":"Jaringan terpisah, TLS","NO LOGIN, NO ENCRYPTION":"TANPA LOGIN, TANPA ENKRIPSI","Seen on the plant network":"Terlihat di jaringan pabrik","Picked by the client; the answer carries the same number.":"Dipilih klien; jawaban membawa nomor yang sama.","Protocol ID":"ID protokol","The unit ID and everything after it.":"Unit ID dan semua yang mengikutinya.","Unit ID":"Unit ID","Which device. It matters when a gateway passes requests on to devices on a serial line.":"Perangkat mana. Penting saat gateway meneruskan permintaan ke perangkat di jalur serial.","Function code":"Kode fungsi","Starting address":"Alamat awal","Modbus counts from 0, though manuals often number the same register 40001 and up.":"Modbus menghitung dari 0, meski manual sering menomori register yang sama mulai 40001.",Quantity:"Jumlah","Modbus/TCP · Read Holding Registers, answer":"Modbus/TCP · Read Holding Registers, jawaban","The same number as the request.":"Nomor yang sama dengan permintaan.","Byte count":"Jumlah byte","Register 0":"Register 0","412 (tank level, 4.12 m)":"412 (ketinggian tangki, 4.12 m)","Plain 16-bit numbers. What each one means is written in the PLC’s documentation, not in the message.":"Angka 16 bit biasa. Arti masing-masing tertulis di dokumentasi PLC, bukan di pesan.","Register 1":"Register 1","183 (temperature, 18.3 °C)":"183 (suhu, 18.3 °C)","Register 2":"Register 2","1450 (pump speed, 1,450 rpm)":"1450 (kecepatan pompa, 1,450 rpm)","450 (level setpoint, 4.50 m)":"450 (setpoint ketinggian, 4.50 m)","Register address":"Alamat register","3 (level setpoint)":"3 (setpoint ketinggian)",Value:"Nilai","Modbus/TCP · Write Single Register, answer":"Modbus/TCP · Write Single Register, jawaban","The answer repeats the request: done.":"Jawaban mengulang permintaan: selesai.","Coil address":"Alamat coil","0 (pump 2)":"0 (pompa 2)","A coil is a single on/off output. 0xFF00 switches it on.":"Coil adalah keluaran nyala/mati tunggal. 0xFF00 menyalakannya.","Modbus/TCP · Write Single Coil, answer":"Modbus/TCP · Write Single Coil, jawaban","Modbus/TCP · exception":"Modbus/TCP · pengecualian","131 (3 + 128: an exception)":"131 (3 + 128: pengecualian)","The top bit set: the request failed.":"Bit teratas dinyalakan: permintaan gagal.","Exception code":"Kode pengecualian","There is no register at that address.":"Tidak ada register di alamat itu.","Internet Routes":"Rute internet",Routes:"Rute","The laptop’s packets":"Paket laptop","Border Gateway Protocol":"Border Gateway Protocol","The internet is a network of networks: tens of thousands of them, run by internet providers, clouds, universities and companies, each with its own AS number. BGP is how their border routers tell each other which addresses they can reach. Every router passes on what it learns with its own number added, so each network builds its own map of the paths to every address on the internet.":"Internet adalah jaringan dari jaringan-jaringan: puluhan ribu, dijalankan oleh penyedia internet, cloud, universitas, dan perusahaan, masing-masing dengan nomor AS sendiri. BGP adalah cara router perbatasan mereka saling memberi tahu alamat mana yang bisa mereka jangkau. Setiap router meneruskan apa yang ia pelajari dengan menambahkan nomornya sendiri, jadi setiap jaringan menyusun petanya sendiri tentang jalur ke setiap alamat di internet.",Between:"Antara","Networks (ASes)":"Jaringan (AS)",Table:"Tabel","About a million IPv4 routes":"Sekitar satu juta rute IPv4","Path choice":"Pemilihan jalur","Policy, then shortest":"Kebijakan, lalu yang terpendek","Route learned":"Rute dipelajari","Announced, passed on, used":"Diumumkan, diteruskan, dipakai","The hosting network announced its addresses, the transit network passed them on with its own number added, and the ISP’s router used that path for the laptop’s packets. When the route was withdrawn, the news spread the same way. There is no central map: every network builds its own from what its neighbours say. Press REPLAY to watch it again.":"Jaringan hosting mengumumkan alamatnya, jaringan transit meneruskannya dengan menambahkan nomornya sendiri, dan router ISP memakai jalur itu untuk paket laptop. Saat rute ditarik, kabar itu menyebar dengan cara yang sama. Tidak ada peta pusat: setiap jaringan menyusun petanya sendiri dari apa yang dikatakan tetangganya. Tekan ULANGI untuk menontonnya lagi.",Map:"Peta","Each network makes its own":"Setiap jaringan membuat sendiri","RPKI and filters":"RPKI dan filter","Many Networks":"Banyak jaringan","Each with its own number":"Masing-masing dengan nomornya","The internet is more than 75,000 separate networks, called autonomous systems (ASes): internet providers, clouds, universities, big companies, each with a number. Here are three: the laptop’s ISP (AS 64500), a transit network that carries others’ traffic (AS 64510), and the hosting network of www.example.com (AS 64511). BGP is how their routers tell each other where every address can be reached.":"Internet terdiri dari lebih dari 75,000 jaringan terpisah, yang disebut sistem otonom (AS): penyedia internet, cloud, universitas, perusahaan besar, masing-masing dengan sebuah nomor. Ini tiga di antaranya: ISP laptop (AS 64500), jaringan transit yang membawa lalu lintas pihak lain (AS 64510), dan jaringan hosting www.example.com (AS 64511). BGP adalah cara router mereka saling memberi tahu di mana setiap alamat bisa dijangkau.",Networks:"Jaringan","More than 75,000 ASes":"Lebih dari 75,000 AS",Here:"Di sini","3 ASes, a router each":"3 AS, masing-masing satu router",Numbers:"Nomor","TCP to port 179":"TCP ke port 179","BGP routers don’t discover each other: engineers at both ends set each other up as neighbours. The ISP’s router opens a TCP connection to the transit router on port 179. They are directly connected, so their packets go out with a TTL of 1: they can’t cross even one more router, so the session only works between direct neighbours.":"Router BGP tidak saling menemukan sendiri: para insinyur di kedua ujung menyetelnya sebagai tetangga. Router ISP membuka koneksi TCP ke router transit di port 179. Keduanya terhubung langsung, jadi paketnya keluar dengan TTL 1: paket itu tidak bisa melewati satu router lagi pun, sehingga sesi hanya berjalan antara tetangga langsung.",Neighbours:"Tetangga","Set up by hand":"Disetel manual","1: the next router only":"1: hanya router berikutnya","OPEN, then KEEPALIVE":"OPEN, lalu KEEPALIVE","Each router sends an OPEN: its AS number, a hold time of 180 seconds, its router ID and what it supports, such as 4-byte AS numbers. Each answers with a KEEPALIVE, and the session is established. From now on a KEEPALIVE goes every 60 seconds when there’s nothing else to send; after 180 silent seconds the session would be dropped.":"Setiap router mengirim OPEN: nomor AS-nya, hold time 180 detik, ID routernya, dan apa yang ia dukung, seperti nomor AS 4 byte. Masing-masing menjawab dengan KEEPALIVE, dan sesi pun terjalin. Mulai sekarang KEEPALIVE dikirim setiap 60 detik jika tidak ada lagi yang dikirim; setelah 180 detik senyap, sesi akan diputus.","AS, hold time, ID":"AS, hold time, ID","KEEPALIVE: established":"KEEPALIVE: terjalin","Hold time":"Hold time","hold 180 s":"hold 180 s","SESSION ESTABLISHED":"SESI TERJALIN","Announce a Route":"Mengumumkan rute","The hosting network: “I have these”":"Jaringan hosting: “saya punya ini”","The hosting network’s router announces 203.0.113.0/24, the 256 addresses that include www.example.com, to the transit network, which it pays to carry its traffic. The UPDATE says how to get there: AS_PATH 64511, only its own network so far, and NEXT_HOP, its own address on the link between them.":"Router jaringan hosting mengumumkan 203.0.113.0/24, 256 alamat yang mencakup www.example.com, ke jaringan transit, yang ia bayar untuk membawa lalu lintasnya. UPDATE itu menyatakan cara ke sana: AS_PATH 64511, sejauh ini hanya jaringannya sendiri, dan NEXT_HOP, alamatnya sendiri di tautan di antara keduanya.","path 64511":"jalur 64511","Passed On":"Diteruskan","Each network adds its number":"Setiap jaringan menambahkan nomornya","The transit router accepts the route and passes it to its other neighbours, the ISP among them, with its own number added to the front: AS_PATH 64510 64511, and itself as the next hop. The ISP’s router may hear of the same prefix from several neighbours. It picks one by its own policy first (routes through paying customers before others, say), then by the shortest AS path.":"Router transit menerima rute itu dan meneruskannya ke tetangganya yang lain, termasuk ISP, dengan nomornya sendiri ditambahkan di depan: AS_PATH 64510 64511, dan dirinya sendiri sebagai next hop. Router ISP mungkin mendengar prefiks yang sama dari beberapa tetangga. Ia memilih satu, pertama menurut kebijakannya sendiri (misalnya rute lewat pelanggan yang membayar lebih dulu daripada yang lain), lalu menurut AS_PATH terpendek.","Best path":"Jalur terbaik","path 64510 64511":"jalur 64510 64511","ROUTE TO 203.0.113.0/24":"RUTE KE 203.0.113.0/24","Follow the Route":"Mengikuti rute","Packets go where BGP said":"Paket pergi ke tempat yang dikatakan BGP","When the laptop connects to www.example.com (its address found by DNS as usual), its packets reach the ISP, whose router now sends anything for 203.0.113.0/24 to the transit router, and the transit router sends it on to the hosting network. The answer comes back by whatever route the hosting network chose towards the laptop’s ISP: on the internet the way back is often different from the way there.":"Saat laptop terhubung ke www.example.com (alamatnya ditemukan lewat DNS seperti biasa), paketnya tiba di ISP, yang routernya kini mengirim apa pun untuk 203.0.113.0/24 ke router transit, dan router transit meneruskannya ke jaringan hosting. Jawaban kembali lewat rute apa pun yang dipilih jaringan hosting menuju ISP laptop: di internet, jalan pulang sering berbeda dengan jalan pergi.","Way back":"Jalan pulang","Chosen separately":"Dipilih terpisah","the way back":"jalan pulang",Withdrawn:"Ditarik","Routes can be taken back":"Rute bisa ditarik kembali","Later the hosting network takes the prefix back, as it would if a link failed: an UPDATE listing it under withdrawn routes. The transit router passes it on, and within seconds to minutes networks everywhere forget the path. A session that goes quiet past its hold time loses all its routes at once. In 2021 Facebook withdrew the routes to its own DNS servers and vanished from the internet for six hours.":"Kemudian jaringan hosting menarik prefiks itu, seperti yang akan dilakukannya jika sebuah tautan putus: UPDATE yang mencantumkannya di bawah rute yang ditarik. Router transit meneruskannya, dan dalam hitungan detik hingga menit jaringan di mana-mana melupakan jalur itu. Sesi yang senyap melewati hold time-nya kehilangan semua rutenya sekaligus. Pada 2021 Facebook menarik rute ke server DNS-nya sendiri dan menghilang dari internet selama enam jam.","Spreads in":"Menyebar dalam","Seconds to minutes":"Detik hingga menit","Session lost":"Sesi terputus","All its routes go":"Semua rutenya hilang",WITHDRAW:"TARIK","Trust Problems":"Masalah kepercayaan","BGP believes its neighbours":"BGP memercayai tetangganya","A router accepts what its neighbours announce. A network that announces addresses that aren’t its own, by mistake or on purpose, pulls their traffic towards it: in 2008 a Pakistani ISP took YouTube offline worldwide this way. With RPKI the holder of a prefix signs which AS may announce it, and routers that check drop any other. Filters on what each neighbour may announce do the rest.":"Router menerima apa yang diumumkan tetangganya. Jaringan yang mengumumkan alamat yang bukan miliknya, karena keliru atau sengaja, menarik lalu lintas alamat itu ke dirinya: pada 2008 sebuah ISP Pakistan membuat YouTube tidak bisa diakses di seluruh dunia dengan cara ini. Dengan RPKI, pemegang prefiks menandatangani AS mana yang boleh mengumumkannya, dan router yang memeriksa membuang yang lain. Filter atas apa yang boleh diumumkan tiap tetangga mengerjakan sisanya.",Risk:"Risiko","Hijacks and leaks":"Pembajakan dan kebocoran","Signed: who may announce":"Ditandatangani: siapa yang boleh mengumumkan",Also:"Juga","Filters per neighbour":"Filter per tetangga","CHECK WHO MAY ANNOUNCE":"PERIKSA SIAPA YANG BOLEH MENGUMUMKAN","UPDATE Message: withdrawn 203.0.113.0/24":"UPDATE Message: ditarik 203.0.113.0/24",Marker:"Penanda","16 bytes of 0xFF":"16 byte 0xFF","All ones: where a message starts.":"Semua satu: tempat pesan dimulai.","The first message on a session: who this router is and what it supports.":"Pesan pertama dalam sesi: siapa router ini dan apa yang ia dukung.","This router’s network. (A 4-byte AS number goes in the capability below, with 23456 here.)":"Jaringan router ini. (Nomor AS 4 byte ada di kapabilitas di bawah, dengan 23456 di sini.)","If nothing at all arrives for this long, the session is dropped. Both sides use the lower offer.":"Jika sama sekali tidak ada yang tiba selama ini, sesi diputus. Kedua pihak memakai tawaran yang lebih rendah.","BGP identifier":"Pengenal BGP","The router’s ID, usually one of its addresses.":"ID router, biasanya salah satu alamatnya.","Optional parameters":"Parameter opsional","parameter 2, 14 bytes":"parameter 2, 14 byte","What this router can do beyond the basics.":"Apa yang bisa dilakukan router ini selain yang dasar.",Multiprotocol:"Multiprotokol","Which kinds of routes it will exchange on this session.":"Jenis rute apa yang akan dipertukarkan dalam sesi ini.","Route refresh":"Penyegaran rute","It can ask the other side to send all its routes again.":"Router ini bisa meminta pihak lain mengirim semua rutenya lagi.","4-byte AS numbers":"Nomor AS 4 byte","2-byte AS numbers ran short, so newer ones are 4 bytes long.":"Nomor AS 2 byte mulai habis, jadi nomor baru panjangnya 4 byte.","Only the header: “still here”. Sent when there’s nothing else to say, every third of the hold time.":"Hanya header: “masih di sini”. Dikirim saat tidak ada lagi yang dikatakan, setiap sepertiga hold time.","Routes: paths to new addresses, and ones taken back.":"Rute: jalur ke alamat baru, dan yang ditarik.","Withdrawn routes":"Rute yang ditarik","Path attributes":"Atribut jalur","0 (IGP: from inside the network that announced it)":"0 (IGP: dari dalam jaringan yang mengumumkannya)","Every network the route has passed through, the latest first. Other things being equal, the shorter path wins; a router that finds its own number here drops the route, so routes can’t loop.":"Setiap jaringan yang dilewati rute, yang terbaru lebih dulu. Jika hal lain setara, jalur yang lebih pendek menang; router yang menemukan nomornya sendiri di sini membuang rute itu, jadi rute tidak bisa berputar-putar.","Send packets for these addresses to this router.":"Kirim paket untuk alamat-alamat ini ke router ini.",Reachable:"Terjangkau","The addresses this route leads to: a prefix, here 256 addresses.":"Alamat yang dituju rute ini: sebuah prefiks, di sini 256 alamat.","BGP · UPDATE (withdrawal)":"BGP · UPDATE (penarikan)","These addresses can no longer be reached through this router.":"Alamat-alamat ini tidak lagi bisa dijangkau lewat router ini.","A Video Call":"Panggilan video",Signalling:"Pensinyalan","STUN and ICE":"STUN dan ICE",Media:"Media","STUN Server":"Server STUN","Sam’s Router":"Router Sam","Sam’s Laptop":"Laptop Sam","Web Real-Time Communication":"Komunikasi Real-Time Web","WebRTC lets two browsers call each other, with audio, video and data going straight between them, not through a server. A server only introduces them: they swap descriptions of what they can send and where they can be reached (signalling), find a way through both home routers with ICE and STUN, encrypt with DTLS, and send the media over UDP as SRTP.":"WebRTC memungkinkan dua browser saling menelepon, dengan audio, video, dan data yang langsung mengalir di antara keduanya, tidak lewat server. Server hanya memperkenalkan mereka: keduanya bertukar deskripsi tentang apa yang bisa dikirim dan di mana bisa dijangkau (pensinyalan), menemukan jalan menembus kedua router rumah dengan ICE dan STUN, mengenkripsi dengan DTLS, dan mengirim media lewat UDP sebagai SRTP.","Media over":"Media lewat","Always on":"Selalu aktif","Works in":"Berjalan di","Every major browser":"Semua browser utama","W3C; RFC 8825 and others":"W3C; RFC 8825 dan lainnya","On the call":"Dalam panggilan","Introduced by a server, then direct":"Diperkenalkan server, lalu langsung","The signalling server passed the offer and the answer between the two browsers, a STUN server told the laptop its public address, and an ICE check found a way through both home routers. After a DTLS handshake, encrypted audio and video went straight from one laptop to the other. Press REPLAY to watch it again.":"Server pensinyalan meneruskan offer dan answer antara kedua browser, server STUN memberi tahu laptop alamat publiknya, dan pemeriksaan ICE menemukan jalan menembus kedua router rumah. Setelah handshake DTLS, audio dan video terenkripsi langsung mengalir dari satu laptop ke laptop lain. Tekan ULANGI untuk menontonnya lagi.","Via call.example.com":"Lewat call.example.com","Media path":"Jalur media","Direct, through 2 NATs":"Langsung, menembus 2 NAT","DTLS, then SRTP":"DTLS, lalu SRTP","If blocked":"Jika diblokir","A TURN relay":"Relay TURN","Join the Call":"Bergabung ke panggilan","Through a signalling server":"Lewat server pensinyalan","The laptop opens a call page on call.example.com, and the page keeps a WebSocket open to the server, inside TLS. It joins room 42, where Sam is already waiting. The server will pass messages between the two browsers. WebRTC doesn’t say how: every app does this signalling its own way.":"Laptop membuka halaman panggilan di call.example.com, dan halaman itu menjaga WebSocket tetap terbuka ke server, di dalam TLS. Laptop bergabung ke ruang 42, tempat Sam sudah menunggu. Server akan meneruskan pesan antara kedua browser. WebRTC tidak menentukan caranya: setiap aplikasi menjalankan pensinyalan ini dengan caranya sendiri.","The app’s own server":"Server milik aplikasi sendiri","A WebSocket in TLS":"WebSocket di dalam TLS",Room:"Ruang","42, with Sam":"42, bersama Sam",JOIN:"GABUNG","room 42":"ruang 42","SAM IS HERE":"SAM ADA DI SINI","peer: Sam":"rekan: Sam","Public Address?":"Alamat publik?","Ask a STUN server":"Tanya server STUN","Behind its home router the laptop knows only its private address, 192.168.1.10, which nobody on the internet can reach. So it asks a STUN server named in the call page’s settings, with one small UDP request. The answer says where the request seemed to come from, 198.51.100.7 port 61022: the router’s public address and the port its NAT opened for this conversation.":"Di balik router rumahnya, laptop hanya tahu alamat privatnya, 192.168.1.10, yang tidak bisa dijangkau siapa pun di internet. Jadi laptop bertanya ke server STUN yang disebut di pengaturan halaman panggilan, dengan satu permintaan UDP kecil. Jawabannya menyatakan dari mana permintaan itu tampaknya datang, 198.51.100.7 port 61022: alamat publik router dan port yang dibuka NAT-nya untuk percakapan ini.",Public:"Publik","what is my address?":"apa alamat saya?","YOUR ADDRESS":"ALAMAT ANDA","The Offer":"Offer","An SDP description, via the server":"Deskripsi SDP, lewat server","The browser writes an offer in SDP: the media it wants to send (Opus audio; video in VP8, H.264 and others), the fingerprint of its DTLS certificate, its ICE user name and password, and its candidates, the addresses it might be reached at. Its private address is hidden behind a random .local name. The signalling server passes the offer on to Sam.":"Browser menulis offer dalam SDP: media yang ingin dikirim (audio Opus; video dalam VP8, H.264, dan lainnya), sidik jari sertifikat DTLS-nya, nama pengguna dan kata sandi ICE-nya, dan kandidatnya, alamat tempat ia mungkin bisa dijangkau. Alamat privatnya disembunyikan di balik nama .local acak. Server pensinyalan meneruskan offer itu ke Sam.","SDP, in a JSON message":"SDP, dalam pesan JSON",Candidates:"Kandidat",".local name, 198.51.100.7":"nama .local, 198.51.100.7","About 4.7 KB":"Sekitar 4.7 KB","SDP: audio, video":"SDP: audio, video",candidates:"kandidat","to Sam":"ke Sam","Sam’s browser replies":"Browser Sam membalas","Sam accepts the call. Sam’s browser answers with SDP of its own: the codecs it picked from the offer, its certificate fingerprint, its ICE user name and password, and its candidates, including its public address, 198.51.100.200 port 49170, which it learned from a STUN server the same way. It also says it will start the encryption handshake. Now each browser knows where the other might be reached.":"Sam menerima panggilan. Browser Sam menjawab dengan SDP-nya sendiri: codec yang dipilih dari offer, sidik jari sertifikatnya, nama pengguna dan kata sandi ICE-nya, dan kandidatnya, termasuk alamat publiknya, 198.51.100.200 port 49170, yang ia ketahui dari server STUN dengan cara yang sama. Browser itu juga menyatakan akan memulai handshake enkripsi. Kini setiap browser tahu di mana yang lain mungkin bisa dijangkau.",Codecs:"Codec","Sam’s address":"Alamat Sam","Starts DTLS":"Memulai DTLS","Sam’s browser":"Browser Sam","from Sam":"dari Sam","Punch Through":"Menembus","Checks straight to each other":"Pemeriksaan langsung satu sama lain","Now the browsers try pairs of addresses with STUN checks sent straight to each other (ICE). Each check also opens a way back through the sender’s own router, so once both sides have sent one, checks get through both NATs. This one is answered: the direct path works. The laptop then repeats the check with USE-CANDIDATE, choosing this pair for the call.":"Kini browser mencoba pasangan alamat dengan pemeriksaan STUN yang dikirim langsung satu sama lain (ICE). Setiap pemeriksaan juga membuka jalan pulang menembus router pengirimnya sendiri, jadi begitu kedua pihak sudah mengirim satu, pemeriksaan bisa menembus kedua NAT. Pemeriksaan ini dijawab: jalur langsung berfungsi. Laptop lalu mengulang pemeriksaan dengan USE-CANDIDATE, memilih pasangan ini untuk panggilan.",Checks:"Pemeriksaan","STUN, peer to peer":"STUN, antarpeer","The ICE password":"Kata sandi ICE","A direct path":"Jalur langsung",CHECK:"PERIKSA","IT WORKS":"BERHASIL","direct path":"jalur langsung","THROUGH BOTH ROUTERS":"MENEMBUS KEDUA ROUTER","DTLS Handshake":"Handshake DTLS","Keys for the media":"Kunci untuk media","Over the same path the browsers run a DTLS handshake: TLS for UDP. Their certificates are self-signed, so each checks the other’s against the fingerprint in the SDP, which came through the signalling server inside TLS. The handshake also agrees the keys for SRTP, which encrypts the audio and video. WebRTC never sends media unencrypted.":"Lewat jalur yang sama, browser menjalankan handshake DTLS: TLS untuk UDP. Sertifikat mereka ditandatangani sendiri, jadi masing-masing memeriksa sertifikat pihak lain dengan sidik jari di SDP, yang datang lewat server pensinyalan di dalam TLS. Handshake ini juga menyepakati kunci untuk SRTP, yang mengenkripsi audio dan video. WebRTC tidak pernah mengirim media tanpa enkripsi.","1.2, TLS over UDP":"1.2, TLS lewat UDP","Checked by fingerprint":"Diperiksa dengan sidik jari",Gives:"Menghasilkan","The SRTP keys":"Kunci SRTP",certificate:"sertifikat","Media Flows":"Media mengalir","Audio and video, direct":"Audio dan video, langsung","Audio goes in an SRTP packet every 20 ms, and video as frames split over several packets. Each packet has a readable RTP header (sequence number, timestamp, stream ID) and encrypted media. None of it passes through call.example.com. Both browsers watch delay and loss and adjust the video quality to suit, and a data channel for chat or files can share the same path.":"Audio dikirim dalam satu paket SRTP setiap 20 ms, dan video sebagai frame yang dipecah ke beberapa paket. Setiap paket punya header RTP yang bisa dibaca (nomor urut, stempel waktu, ID stream) dan media terenkripsi. Tidak ada yang lewat call.example.com. Kedua browser memantau jeda dan paket yang hilang lalu menyesuaikan kualitas video, dan kanal data untuk chat atau file bisa berbagi jalur yang sama.","Opus, a packet per 20 ms":"Opus, satu paket per 20 ms",Video:"Video","VP8, adapts to the network":"VP8, menyesuaikan dengan jaringan","None of it":"Tidak ada",AUDIO:"AUDIO","Opus, every 20 ms":"Opus, setiap 20 ms",VIDEO:"VIDEO","VP8, a frame in 3 packets":"VP8, satu frame dalam 3 paket","Peer to Peer":"Peer to peer","And when it can’t be":"Dan saat tidak bisa","The server helped the two browsers find each other, then stepped aside: the call goes straight between the two homes. When a network won’t let direct packets through (some company firewalls, some mobile networks), ICE falls back to a TURN server that relays the encrypted media without being able to read it. Group calls usually send media through a server too, called an SFU.":"Server membantu kedua browser saling menemukan, lalu menyingkir: panggilan berjalan langsung antara kedua rumah. Saat jaringan tidak meloloskan paket langsung (sebagian firewall kantor, sebagian jaringan seluler), ICE beralih ke server TURN yang meneruskan media terenkripsi tanpa bisa membacanya. Panggilan grup biasanya juga mengirim media lewat server, yang disebut SFU.","Laptop to laptop":"Laptop ke laptop",Fallback:"Cadangan","TURN relay (encrypted)":"Relay TURN (terenkripsi)","Group calls":"Panggilan grup","Usually via an SFU":"Biasanya lewat SFU","NO SERVER IN THE MIDDLE":"TANPA SERVER DI TENGAH","A WebSocket text message":"Pesan teks WebSocket","The attributes; the 20-byte header isn’t counted.":"Atribut; header 20 byte tidak dihitung.","Always this value: tells STUN apart from the other traffic on the same port.":"Selalu nilai ini: membedakan STUN dari lalu lintas lain di port yang sama.","Random; the response carries the same ID.":"Acak; respons membawa ID yang sama.","Where the request came from, as the server saw it: the home router’s public address, and the port its NAT picked for this conversation.":"Asal permintaan, seperti yang dilihat server: alamat publik router rumah, dan port yang dipilih NAT-nya untuk percakapan ini.","Their internet provider’s router, the next hop.":"Router penyedia internet Sam, hop berikutnya.","Their router’s internet-facing port.":"Port router Sam yang menghadap internet.","The ICE user names from the offer and the answer, the other side’s first: proves the check belongs to this call.":"Nama pengguna ICE dari offer dan answer, milik pihak lain lebih dulu: membuktikan pemeriksaan ini milik panggilan ini.","The priority a new candidate found by this check would get.":"Prioritas yang akan didapat kandidat baru yang ditemukan oleh pemeriksaan ini.","This side, the caller, makes the final choice of path. The random number settles a tie.":"Pihak ini, si penelepon, membuat pilihan akhir jalur. Angka acak memutus hasil seri.","HMAC-SHA1 of the message, keyed with an ICE password swapped through the signalling server, so a stranger can’t fake a check or its answer.":"HMAC-SHA1 dari pesan, dengan kunci kata sandi ICE yang dipertukarkan lewat server pensinyalan, sehingga orang asing tidak bisa memalsukan pemeriksaan atau jawabannya.","A CRC-32 of the message: marks it clearly as STUN.":"CRC-32 dari pesan: menandainya dengan jelas sebagai STUN.","Where the check came from, as the other laptop saw it: the home router’s public address and port.":"Asal pemeriksaan, seperti yang dilihat laptop lain: alamat publik dan port router rumah.",Epoch:"Epoch","Counts this side’s records, so repeats and stale ones can be spotted.":"Menghitung record pihak ini, sehingga yang berulang dan yang usang bisa dikenali.","Message length":"Panjang pesan","Message sequence":"Urutan pesan","Handshake messages are numbered, so they can be put back in order.":"Pesan handshake diberi nomor, sehingga bisa disusun kembali sesuai urutan.",Fragment:"Fragmen","Cipher suites: ECDHE-ECDSA with AES-GCM, and others":"Cipher suite: ECDHE-ECDSA dengan AES-GCM, dan lainnya","use_srtp: the SRTP protection it supports":"use_srtp: proteksi SRTP yang didukungnya","Chosen: ECDHE-ECDSA-AES128-GCM-SHA256":"Dipilih: ECDHE-ECDSA-AES128-GCM-SHA256","A self-signed certificate the browser made; its fingerprint was in the offer":"Sertifikat yang ditandatangani sendiri buatan browser; sidik jarinya ada di offer","Its half of an X25519 key exchange, signed":"Separuh miliknya dari pertukaran kunci X25519, ditandatangani","Asks Sam’s browser for its certificate too":"Meminta sertifikat dari browser Sam juga","Sam’s self-signed certificate; its fingerprint was in the answer":"Sertifikat Sam yang ditandatangani sendiri; sidik jarinya ada di answer","Its half of the X25519 key exchange":"Separuh miliknya dari pertukaran kunci X25519","A signature that proves it holds the certificate’s key":"Tanda tangan yang membuktikan ia memegang kunci sertifikat","From the next record on, this side encrypts.":"Mulai record berikutnya, pihak ini mengenkripsi.","Finished (encrypted)":"Finished (terenkripsi)","Epoch 1: protected with the keys just agreed.":"Epoch 1: dilindungi dengan kunci yang baru disepakati.","An 8-byte nonce, the Finished message and a 16-byte tag (AES-128-GCM).":"Nonce 8 byte, pesan Finished, dan tag 16 byte (AES-128-GCM).","SRTP · audio":"SRTP · audio","2, no padding, extension, no CSRCs":"2, tanpa padding, ada ekstensi, tanpa CSRC","X set: a header extension follows the fixed header.":"X aktif: ekstensi header menyusul header tetap.","One more for each packet, so a lost or late one shows.":"Bertambah satu untuk tiap paket, sehingga paket yang hilang atau terlambat ketahuan.","Audio clock, 48,000 ticks a second: +960 per 20 ms.":"Clock audio, 48,000 tick per detik: +960 per 20 ms.","Which stream this is; announced in the SDP.":"Stream mana ini; diumumkan di SDP.","Header extension":"Ekstensi header","0xbede, 2 words":"0xbede, 2 word","One-byte elements: an ID (from the SDP’s a=extmap lines) and a length.":"Elemen satu byte: ID (dari baris a=extmap di SDP) dan panjang.","Audio level":"Level audio","How loud this packet is, so a group call can show who is talking without decrypting.":"Seberapa keras paket ini, sehingga panggilan grup bisa menunjukkan siapa yang berbicara tanpa mendekripsi.","Transport sequence":"Urutan transport","Numbers every packet of the call; the receiver reports what arrived when, for congestion control.":"Memberi nomor setiap paket dalam panggilan; penerima melaporkan apa yang tiba dan kapan, untuk kendali kemacetan.","Encrypted media":"Media terenkripsi","20 ms of Opus audio, encrypted with keys from the DTLS handshake (AES-128-GCM).":"20 ms audio Opus, dienkripsi dengan kunci dari handshake DTLS (AES-128-GCM).","Authentication tag":"Tag autentikasi","Proves the packet came from the other side unchanged; the header is covered too.":"Membuktikan paket datang dari pihak lain tanpa diubah; header juga tercakup.","SRTP · video":"SRTP · video","Video clock, 90,000 ticks a second: +3,000 per frame at 30 frames a second.":"Clock video, 90,000 tick per detik: +3,000 per frame pada 30 frame per detik.","Absolute send time":"Waktu kirim absolut","When the packet was sent, so the receiver can tell when the network is filling up.":"Kapan paket dikirim, sehingga penerima bisa tahu kapan jaringan mulai penuh.","1 byte":"1 byte","Part of a VP8 video frame, encrypted with keys from the DTLS handshake (AES-128-GCM).":"Bagian dari frame video VP8, dienkripsi dengan kunci dari handshake DTLS (AES-128-GCM).","Marker set: the last packet of a video frame.":"Marker aktif: paket terakhir dari frame video.","8 ports":"8 port","Frames and switches":"Frame dan switch","Broadband logins":"Login broadband","The laptop sent it with 128; the router took 1 when it passed it on.":"Laptop mengirimnya dengan 128; router menguranginya 1 saat meneruskannya.","Frames & Switches":"Frame dan switch","To the NAS":"Ke NAS","To the internet":"Ke internet","Ethernet and Switches":"Ethernet dan switch","Ethernet carries almost every wired network, and Wi-Fi access points pass their traffic on to it. Every network card has a 48-bit MAC address. A frame says which card it is for and which card sent it, and a switch delivers it: it learns which port each address is behind from the frames it sees, and sends each frame only where it needs to go.":"Ethernet membawa hampir semua jaringan berkabel, dan titik akses Wi-Fi meneruskan lalu lintasnya ke sana. Setiap kartu jaringan punya alamat MAC 48-bit. Sebuah frame menyebut untuk kartu mana ia ditujukan dan kartu mana yang mengirimnya, lalu switch mengantarkannya: ia mempelajari di balik port mana setiap alamat berada dari frame yang dilihatnya, dan mengirim setiap frame hanya ke tempat yang perlu.","48-bit MAC":"MAC 48-bit","14 bytes, plus a 4-byte FCS":"14 byte, ditambah FCS 4 byte","Frame size":"Ukuran frame","64 to 1,518 bytes":"64 hingga 1.518 byte",Speeds:"Kecepatan",Switched:"Tersalurkan","Learned, flooded, forwarded":"Belajar, membanjiri, meneruskan","The switch learned where the laptop and the NAS were from the frames they sent, flooded only the broadcast, and sent every other frame out of just the port it needed. MAC addresses carried each frame across one link; at the router the packet moved into a new frame. Press REPLAY to watch it again.":"Switch mempelajari letak laptop dan NAS dari frame yang mereka kirim, hanya membanjiri broadcast, dan mengirim setiap frame lain hanya lewat port yang diperlukan. Alamat MAC membawa setiap frame melintasi satu tautan; di router, paket pindah ke frame baru. Tekan ULANGI untuk menontonnya lagi.",Learned:"Dipelajari","2 addresses, 2 ports":"2 alamat, 2 port",Flooded:"Dibanjiri","Only the broadcast":"Hanya broadcast",Frame:"Frame","14-byte header, 4-byte FCS":"Header 14 byte, FCS 4 byte","Forgets after":"Lupa setelah","5 minutes unused":"5 menit tak dipakai","Who Has the NAS?":"NAS di Mana?","A broadcast asks for a MAC address":"Broadcast menanyakan alamat MAC","The laptop wants to reach the NAS at 192.168.1.20. On a local network, frames are delivered by MAC address, and the laptop doesn’t know the NAS’s yet. So it sends an ARP request to ff:ff:ff:ff:ff:ff, the broadcast address, into port 1 of the switch.":"Laptop ingin menjangkau NAS di 192.168.1.20. Di jaringan lokal, frame diantar berdasarkan alamat MAC, dan laptop belum tahu MAC milik NAS. Jadi ia mengirim permintaan ARP ke ff:ff:ff:ff:ff:ff, alamat broadcast, masuk ke port 1 switch.","Looking for":"Mencari","ff:ff:ff:ff:ff:ff (all)":"ff:ff:ff:ff:ff:ff (semua)",Into:"Masuk ke","Switch port 1":"Port 1 switch","who has 192.168.1.20?":"siapa punya 192.168.1.20?","Learn, Then Flood":"Belajar, Lalu Banjiri","The switch notes where the laptop is":"Switch mencatat letak laptop","A switch reads each frame’s source address and notes it in its MAC table: 00:00:5e:00:53:10 is on port 1. A broadcast is for everyone, so it sends a copy out of every other port: to the NAS on port 2 and the router on port 8. Frames for unknown addresses are flooded too.":"Switch membaca alamat sumber setiap frame dan mencatatnya di tabel MAC-nya: 00:00:5e:00:53:10 ada di port 1. Broadcast ditujukan untuk semua, jadi ia mengirim salinan lewat setiap port lain: ke NAS di port 2 dan ke router di port 8. Frame untuk alamat yang belum dikenal juga dibanjiri.","…:53:10 is on port 1":"…:53:10 ada di port 1",Copies:"Salinan","Out of every other port":"Lewat setiap port lain","Unknown address":"Alamat tak dikenal","Flooded the same way":"Dibanjiri juga","…:53:10 IS ON PORT 1":"…:53:10 DI PORT 1","copies out of ports 2 and 8":"salinan lewat port 2 dan 8","Only the NAS Answers":"Hanya NAS yang Menjawab","The reply goes to one port":"Balasan menuju satu port","Every device reads the request, but only the NAS has 192.168.1.20, so only it answers, straight to the laptop’s MAC; the router ignores it. The switch learns that 00:00:5e:00:53:20 is on port 2. It already knows where the laptop is, so the reply leaves by port 1 alone.":"Setiap perangkat membaca permintaan itu, tetapi hanya NAS yang punya 192.168.1.20, jadi hanya ia yang menjawab, langsung ke MAC laptop; router mengabaikannya. Switch mempelajari bahwa 00:00:5e:00:53:20 ada di port 2. Ia sudah tahu letak laptop, jadi balasan keluar hanya lewat port 1.","To the laptop only":"Hanya ke laptop","…:53:20 is on port 2":"…:53:20 ada di port 2","Out of":"Keluar lewat","Port 1":"Port 1","…:53:20 IS ON PORT 2":"…:53:20 DI PORT 2","port 1 only":"hanya port 1","Port to Port":"Port ke Port","Frames go only where they must":"Frame hanya pergi ke tujuannya","The laptop connects to the NAS. Each frame starts with the NAS’s MAC, then its own, then a type: 0x0800, an IPv4 packet. After the packet, the card adds a 4-byte checksum. The switch looks up the destination and sends each frame out of port 2 only. The router never sees them.":"Laptop terhubung ke NAS. Setiap frame diawali MAC NAS, lalu MAC-nya sendiri, lalu sebuah tipe: 0x0800, paket IPv4. Setelah paket, kartu menambahkan checksum 4 byte. Switch mencari tujuan dan mengirim setiap frame hanya lewat port 2. Router tidak pernah melihatnya.","To, from, type: 14 bytes":"Ke, dari, tipe: 14 byte","4 bytes, added by the card":"4 byte, ditambah kartu","Router sees":"Router melihat",Nothing:"Tidak ada","type 0x0800 (IPv4)":"tipe 0x0800 (IPv4)","out of port 2 only":"hanya lewat port 2","Off the Network":"Keluar dari Jaringan","A frame for the router":"Frame untuk router","Next the laptop opens a website at 203.0.113.10. That address isn’t on the local network, so the frame goes to the router: the router’s MAC, known from an earlier ARP, is the destination, while the packet inside still names 203.0.113.10. The switch sends it out of port 8.":"Berikutnya laptop membuka situs web di 203.0.113.10. Alamat itu tidak ada di jaringan lokal, jadi frame pergi ke router: MAC router, yang diketahui dari ARP sebelumnya, menjadi tujuan, sementara paket di dalamnya tetap menyebut 203.0.113.10. Switch mengirimnya lewat port 8.","Frame to":"Frame ke","The router’s MAC":"MAC router","Packet to":"Paket ke","Port 8":"Port 8","IP packet to 203.0.113.10":"paket IP ke 203.0.113.10","out of port 8":"lewat port 8","A New Frame":"Frame Baru","Every hop rewraps the packet":"Setiap hop membungkus ulang paket","The router takes the packet out of the frame, lowers its TTL and swaps in its public address (NAT). Then it puts the packet in a new frame for its next link: its internet-side MAC as the source, the provider’s router as the destination. MAC addresses only ever cross one link.":"Router mengeluarkan paket dari frame, menurunkan TTL-nya, dan memasang alamat publiknya (NAT). Lalu ia memasukkan paket ke frame baru untuk tautan berikutnya: MAC sisi internetnya sebagai sumber, router penyedia sebagai tujuan. Alamat MAC tidak pernah melintasi lebih dari satu tautan.","The router’s internet port":"Port internet router","The provider’s router":"Router penyedia","Still 203.0.113.10":"Tetap 203.0.113.10","NEW FRAME":"FRAME BARU","from the router’s internet port":"dari port internet router","IP still to 203.0.113.10":"IP tetap ke 203.0.113.10","In port 1 · Who has 192.168.1.20? Tell 192.168.1.10":"Masuk, port 1 · Who has 192.168.1.20? Tell 192.168.1.10","Out port 2 (flooded) · Who has 192.168.1.20?":"Keluar, port 2 (dibanjiri) · Who has 192.168.1.20?","Out port 8 (flooded) · Who has 192.168.1.20?":"Keluar, port 8 (dibanjiri) · Who has 192.168.1.20?","In port 2 · 192.168.1.20 is at 00:00:5e:00:53:20":"Masuk, port 2 · 192.168.1.20 is at 00:00:5e:00:53:20","Out port 1 only · 192.168.1.20 is at 00:00:5e:00:53:20":"Keluar hanya port 1 · 192.168.1.20 is at 00:00:5e:00:53:20","In port 1 · 50532 → 445 [SYN]":"Masuk, port 1 · 50532 → 445 [SYN]","Out port 2 · 50532 → 445 [SYN]":"Keluar, port 2 · 50532 → 445 [SYN]","In port 2 · 445 → 50532 [SYN, ACK]":"Masuk, port 2 · 445 → 50532 [SYN, ACK]","Out port 1 · 445 → 50532 [SYN, ACK]":"Keluar, port 1 · 445 → 50532 [SYN, ACK]","In port 1 · 52344 → 443 [SYN] (frame to the router)":"Masuk, port 1 · 52344 → 443 [SYN] (frame ke router)","Out port 8 · 52344 → 443 [SYN]":"Keluar, port 8 · 52344 → 443 [SYN]","TTL 127 · 40112 → 443 [SYN] (new frame, after NAT)":"TTL 127 · 40112 → 443 [SYN] (frame baru, setelah NAT)","Seen going into the switch, port 1":"Terlihat masuk ke switch, port 1","Seen leaving the switch, port 2":"Terlihat keluar dari switch, port 2","Seen leaving the switch, port 8":"Terlihat keluar dari switch, port 8","Seen going into the switch, port 2":"Terlihat masuk ke switch, port 2","Seen leaving the switch, port 1":"Terlihat keluar dari switch, port 1","Broadband Logins":"Login Broadband",Discovery:"Penemuan","PPP setup":"Penyiapan PPP","Home Router":"Router Rumah","Access Server":"Server Akses","Point-to-Point Protocol over Ethernet":"Point-to-Point Protocol melalui Ethernet","Many DSL and fibre providers make the home router log in before it gets online. PPPoE is how: the router finds the provider’s access server and opens a session with it, then runs PPP inside, agreeing on the link’s settings, logging in with the username and password from the provider and receiving its public IP address. Every packet then carries an 8-byte PPPoE header.":"Banyak penyedia DSL dan fiber mewajibkan router rumah login sebelum bisa online. PPPoE adalah caranya: router menemukan server akses penyedia dan membuka sesi dengannya, lalu menjalankan PPP di dalamnya, menyepakati pengaturan tautan, login dengan nama pengguna dan kata sandi dari penyedia, dan menerima alamat IP publiknya. Setelah itu setiap paket membawa header PPPoE 8 byte.","CHAP or PAP":"CHAP atau PAP","From IPCP":"Dari IPCP","8 bytes (MTU 1,492)":"8 byte (MTU 1.492)","Logged in":"Sudah login","Found, agreed, checked, addressed":"Ditemukan, disepakati, dicek, diberi alamat","The router found the provider’s access server, got a session, agreed on the link’s settings, proved its password without sending it and was given its public address. Every packet now travels inside that session, until a PADT ends it. Press REPLAY to watch it again.":"Router menemukan server akses penyedia, mendapat sesi, menyepakati pengaturan tautan, membuktikan kata sandinya tanpa mengirimnya, dan diberi alamat publiknya. Kini setiap paket berjalan di dalam sesi itu, sampai sebuah PADT mengakhirinya. Tekan ULANGI untuk menontonnya lagi.","17 to get online":"17 untuk online","Public IP":"IP publik","8 bytes per packet":"8 byte per paket","Anyone There?":"Ada Orang?","The router looks for an access server":"Router mencari server akses","The home router is plugged into the provider’s fibre or DSL line. Before it can log in, it has to find the provider’s access server, so it broadcasts a PADI: “PPPoE Active Discovery Initiation”. An access server answers with a PADO, an offer that names it: bng-1.example.net.":"Router rumah tersambung ke jalur fiber atau DSL penyedia. Sebelum bisa login, ia harus menemukan server akses penyedia, jadi ia menyiarkan PADI: “PPPoE Active Discovery Initiation”. Sebuah server akses menjawab dengan PADO, penawaran yang menyebut namanya: bng-1.example.net.","PADI, to everyone":"PADI, ke semua","PADO, from the server":"PADO, dari server","Ethernet type":"Tipe Ethernet","0x8863 (discovery)":"0x8863 (penemuan)","is there an access server?":"ada server akses?","and a cookie":"dan sebuah cookie","Pick a Server":"Pilih Server","A session number for the line":"Nomor sesi untuk jalur","If several servers answered, the router picks one and asks it directly with a PADR, sending back the cookie it was given. The server replies with a PADS carrying a session ID, 0x2f1c. From now on every frame between the two of them carries that number.":"Jika beberapa server menjawab, router memilih satu dan memintanya langsung dengan PADR, sambil mengembalikan cookie yang diterimanya. Server membalas dengan PADS yang membawa ID sesi, 0x2f1c. Mulai sekarang setiap frame di antara keduanya membawa nomor itu.",Confirmed:"Dikonfirmasi","this server, please":"server ini, ya","with its cookie":"beserta cookie-nya","session ID 0x2f1c":"ID sesi 0x2f1c","SESSION 0x2F1C":"SESI 0x2F1C","Link Settings":"Pengaturan Tautan","LCP agrees on size and login":"LCP menyepakati ukuran dan login","Now PPP runs inside the session, starting with LCP. Each side asks for its settings: packets of at most 1,492 bytes, since PPPoE’s 8 bytes have to fit in Ethernet’s 1,500, and a random magic number to spot loops. The server also asks for a CHAP login. Both agree.":"Kini PPP berjalan di dalam sesi, dimulai dengan LCP. Tiap sisi meminta pengaturannya: paket paling besar 1.492 byte, karena 8 byte PPPoE harus muat di 1.500 milik Ethernet, dan magic number acak untuk mendeteksi loop. Server juga meminta login CHAP. Keduanya setuju.","Largest packet":"Paket terbesar","1,492 bytes (MRU)":"1.492 byte (MRU)","CHAP with MD5":"CHAP dengan MD5","0x8864 (session)":"0x8864 (sesi)","LCP REQUEST":"PERMINTAAN LCP","magic number":"magic number","MRU 1492, log in with CHAP":"MRU 1492, login dengan CHAP","LCP ACK":"LCP ACK","A password check without the password":"Cek kata sandi tanpa kata sandi","The server sends a random challenge. The router answers with its username, alex@fibre.example, and an MD5 hash of the challenge and its password, so the password itself never crosses the line. The server checks the answer with the provider’s RADIUS server, then says Success.":"Server mengirim tantangan acak. Router menjawab dengan nama penggunanya, alex@fibre.example, dan hash MD5 dari tantangan dan kata sandinya, sehingga kata sandi itu sendiri tidak pernah melintasi jalur. Server memeriksa jawaban itu ke server RADIUS penyedia, lalu menjawab Success.",Username:"Nama pengguna","A hash, not the password":"Hash, bukan kata sandi","The provider’s RADIUS":"RADIUS penyedia","MD5(id, password, challenge)":"MD5(id, kata sandi, tantangan)","CHECKED WITH RADIUS":"DICEK DENGAN RADIUS","Get an Address":"Dapatkan Alamat","IPCP hands out the public IP":"IPCP membagikan IP publik","The server first tells the router its own end, 198.51.100.1. The router asks for an address and DNS servers, offering 0.0.0.0: “anything”. The server says no and suggests 198.51.100.7 and two DNS servers. The router asks again with those, and the server agrees.":"Server lebih dulu memberi tahu router ujungnya sendiri, 198.51.100.1. Router meminta alamat dan server DNS, dengan menawarkan 0.0.0.0: “apa saja”. Server menolak dan menyarankan 198.51.100.7 serta dua server DNS. Router meminta lagi dengan nilai itu, dan server setuju.","Other end":"Ujung lain","IPCP REQUEST":"PERMINTAAN IPCP","my end: 198.51.100.1":"ujungku: 198.51.100.1","address? 0.0.0.0":"alamat? 0.0.0.0","IPCP ACK":"IPCP ACK","IPCP NAK":"IPCP NAK","use 198.51.100.7":"pakai 198.51.100.7","198.51.100.7, please":"198.51.100.7, ya",agreed:"setuju","Every packet in an 8-byte wrapper":"Setiap paket dalam bungkus 8 byte","The laptop opens a website. The router swaps in its public address (NAT) and sends the packet inside the session: a 6-byte PPPoE header, then 2 bytes saying “IPv4”. It also lowers the MSS the laptop offered from 1460 to 1452, so the replies fit in 1,492 bytes.":"Laptop membuka situs web. Router memasang alamat publiknya (NAT) dan mengirim paket di dalam sesi: header PPPoE 6 byte, lalu 2 byte yang menyatakan “IPv4”. Ia juga menurunkan MSS yang ditawarkan laptop dari 1460 menjadi 1452, agar balasan muat dalam 1.492 byte.",Wrapper:"Pembungkus","6 + 2 bytes":"6 + 2 byte","1460 → 1452 (clamped)":"1460 → 1452 (dibatasi)","in session 0x2f1c":"dalam sesi 0x2f1c","MSS now 1452":"MSS kini 1452","Seen on the router’s line to the provider":"Terlihat di jalur router ke penyedia","PPPoE PADI · 18 bytes":"PPPoE PADI · 18 byte","PADI, 2 tags":"PADI, 2 tag","Broadcast: everything on the line receives it.":"Broadcast: semua yang ada di jalur menerimanya.","0x8863 (PPPoE discovery)":"0x8863 (penemuan PPPoE)","Version, type":"Versi, tipe","Active Discovery Initiation: is there an access server out there?":"Active Discovery Initiation: adakah server akses di luar sana?","0 (none yet)":"0 (belum ada)","What follows this header.":"Yang mengikuti header ini.","The service the router wants; empty means any.":"Layanan yang diinginkan router; kosong berarti apa saja.","Type, length":"Tipe, panjang","A value the router made up. Answers carry it back, so the router can match them to its request.":"Nilai buatan router sendiri. Jawaban membawanya kembali, sehingga router bisa mencocokkannya dengan permintaannya.","PPPoE PADO · 59 bytes":"PPPoE PADO · 59 byte","PADO, 4 tags":"PADO, 4 tag","The access server’s port.":"Port server akses.","Active Discovery Offer: an access server answers.":"Active Discovery Offer: sebuah server akses menjawab.","The access server’s name.":"Nama server akses.","A value the server will recognise when the router asks for it again, so floods of fake requests cost it nothing.":"Nilai yang akan dikenali server saat router memintanya lagi, sehingga banjir permintaan palsu tidak membebaninya.","PPPoE PADR · 38 bytes":"PPPoE PADR · 38 byte","PADR, 3 tags":"PADR, 3 tag","The access server that answered.":"Server akses yang menjawab.","Active Discovery Request: the router picks this server.":"Active Discovery Request: router memilih server ini.","PPPoE PADS · 18 bytes":"PPPoE PADS · 18 byte","PADS, 2 tags":"PADS, 2 tag","Active Discovery Session-confirmation: here is the session ID.":"Active Discovery Session-confirmation: inilah ID sesinya.","Given by the server in its PADS; every frame of the session carries it.":"Diberikan server dalam PADS-nya; setiap frame sesi membawanya.","PPPoE · 6 bytes":"PPPoE · 6 byte","PPP LCP Configure-Request · 16 bytes":"PPP LCP Configure-Request · 16 byte","0x8864 (PPPoE session)":"0x8864 (sesi PPPoE)","0x00 (Session)":"0x00 (sesi)","Session data: one PPP packet.":"Data sesi: satu paket PPP.","Link Control Protocol: the link’s settings.":"Link Control Protocol: pengaturan tautan.","The settings this side wants.":"Pengaturan yang diinginkan sisi ini.","The answer carries the same number.":"Jawabannya membawa nomor yang sama.","The largest packet this side will take: 1,500 bytes of Ethernet minus PPPoE’s 8.":"Paket terbesar yang diterima sisi ini: 1.500 byte Ethernet dikurangi 8 milik PPPoE.","Random. Seeing its own number come back would mean the line loops back on itself.":"Acak. Melihat nomornya sendiri kembali berarti jalur memutar balik ke dirinya sendiri.","PPP LCP Configure-Request · 21 bytes":"PPP LCP Configure-Request · 21 byte","How the server wants the router to log in.":"Cara server ingin router login.","PPP LCP Configure-Ack · 16 bytes":"PPP LCP Configure-Ack · 16 byte","Every setting accepted, exactly as asked.":"Semua pengaturan diterima, persis seperti yang diminta.","The number of the request this answers.":"Nomor permintaan yang dijawab ini.","PPP LCP Configure-Ack · 21 bytes":"PPP LCP Configure-Ack · 21 byte","PPP CHAP Challenge · 40 bytes":"PPP CHAP Challenge · 40 byte","Challenge Handshake Authentication Protocol: the login.":"Challenge Handshake Authentication Protocol: proses login.","A random value for the router to prove its password with.":"Nilai acak untuk dipakai router membuktikan kata sandinya.","The response must carry the same number.":"Jawabannya harus membawa nomor yang sama.","Value size":"Ukuran nilai","Random, new for every login.":"Acak, baru di setiap login.","The server’s name.":"Nama server.","PPP CHAP Response · 41 bytes":"PPP CHAP Response · 41 byte","The proof, and who is logging in.":"Buktinya, dan siapa yang login.","The number of the challenge this answers.":"Nomor tantangan yang dijawab ini.","MD5 of the identifier, the password and the challenge: it proves the password without sending it.":"MD5 dari pengenal, kata sandi, dan tantangan: membuktikan kata sandi tanpa mengirimnya.","The username the provider gave.":"Nama pengguna dari penyedia.","PPP CHAP Success · 13 bytes":"PPP CHAP Success · 13 byte","The login worked.":"Login berhasil.","Text for people to read; any words will do.":"Teks untuk dibaca orang; kata apa pun boleh.","PPP IPCP Configure-Request · 12 bytes":"PPP IPCP Configure-Request · 12 byte","IP Control Protocol: the IP address and DNS servers.":"IP Control Protocol: alamat IP dan server DNS.","The address of the server’s end of the link.":"Alamat ujung tautan di sisi server.","PPP IPCP Configure-Request · 24 bytes":"PPP IPCP Configure-Request · 24 byte","Zero: “please give me an address”.":"Nol: “tolong beri saya alamat”.","Zero: “which DNS server should I use?”":"Nol: “server DNS mana yang harus saya pakai?”","PPP IPCP Configure-Ack · 12 bytes":"PPP IPCP Configure-Ack · 12 byte","PPP IPCP Configure-Nak · 24 bytes":"PPP IPCP Configure-Nak · 24 byte","Not these values: here are ones that would be accepted.":"Bukan nilai ini: inilah nilai yang akan diterima.","The address for the router.":"Alamat untuk router.","PPP IPCP Configure-Ack · 24 bytes":"PPP IPCP Configure-Ack · 24 byte","PPP · 2 bytes":"PPP · 2 byte","An IPv4 packet follows.":"Paket IPv4 menyusul.","Lowered from 1460 by the router, so packets back fit in the 1,492 bytes PPPoE leaves.":"Diturunkan dari 1460 oleh router, agar paket balasan muat dalam 1.492 byte yang disisakan PPPoE.","Internet phone calls":"Telepon lewat internet","IP camera streams":"Siaran kamera IP","Live streaming upload":"Unggah siaran langsung","Multicast and TV channels":"Multicast dan saluran TV","IP Camera":"Kamera IP","TV Box":"TV Box",Camera:"Kamera","Internet Phone Calls":"Telepon Lewat Internet","Voice (RTP)":"Suara (RTP)","SIP Server":"Server SIP","Bob’s Router":"Router Bob","Session Initiation Protocol":"Session Initiation Protocol","SIP sets up phone calls over the internet: office desk phones, phone apps and the providers behind them. A phone signs in with its provider’s SIP server. To call someone it sends an INVITE; the other phone rings and answers, and the two agree on how to send the voice, which then flows as RTP. The messages are plain text, a lot like HTTP.":"SIP menyiapkan panggilan telepon lewat internet: telepon meja kantor, aplikasi telepon, dan penyedia di baliknya. Telepon masuk ke server SIP penyedianya. Untuk menelepon seseorang, ia mengirim INVITE; telepon lain berdering dan diangkat, lalu keduanya sepakat cara mengirim suara, yang kemudian mengalir sebagai RTP. Pesannya berupa teks biasa, sangat mirip HTTP.","UDP or TCP 5060":"UDP atau TCP 5060","Call setup":"Menyiapkan panggilan",Voice:"Suara","RTP, described by SDP":"RTP, dijelaskan oleh SDP","Codec here":"Codec di sini","Call ended":"Panggilan selesai","Signed in, rang, talked, hung up":"Masuk, berdering, bicara, ditutup","Alice’s phone signed in with a password it never sent, invited Bob’s phone through the SIP server, heard it ring, and talked over RTP until Bob hung up with a BYE. SIP only set the call up and took it down; the voice travelled as packets of its own. Press REPLAY to watch it again.":"Telepon Alice masuk dengan kata sandi yang tidak pernah dikirimnya, mengundang telepon Bob melalui server SIP, mendengarnya berdering, dan bicara lewat RTP sampai Bob menutup dengan BYE. SIP hanya menyiapkan dan mengakhiri panggilan; suaranya berjalan dalam paket tersendiri. Tekan ULANGI untuk menontonnya lagi.","50 packets a second each way":"50 paket per detik tiap arah",Through:"Melalui","The provider’s server":"Server penyedia","No (SIPS and SRTP add it)":"Tidak (SIPS dan SRTP menambahkannya)","Sign In":"Masuk","The phone tells the server where it is":"Telepon memberi tahu server di mana ia berada","Alice’s phone, an app on her laptop, registers with her provider’s SIP server: alice@example.net can be reached here. The server answers 401 with a challenge, so the phone asks again with a hash made from the challenge and its password. 200 OK: registered for an hour.":"Telepon Alice, aplikasi di laptopnya, mendaftar ke server SIP penyedianya: alice@example.net bisa dihubungi di sini. Server menjawab 401 dengan sebuah tantangan, jadi telepon meminta lagi dengan hash dari tantangan dan kata sandinya. 200 OK: terdaftar selama satu jam.","Good for":"Berlaku","3600 s, then again":"3600 s, lalu lagi","is here":"ada di sini","with a challenge":"dengan tantangan","again, with a hash":"lagi, dengan hash",registered:"terdaftar","Call Bob":"Menelepon Bob","An INVITE, passed on by the server":"INVITE, diteruskan oleh server","Alice calls bob@example.net. Her INVITE carries SDP: G.711 audio, sent to her phone. The server answers 100 Trying, finds where Bob’s phone registered and passes the INVITE on, with its own Via and Record-Route and its own address in the SDP: the voice will go through it.":"Alice menelepon bob@example.net. INVITE-nya membawa SDP: audio G.711, dikirim ke teleponnya. Server menjawab 100 Trying, mencari tempat telepon Bob terdaftar, lalu meneruskan INVITE dengan Via dan Record-Route miliknya serta alamatnya sendiri di SDP: suara akan lewat server itu.","Offer (SDP)":"Tawaran (SDP)","G.711, port 49170":"G.711, port 49170","Stops Alice resending":"Alice berhenti mengirim ulang","call bob@example.net":"telepon bob@example.net","SDP: G.711 audio":"SDP: audio G.711","passed on to Bob":"diteruskan ke Bob","voice via the server":"suara lewat server",Ringing:"Berdering","The answer retraces the route":"Jawaban menelusuri rute kembali","Bob’s phone starts ringing and says so: 180 Ringing. Responses follow the Via headers back the way the request came, so it goes to the server, which removes its own Via and passes it on to Alice. Her phone plays the ringing tone.":"Telepon Bob mulai berdering dan memberitahukannya: 180 Ringing. Respons mengikuti header Via kembali lewat jalan yang dilalui permintaan, jadi ia menuju server, yang menghapus Via miliknya lalu meneruskannya ke Alice. Telepon Alice memutar nada sambung.","Route back":"Rute kembali","The Via headers, in reverse":"Header Via, dibalik","Alice hears":"Yang didengar Alice","The ringing tone":"Nada sambung","Bob’s phone rings":"telepon Bob berdering","to Alice":"ke Alice",Answered:"Diangkat","200 OK, then ACK":"200 OK, lalu ACK","Bob picks up. His 200 OK carries his SDP answer: G.711, sent to his phone. The server swaps in its own address again before passing it to Alice. Her phone confirms with an ACK, which the server passes to Bob. The call is set up.":"Bob mengangkat. 200 OK-nya membawa jawaban SDP: G.711, dikirim ke teleponnya. Server kembali memasang alamatnya sendiri sebelum meneruskannya ke Alice. Telepon Alice mengonfirmasi dengan ACK, yang diteruskan server ke Bob. Panggilan tersambung.","Answer (SDP)":"Jawaban (SDP)","G.711, port 49172":"G.711, port 49172","Confirmed by":"Dikonfirmasi dengan","Voice goes to":"Suara dikirim ke","The server, ports 40000, 40002":"Server, port 40000, 40002","Bob answers":"Bob mengangkat",answered:"diangkat",Talking:"Berbicara","Voice flows as RTP":"Suara mengalir sebagai RTP","Now the voice: every 20 ms each phone sends an RTP packet with 160 bytes of G.711 sound, a sequence number and a timestamp, over UDP. They go to the server, which passes them on to the other phone. SIP stays quiet while they talk.":"Sekarang suaranya: setiap 20 ms tiap telepon mengirim paket RTP berisi 160 byte suara G.711, nomor urut, dan stempel waktu, lewat UDP. Paket itu menuju server, yang meneruskannya ke telepon lain. SIP diam selama mereka bicara.",Every:"Setiap","20 ms, 160 bytes of sound":"20 ms, 160 byte suara","Carried by":"Dibawa oleh","RTP over UDP":"RTP lewat UDP","SIP meanwhile":"SIP sementara itu","Nothing to say":"Tidak ada yang dikatakan",VOICE:"SUARA","20 ms of Alice":"20 ms dari Alice","20 ms of Bob":"20 ms dari Bob","Hang Up":"Menutup","BYE, and 200 OK":"BYE, lalu 200 OK","Bob hangs up: his phone sends BYE, routed through the server as the Record-Route asked, and Alice’s phone answers 200 OK. Both stop sending voice. The call took four kinds of request; the voice itself was never part of SIP.":"Bob menutup: teleponnya mengirim BYE, dirutekan lewat server sesuai Record-Route, dan telepon Alice menjawab 200 OK. Keduanya berhenti mengirim suara. Panggilan ini memakai empat jenis permintaan; suaranya sendiri tidak pernah menjadi bagian dari SIP.","No more RTP":"RTP berhenti","Bob hangs up":"Bob menutup","1, 0 (PCMU: G.711 μ-law, the classic phone codec)":"1, 0 (PCMU: G.711 μ-law, codec telepon klasik)","Audio clock at 8,000 per second: +160 per 20 ms of sound.":"Jam audio 8000 per detik: +160 per 20 ms suara.","160 bytes of G.711 audio (20 ms, one byte per sample)":"160 byte audio G.711 (20 ms, satu byte per sampel)","IP Camera Streams":"Siaran Kamera IP","Video (RTP)":"Video (RTP)","Real Time Streaming Protocol":"Real Time Streaming Protocol","RTSP is how video players, recorders and security apps get live video from IP cameras. It works like a remote control: the player asks what the camera offers, sets up a stream, and says PLAY and later TEARDOWN, in text messages much like HTTP. The video itself doesn’t travel in RTSP: it flows separately as RTP, here over UDP.":"RTSP adalah cara pemutar video, perekam, dan aplikasi keamanan mengambil video langsung dari kamera IP. Cara kerjanya seperti remote: pemutar menanyakan apa yang ditawarkan kamera, menyiapkan stream, lalu berkata PLAY dan kemudian TEARDOWN, dalam pesan teks yang mirip HTTP. Videonya sendiri tidak lewat RTSP: ia mengalir terpisah sebagai RTP, di sini lewat UDP.",Controls:"Perintah",Watched:"Ditonton","Described, set up, played, stopped":"Dijelaskan, disiapkan, diputar, dihentikan","VLC asked the camera what it had, logged in with a hash of its password, set up one video track and pressed PLAY. The video came as RTP packets on ports of its own, a key frame in three pieces, until TEARDOWN ended the session. Press REPLAY to watch it again.":"VLC menanyakan apa yang dimiliki kamera, masuk dengan hash kata sandinya, menyiapkan satu trek video, dan menekan PLAY. Video datang sebagai paket RTP di port tersendiri, satu frame kunci dalam tiga bagian, sampai TEARDOWN mengakhiri sesi. Tekan ULANGI untuk menontonnya lagi.","6 on one TCP connection":"6 dalam satu koneksi TCP","Key frame":"Frame kunci","Split into 3 packets":"Dipecah jadi 3 paket","1185d200, 60 s timeout":"1185d200, habis dalam 60 s","What Can You Do?":"Apa yang Bisa Kamu Lakukan?","OPTIONS over a TCP connection":"OPTIONS lewat koneksi TCP","VLC opens rtsp://192.168.1.64/stream1. It connects to the camera on TCP port 554 and starts with OPTIONS: which commands do you support? The camera lists them. As in HTTP, every request and reply is text; a CSeq header numbers them.":"VLC membuka rtsp://192.168.1.64/stream1. Ia tersambung ke kamera di port TCP 554 dan mulai dengan OPTIONS: perintah apa saja yang kamu dukung? Kamera menyebutkannya. Seperti HTTP, setiap permintaan dan balasan berupa teks; header CSeq memberinya nomor.","Numbered by":"Dinomori oleh","what can you do?":"apa yang bisa kamu lakukan?","Describe the Stream":"Menjelaskan Stream","SDP says what the video is":"SDP menjelaskan videonya","DESCRIBE asks for the stream’s description. The camera wants a login first: 401, with a digest challenge. VLC asks again with a hash of the password, and the reply carries SDP: one H.264 video track, RTP payload type 96, with a 90 kHz clock.":"DESCRIBE meminta penjelasan stream. Kamera meminta login dulu: 401, dengan tantangan digest. VLC meminta lagi dengan hash kata sandi, dan balasannya membawa SDP: satu trek video H.264, jenis payload RTP 96, dengan jam 90 kHz.","Digest: a hash":"Digest: sebuah hash","H.264, payload type 96":"H.264, jenis payload 96",Track:"Trek","describe stream1":"jelaskan stream1","log in first":"login dulu","SDP: H.264 video":"SDP: video H.264","track 1":"trek 1","Set Up":"Menyiapkan","Agree on ports for the video":"Sepakat soal port untuk video","SETUP for trackID=1 says how to deliver it: RTP over UDP, to the laptop’s ports 50000 (video) and 50001 (RTCP reports). The camera agrees, picks its own ports, 6970 and 6971, and opens a session, 1185d200, that every later request names.":"SETUP untuk trackID=1 menyebut cara mengirimnya: RTP lewat UDP, ke port 50000 (video) dan 50001 (laporan RTCP) di laptop. Kamera setuju, memilih port sendiri, 6970 dan 6971, dan membuka sesi 1185d200 yang disebut oleh setiap permintaan berikutnya.","Laptop ports":"Port laptop","track 1, RTP over UDP":"trek 1, RTP lewat UDP","to ports 50000-50001":"ke port 50000-50001","session 1185d200":"sesi 1185d200","from ports 6970-6971":"dari port 6970-6971",Play:"Putar","The remote control’s PLAY button":"Tombol PLAY di remote","PLAY starts the stream from now (npt=0.000-). The reply tells VLC which RTP sequence number and timestamp come first, so it can line the video up. From here on, the video doesn’t travel in RTSP at all.":"PLAY memulai stream mulai sekarang (npt=0.000-). Balasannya memberi tahu VLC nomor urut dan stempel waktu RTP mana yang datang pertama, supaya videonya bisa diurutkan. Mulai dari sini, video sama sekali tidak lewat RTSP.",Range:"Rentang","From now":"Mulai sekarang","First packet":"Paket pertama","Video arrives":"Video datang","On the UDP ports":"Di port UDP","play from now":"putar mulai sekarang",playing:"diputar","Video Arrives":"Video Datang","A key frame in RTP packets":"Frame kunci dalam paket RTP","The camera sends a key frame, a whole picture, in three RTP packets: H.264 fragments marked first, middle and last, with the marker bit on the last. All three carry the same 90 kHz timestamp. Smaller frames holding only the changes follow, 25 a second.":"Kamera mengirim frame kunci, satu gambar utuh, dalam tiga paket RTP: potongan H.264 bertanda pertama, tengah, dan terakhir, dengan bit penanda di yang terakhir. Ketiganya membawa stempel waktu 90 kHz yang sama. Setelahnya menyusul frame yang lebih kecil berisi perubahannya saja, 25 per detik.",Packets:"Paket","3 for one key frame":"3 untuk satu frame kunci","Same for the whole frame":"Sama untuk seluruh frame",Frames:"Frame","25 a second":"25 per detik","a key frame in 3 packets":"frame kunci dalam 3 paket",Stop:"Berhenti","TEARDOWN ends the session":"TEARDOWN mengakhiri sesi","When the viewer closes the stream, VLC sends TEARDOWN with the session ID. The camera stops sending video and confirms. Had VLC simply vanished, the camera would stop anyway once 60 seconds passed without a word from it.":"Saat penonton menutup stream, VLC mengirim TEARDOWN dengan ID sesi. Kamera berhenti mengirim video dan mengonfirmasi. Seandainya VLC hilang begitu saja, kamera tetap berhenti setelah 60 detik tanpa kabar darinya.",Ended:"Selesai",Otherwise:"Kalau tidak","Timeout after 60 s":"Habis setelah 60 s","stop session 1185d200":"hentikan sesi 1185d200",stopped:"berhenti","The camera. It is on the same network, so the frame goes straight to it, not through the router.":"Kamera. Ia ada di jaringan yang sama, jadi frame langsung menuju ke sana, tidak lewat router.","The camera’s network port.":"Port jaringan kamera.","RTP + video":"RTP + video","0, 96 (H.264, as the camera’s description said)":"0, 96 (H.264, sesuai penjelasan kamera)","Marker clear: more of this frame follows.":"Penanda nol: masih ada lanjutan frame ini.","Video clock at 90,000 per second; every packet of one frame has the same value.":"Jam video 90.000 per detik; setiap paket dari satu frame memakai nilai yang sama.","Identifies this video stream.":"Menandai stream video ini.","FU indicator":"Indikator FU","0x7c (fragment of a frame)":"0x7c (potongan frame)","Fragmentation unit: one piece of a frame too big for one packet.":"Unit fragmentasi: satu potongan dari frame yang terlalu besar untuk satu paket.","FU header":"Header FU","0x85 (first piece of a key frame)":"0x85 (potongan pertama frame kunci)","Type 5: a key frame (IDR), a whole picture the decoder can start from.":"Jenis 5: frame kunci (IDR), gambar utuh tempat dekoder bisa mulai.","1398 bytes of the key frame":"1398 byte dari frame kunci","0x05 (middle piece of a key frame)":"0x05 (potongan tengah frame kunci)","1, 96 (H.264, as the camera’s description said)":"1, 96 (H.264, sesuai penjelasan kamera)","Marker set: the last packet of a frame.":"Penanda aktif: paket terakhir dari satu frame.","0x45 (last piece of a key frame)":"0x45 (potongan terakhir frame kunci)","900 bytes of the key frame":"900 byte dari frame kunci","Multicast TV":"TV Multicast","Joins and leaves":"Bergabung dan keluar","Channel 1":"Saluran 1","TV channels":"Saluran TV","Internet Group Management Protocol":"Internet Group Management Protocol","Multicast sends one stream to a group address, and the network copies it only where it’s wanted: it’s how internet providers deliver live TV channels. IGMP is how a device tells its router which groups it wants. Switches listen in (IGMP snooping), so each stream reaches only the ports that asked for it.":"Multicast mengirim satu stream ke alamat grup, dan jaringan menyalinnya hanya ke tempat yang menginginkannya: begitulah penyedia internet menyalurkan saluran TV langsung. IGMP adalah cara perangkat memberi tahu router grup mana yang diinginkannya. Switch ikut mendengarkan (IGMP snooping), jadi setiap stream hanya sampai ke port yang memintanya.","IP protocol 2":"Protokol IP 2",Groups:"Grup","Version here":"Versi di sini","Tuned In":"Tersambung","Joined, copied, checked, left":"Bergabung, disalin, dicek, keluar","The TV box and then the laptop joined channel 1 with IGMP reports. The router joined once for the whole home, and the switch, listening in, copied the channel only to the ports that wanted it. Queries kept it flowing, and when the laptop left, the TV box’s answer kept it on. Press REPLAY to watch it again.":"TV box lalu laptop bergabung ke saluran 1 dengan laporan IGMP. Router bergabung sekali saja untuk seluruh rumah, dan switch, yang ikut mendengarkan, menyalin saluran hanya ke port yang menginginkannya. Query membuatnya tetap mengalir, dan saat laptop keluar, jawaban TV box membuatnya tetap menyala. Tekan ULANGI untuk menontonnya lagi.",Upstream:"Ke arah penyedia","One stream for the home":"Satu stream untuk seluruh rumah","Copies to ports that joined":"Salinan ke port yang bergabung","Every 125 s":"Setiap 125 s","Pick a Channel":"Memilih Saluran","The TV box joins a group":"TV box bergabung ke grup","The viewer picks channel 1. Each channel is a multicast group, here 233.252.0.1, and the TV box sends an IGMP Membership Report to that address: I want this group. The switch listens in (IGMP snooping), notes port 2, and passes the report to the router alone.":"Penonton memilih saluran 1. Setiap saluran adalah grup multicast, di sini 233.252.0.1, dan TV box mengirim IGMP Membership Report ke alamat itu: aku mau grup ini. Switch ikut mendengarkan (IGMP snooping), mencatat port 2, dan meneruskan laporan itu hanya ke router.","Switch notes":"Switch mencatat","Port 2 wants it":"Port 2 menginginkannya","233.252.0.1, please":"233.252.0.1, tolong","to the router port only":"hanya ke port router","Ask the Provider":"Meminta ke Penyedia","The router joins for the home":"Router bergabung untuk seisi rumah","The router is an IGMP proxy: it joins the group on its internet side with a report of its own, from its public address, and the provider’s network starts sending channel 1 down the line. However many screens at home tune in, the router joins only once.":"Router adalah proxy IGMP: ia bergabung ke grup di sisi internet dengan laporannya sendiri, dari alamat publiknya, dan jaringan penyedia mulai mengirim saluran 1 lewat jalur itu. Berapa pun layar di rumah yang menyetel, router hanya bergabung sekali.","Router role":"Peran router","IGMP proxy":"Proxy IGMP",Joins:"Bergabung","Once for the whole home":"Sekali untuk seluruh rumah","for the whole home":"untuk seluruh rumah","The Channel Flows":"Saluran Mengalir","Sent only where it was asked for":"Dikirim hanya ke yang meminta","The provider’s TV server sends channel 1 to 233.252.0.1: UDP datagrams holding seven 188-byte MPEG-TS packets of video and audio each. The router passes them in, and the switch sends them out of port 2 alone: only the TV box joined, so the laptop gets none.":"Server TV penyedia mengirim saluran 1 ke 233.252.0.1: datagram UDP yang masing-masing berisi tujuh paket MPEG-TS 188 byte berisi video dan audio. Router meneruskannya ke dalam, dan switch hanya mengeluarkannya lewat port 2: hanya TV box yang bergabung, jadi laptop tidak menerima satu pun.",Datagram:"Datagram","UDP, 1,316 bytes of TV":"UDP, 1.316 byte TV",Holds:"Berisi","7 MPEG-TS packets":"7 paket MPEG-TS","CHANNEL 1":"SALURAN 1","MPEG-TS over UDP":"MPEG-TS lewat UDP","passed into the home":"diteruskan ke rumah","port 2 only":"hanya port 2","A Second Screen":"Layar Kedua","The laptop tunes in too":"Laptop ikut menyetel","The laptop opens channel 1 in VLC and sends its own report. The switch adds port 1 and now makes two copies of every datagram. The router already gets the channel, so it asks the provider for nothing: one stream still comes down the line.":"Laptop membuka saluran 1 di VLC dan mengirim laporannya sendiri. Switch menambahkan port 1 dan kini membuat dua salinan setiap datagram. Router sudah menerima saluran itu, jadi ia tidak meminta apa pun ke penyedia: lewat jalur tetap datang satu stream saja.","Switch sends to":"Switch mengirim ke","Ports 1 and 2":"Port 1 dan 2","Still one stream":"Tetap satu stream","Router asks":"Router meminta","Nothing new":"Tidak ada yang baru","the same one stream":"satu stream yang sama","copied to ports 1 and 2":"disalin ke port 1 dan 2","Still Watching?":"Masih Menonton?","The router checks regularly":"Router memeriksa secara berkala","Every 125 seconds the router sends a General Query to 224.0.0.1, every device: which groups do you still want? The switch passes it to every port. Each member answers at a random moment within 10 seconds, so the router and the switch keep the channel coming.":"Setiap 125 detik router mengirim General Query ke 224.0.0.1, semua perangkat: grup mana yang masih kalian mau? Switch meneruskannya ke semua port. Setiap anggota menjawab pada saat acak dalam 10 detik, jadi router dan switch tetap menyalurkan saluran itu.","125 seconds":"125 detik","224.0.0.1, all devices":"224.0.0.1, semua perangkat","Answer within":"Jawab dalam","10 seconds":"10 detik",QUERY:"QUERY","any groups wanted?":"grup mana yang diinginkan?","to every port":"ke semua port",REPORT:"LAPORAN","still watching":"masih menonton",Leave:"Keluar","The laptop stops watching":"Laptop berhenti menonton","Closing VLC sends a Leave Group to 224.0.0.2, all routers. Others may still watch, so the router asks about that group alone and waits 1 second. The TV box answers, so the channel stays; the switch just stops sending it to port 1.":"Menutup VLC mengirim Leave Group ke 224.0.0.2, semua router. Mungkin yang lain masih menonton, jadi router hanya menanyakan grup itu dan menunggu 1 detik. TV box menjawab, jadi saluran tetap ada; switch hanya berhenti mengirimkannya ke port 1.","Leave sent to":"Keluar dikirim ke","224.0.0.2, all routers":"224.0.0.2, semua router","About that group alone":"Hanya tentang grup itu","Stays: the TV box answered":"Tetap: TV box menjawab",LEAVE:"KELUAR","done with 233.252.0.1":"selesai dengan 233.252.0.1","anyone for 233.252.0.1?":"ada yang mau 233.252.0.1?","to the ports that joined":"ke port yang bergabung","Multicast: 01:00:5e, then the last 23 bits of the group address. Network cards listen for the groups their system has joined.":"Multicast: 01:00:5e, lalu 23 bit terakhir dari alamat grup. Kartu jaringan mendengarkan grup yang telah diikuti sistemnya.","The TV box’s network port.":"Port jaringan TV box.","4, 24 bytes":"4, 24 byte","IPv4, with one 4-byte option.":"IPv4, dengan satu opsi 4 byte.","48 (network control), 0":"48 (kontrol jaringan), 0","Marked as network control, so it is sent ahead of ordinary traffic.":"Ditandai sebagai kontrol jaringan, jadi dikirim lebih dulu daripada lalu lintas biasa.","Always 1: IGMP never goes past the first router.":"Selalu 1: IGMP tidak pernah melewati router pertama.","A multicast group address.":"Alamat grup multicast.","Router Alert option":"Opsi Router Alert","Asks every router on the way to look inside, though the packet isn’t addressed to it.":"Meminta setiap router di jalan untuk melihat isinya, meski paket itu tidak ditujukan kepadanya.","This device wants the group’s traffic.":"Perangkat ini menginginkan lalu lintas grup.","Max response time":"Waktu jawab maksimum","Only queries use it.":"Hanya query yang memakainya.","Covers the IGMP message.":"Mencakup pesan IGMP.","Group address":"Alamat grup","The multicast group: one TV channel.":"Grup multicast: satu saluran TV.","Seen arriving on the router’s internet side":"Terlihat tiba di sisi internet router","MPEG-TS · 7 packets":"MPEG-TS · 7 paket","The provider’s router, passing the channel on.":"Router penyedia, meneruskan saluran.","Sync byte":"Byte sinkronisasi","Every transport stream packet starts with 0x47, so the receiver can find where packets begin.":"Setiap paket transport stream diawali 0x47, supaya penerima bisa menemukan awal paket.","Flags, PID":"Flag, PID","0x0100 (PID 256: video)":"0x0100 (PID 256: video)","Which stream the packet belongs to: the channel’s video, its audio, or the tables that list them.":"Stream mana pemilik paket ini: video saluran, audionya, atau tabel yang mendaftar keduanya.","Payload, counter":"Payload, penghitung","0x14 (payload only, counter 4)":"0x14 (hanya payload, penghitung 4)","Counts 0 to 15 for each PID, so a lost packet shows up as a gap.":"Menghitung 0 sampai 15 untuk tiap PID, jadi paket yang hilang tampak sebagai celah.","184 bytes of the channel’s video":"184 byte video saluran","More packets":"Paket lainnya","6 × 188 bytes: video and audio":"6 × 188 byte: video dan audio","Six more transport stream packets, each with its own 4-byte header.":"Enam paket transport stream lagi, masing-masing dengan header 4 byte sendiri.","Seen going into the switch, port 8":"Terlihat masuk ke switch, port 8","The router, passing the channel into the home.":"Router, meneruskan saluran ke dalam rumah.","0x19 (payload only, counter 9)":"0x19 (hanya payload, penghitung 9)","The router asks: which groups does anyone here still want?":"Router bertanya: grup mana yang masih diinginkan seseorang di sini?","Members answer at a random moment within this time, so their answers don’t all arrive at once.":"Anggota menjawab pada saat acak dalam rentang ini, supaya jawaban mereka tidak tiba bersamaan.","Zero in a general query: every group.":"Nol dalam query umum: semua grup.","This device no longer wants the group.":"Perangkat ini tidak lagi menginginkan grup.","The router asks: does anyone still want this group?":"Router bertanya: masih ada yang mau grup ini?","Live Streaming Upload":"Unggah Siaran Langsung","RTMP handshake":"Jabat tangan RTMP","Video and audio":"Video dan audio","Ingest Server":"Server Ingest","Real-Time Messaging Protocol":"Real-Time Messaging Protocol","RTMP is how most streamers send live video to a platform: OBS and other apps push it to an ingest server, which turns it into streams for viewers. Made for Flash, it outlived Flash as the way to upload. Everything shares one TCP connection: commands, audio and video, cut into chunks.":"RTMP adalah cara sebagian besar streamer mengirim video langsung ke platform: OBS dan aplikasi lain mendorongnya ke server ingest, yang mengubahnya menjadi siaran untuk penonton. Dibuat untuk Flash, ia bertahan lebih lama dari Flash sebagai cara mengunggah. Semuanya berbagi satu koneksi TCP: perintah, audio, dan video, dipotong menjadi chunk.","H.264 video, AAC audio":"Video H.264, audio AAC","Encoded in AMF0":"Dikodekan dalam AMF0","Secure version":"Versi aman","RTMPS, over TLS":"RTMPS, lewat TLS","Adobe specification (2012)":"Spesifikasi Adobe (2012)",Live:"Siaran","Connected, published, streamed":"Tersambung, dipublikasikan, disiarkan","OBS shook hands with the ingest server, connected to its live app, got stream 1 and published to it with the stream key. The video and audio then flowed in chunks over the same TCP connection until the streamer stopped. Press REPLAY to watch it again.":"OBS berjabat tangan dengan server ingest, tersambung ke aplikasi live-nya, mendapat stream 1, dan mempublikasikan ke sana dengan kunci stream. Video dan audio lalu mengalir dalam chunk lewat koneksi TCP yang sama sampai streamer berhenti. Tekan ULANGI untuk menontonnya lagi.","One TCP, port 1935":"Satu TCP, port 1935",Stream:"Stream",Chunks:"Chunk","Up to 4,096 bytes":"Sampai 4.096 byte","None: RTMPS adds TLS":"Tidak ada: RTMPS menambahkan TLS","TCP, then RTMP’s own":"TCP, lalu milik RTMP","The streamer clicks Start Streaming. OBS connects to the ingest server on TCP port 1935, then RTMP has its own handshake: version 3 and 1,536 random bytes each way, which each side sends back. It shows both ends speak RTMP; it encrypts nothing.":"Streamer mengklik Mulai Streaming. OBS tersambung ke server ingest di port TCP 1935, lalu RTMP melakukan jabat tangannya sendiri: versi 3 dan 1.536 byte acak ke tiap arah, yang dikirim balik oleh tiap sisi. Ini menunjukkan kedua ujung berbicara RTMP; tidak ada yang dienkripsi.","Each side":"Tiap sisi","Sends 3,073 bytes":"Mengirim 3.073 byte","version 3":"versi 3","1,536 random bytes":"1.536 byte acak","version 3, its own bytes":"versi 3, byte miliknya","and C1 sent back":"dan C1 dikirim balik","S1 sent back":"S1 dikirim balik",Connect:"Menyambung","To the server’s live app":"Ke aplikasi live di server","OBS raises its chunk size to 4,096 bytes and sends connect for the app called live, in AMF0, a compact binary format from Flash. The server sets its own window, bandwidth and chunk size, and answers _result: NetConnection.Connect.Success.":"OBS menaikkan ukuran chunk-nya ke 4.096 byte dan mengirim connect untuk aplikasi bernama live, dalam AMF0, format biner ringkas dari Flash. Server menetapkan window, bandwidth, dan ukuran chunk miliknya, lalu menjawab _result: NetConnection.Connect.Success.",App:"Aplikasi",Encoding:"Pengodean","chunk size 4,096":"ukuran chunk 4.096","window, bandwidth, chunks":"window, bandwidth, chunk","Make a Stream":"Membuat Stream","createStream returns stream 1":"createStream memberi stream 1","Every message names a message stream; 0 is the connection itself. OBS releases and announces its stream key, then asks createStream for a stream to send on, all three commands in one packet. The server answers with stream ID 1.":"Setiap pesan menyebut satu message stream; 0 adalah koneksi itu sendiri. OBS melepas dan mengumumkan kunci stream-nya, lalu meminta createStream untuk stream tempat mengirim, ketiga perintah dalam satu paket. Server menjawab dengan stream ID 1.","3 in one packet":"3 dalam satu paket",Gets:"Mendapat","Stream ID 1":"Stream ID 1","stream ID 1":"stream ID 1",Publish:"Publikasi","The stream key goes live":"Kunci stream mulai siaran","publish names the stream key, the secret that says whose channel this is. RTMP has no encryption, so the key crosses in plain text; platforms prefer RTMPS, the same over TLS. The server checks the key and answers NetStream.Publish.Start.":"publish menyebut kunci stream, rahasia yang menyatakan saluran milik siapa ini. RTMP tidak punya enkripsi, jadi kunci lewat sebagai teks biasa; platform lebih suka RTMPS, yang sama tetapi lewat TLS. Server memeriksa kunci dan menjawab NetStream.Publish.Start.","The stream key":"Kunci stream","None (RTMPS adds TLS)":"Tidak ada (RTMPS menambahkan TLS)","on stream 1":"di stream 1","stream key, live":"kunci stream, live","Video and Sound":"Video dan Suara","Metadata, settings, then frames":"Metadata, pengaturan, lalu frame","OBS describes the stream: 1920×1080 at 30 frames a second, H.264 video, AAC audio. It sends the decoders’ settings, then a key frame, about 30 KB cut into 4,096-byte chunks. Frames follow non-stop, on the same TCP connection.":"OBS menjelaskan siarannya: 1920×1080 dengan 30 frame per detik, video H.264, audio AAC. Ia mengirim pengaturan dekoder, lalu sebuah frame kunci sekitar 30 KB yang dipotong menjadi chunk 4.096 byte. Frame terus menyusul tanpa henti lewat koneksi TCP yang sama.","AAC, 48 kHz stereo":"AAC, 48 kHz stereo","30 KB in 8 chunks":"30 KB dalam 8 chunk",METADATA:"METADATA","H.264 + AAC settings":"pengaturan H.264 + AAC","KEY FRAME":"FRAME KUNCI","8 chunks":"8 chunk","Stop Streaming":"Hentikan Streaming","FCUnpublish and deleteStream":"FCUnpublish dan deleteStream","When the streamer clicks Stop Streaming, OBS sends FCUnpublish and deleteStream for stream 1. The server answers NetStream.Unpublish.Success and ends the broadcast for viewers. Then OBS closes the TCP connection.":"Saat streamer mengklik Hentikan Streaming, OBS mengirim FCUnpublish dan deleteStream untuk stream 1. Server menjawab NetStream.Unpublish.Success dan mengakhiri siaran bagi penonton. Lalu OBS menutup koneksi TCP.","C0: version":"C0: versi","RTMP version 3, the only one in use.":"RTMP versi 3, satu-satunya yang dipakai.",Time:"Waktu","A timestamp; zero is allowed.":"Stempel waktu; nol diperbolehkan.",Zero:"Nol","Random data":"Data acak","Random bytes the server must send back.":"Byte acak yang harus dikirim balik oleh server.","S0: version":"S0: versi","Random bytes the client must send back.":"Byte acak yang harus dikirim balik oleh klien.","1,536 bytes: C1 back":"1.536 byte: C1 dikirim balik","The timestamp from the block it echoes.":"Stempel waktu dari blok yang dipantulkannya.","Time read":"Waktu dibaca","C1’s random bytes, sent back unchanged.":"Byte acak dari C1, dikirim balik tanpa diubah.","1,536 bytes: S1 back":"1.536 byte: S1 dikirim balik","S1’s random bytes, sent back unchanged.":"Byte acak dari S1, dikirim balik tanpa diubah.","RTMP · 2 messages":"RTMP · 2 pesan","First message":"Pesan pertama","Chunk header":"Header chunk","type 0, chunk stream 2":"jenis 0, chunk stream 2","A full header follows: this chunk starts a message.":"Header lengkap menyusul: chunk ini memulai sebuah pesan.","Message stream":"Message stream","Stream 0: the connection itself. (This number alone is little-endian.)":"Stream 0: koneksi itu sendiri. (Hanya angka ini yang little-endian.)","Chunk size":"Ukuran chunk","From now on this side cuts messages into chunks of up to this size (128 until it says otherwise).":"Mulai sekarang sisi ini memotong pesan menjadi chunk sampai ukuran ini (128 sampai ia menyatakan lain).","Second message":"Pesan kedua","type 0, chunk stream 3":"jenis 0, chunk stream 3","Matches a reply to its request.":"Mencocokkan balasan dengan permintaannya.","Command object":"Objek perintah","object, 5 properties":"objek, 5 properti","Which app on the server, and the address OBS was given.":"Aplikasi mana di server, dan alamat yang diberikan ke OBS.","End of object":"Akhir objek","RTMP · 4 messages":"RTMP · 4 pesan","The other side should hear back after every this many bytes it sends.":"Sisi lain harus mendapat kabar setiap kali ia mengirim sebanyak ini byte.","Bandwidth, limit":"Bandwidth, batas","5,000,000 bytes, dynamic":"5.000.000 byte, dinamis","How much the sender may have unacknowledged at once.":"Berapa banyak yang boleh belum dikonfirmasi oleh pengirim sekaligus.","Third message":"Pesan ketiga","Fourth message":"Pesan keempat",Properties:"Properti","object, 2 properties":"objek, 2 properti",Information:"Informasi","object, 4 properties":"objek, 4 properti","RTMP · 3 messages":"RTMP · 3 pesan","Nothing: AMF0 null.":"Kosong: null AMF0.","Stream key":"Kunci stream","Which channel this is. It works like a password, and here it travels unencrypted.":"Saluran mana ini. Fungsinya seperti kata sandi, dan di sini ia lewat tanpa enkripsi.","Stream ID":"Stream ID","The new stream: video and audio will go on it.":"Stream baru: video dan audio akan lewat di sini.","type 0, chunk stream 4":"jenis 0, chunk stream 4","Stream 1, the one createStream made.":"Stream 1, yang dibuat createStream.","Publishing type":"Jenis publikasi","Live: not recorded by this request.":"Live: permintaan ini tidak merekam.","type 0, chunk stream 5":"jenis 0, chunk stream 5","object, 3 properties":"objek, 3 properti",Handler:"Penangan",Event:"Event",Metadata:"Metadata","array of 14":"array berisi 14","Codec IDs as in Flash video files: 7 is H.264, 10 is AAC.":"ID codec seperti di file video Flash: 7 adalah H.264, 10 adalah AAC.","type 0, chunk stream 6":"jenis 0, chunk stream 6","Frame, codec":"Frame, codec","0x17 (key frame, H.264)":"0x17 (frame kunci, H.264)","AVC packet type":"Jenis paket AVC","0 (decoder settings)":"0 (pengaturan dekoder)","The sequence header: the settings a decoder needs before the first frame.":"Header urutan: pengaturan yang dibutuhkan dekoder sebelum frame pertama.","Composition time":"Waktu komposisi","The H.264 profile, level and parameter sets.":"Profil, level, dan set parameter H.264.","AAC; the other bits are fixed for AAC.":"AAC; bit lainnya tetap untuk AAC.","AAC packet type":"Jenis paket AAC","Sample rate and channels, for the decoder.":"Laju sampel dan kanal, untuk dekoder.","1 (video)":"1 (video)","Compressed picture data.":"Data gambar terkompresi.","The key frame: a whole picture. Every 4,096 bytes a 1-byte chunk header continues it.":"Frame kunci: satu gambar utuh. Setiap 4.096 byte, header chunk 1 byte melanjutkannya."},h={strings:{...d,...o,...r},patterns:[[/^([\d,]+) bytes$/,"$1 byte"],[/^(Ethernet II|IPv4|IPv6|UDP|TCP|802\.11|LLC\/SNAP|EAPOL) · (\d+) bytes$/,"$1 · $2 byte"],[/^(Application Data|Handshake|Change Cipher Spec), ([\d,]+) bytes?$/,"$1, $2 byte"],[/^([\d,]+) bytes: report\.pdf, bytes (.+)$/,"$1 byte: report.pdf, byte $2"],[/^(.+) h later$/,"$1 jam kemudian"],[/^(.+) min later$/,"$1 menit kemudian"],[/^(.+) s later$/,"$1 detik kemudian"],[/^(\S+) \(relative\)$/,"$1 (relatif)"],[/^(\d+) \(ephemeral\)$/,"$1 (efemeral)"],[/^(\d+) TCP segments$/,"$1 segmen TCP"],[/^(\d+) segments$/,"$1 segmen"],[/^(.*), (\d+) segments$/,"$1, $2 segmen"],[/^TLS 1\.3 · (\d+) records? · bytes (.+) of (.+)$/,"TLS 1.3 · $1 record · byte $2 dari $3"],[/^TLS 1\.3 · (\d+) records?$/,"TLS 1.3 · $1 record"],[/^Ethernet padding · (\d+) bytes$/,"Padding Ethernet · $1 byte"],[/^(\d+) zero bytes, up to the 300-byte minimum$/,"$1 byte nol, hingga batas minimum 300 byte"],[/^(\d+) zero bytes$/,"$1 byte nol"],[/^(\d+) random bytes$/,"$1 byte acak"],[/^Seen as it leaves (.+)$/,"Terlihat saat keluar dari $1"],[/^Option (\d+)$/,"Opsi $1"],[/^value (\d+), echo (\d+)$/,"nilai $1, echo $2"],[/^20 bytes, plus (\d+) of options\.$/,"20 byte, ditambah $1 byte opsi."],[/^Windows starts at (\d+)\. Set to (\d+) on purpose here\.$/,"Windows mulai dari $1. Di sini sengaja diatur ke $2."],[/^Started at (\d+); (\d+) routers? on the way each took 1\.$/,(t,a,e)=>e==="1"?`Dimulai dari ${a}; router di jalur menguranginya 1.`:`Dimulai dari ${a}; masing-masing dari ${e} router di jalur menguranginya 1.`],[/^all (\d+) bytes of it$/,"seluruh $1 byte-nya"],[/^The packet that caused this, as the reporting device received it \(TTL (\d+)\), so the sender can tell which packet it was\.$/,"Paket penyebabnya, seperti yang diterima perangkat pelapor (TTL $1), agar pengirim tahu paket mana itu."],[/^Port (\d+), TLS from the start$/,"Port $1, TLS sejak awal"],[/^(\d+), TLS from the start$/,"$1, TLS sejak awal"],[/^type 79, (\d+) bytes$/,"tipe 79, $1 byte"],[/^(\d+) of (\d+) bytes$/,"$1 dari $2 byte"],[/^(\d+) more bytes$/,"$1 byte lagi"],[/^offset (\d+), (\d+) bytes$/,"offset $1, $2 byte"],[/^offset 0, (\d+) bytes \(all of it\)$/,"offset 0, $1 byte (seluruhnya)"],[/^record, (\d+) bytes$/,"record, $1 byte"],[/^EAPOL-Key · message (\d) of 4$/,"EAPOL-Key · pesan $1 dari 4"],[/^((?:SMB2|IKEv2) · )?([A-Z_]+) (request|response)$/,(t,a,e,i)=>{const n=i==="request"?"permintaan":"respons";return a?`${a}${n} ${e}`:`${n[0].toUpperCase()}${n.slice(1)} ${e}`}],[/^(\d+) registers$/,"$1 register"],[/^id 1: −(\d+) dBov, voice$/,"id 1: −$1 dBov, suara"],[/^"(.*)" \(([\d,]+) bytes\)$/,'"$1" ($2 byte)'],[/^(masked|not masked), (\d+) bytes?$/,(t,a,e)=>`${a==="masked"?"di-mask":"tidak di-mask"}, ${e} byte`],[/^(\d+) \(disguised\)$/,"$1 (disamarkan)"],[/^(\d+) \((KE|Nonce|Notify|IDi|IDr)\), (\d+) bytes$/,"$1 ($2), $3 byte"],[/^0 \(none\), (\d+) bytes$/,"0 (tidak ada), $1 byte"],[/^Microsoft \(311\), type (\d+)$/,"Microsoft (311), tipe $1"],[/^(\d+) \(register (\d+)\)$/,"$1 (register $2)"],[/^yes, AS (\d+)$/,"ya, AS $1"],[/^id 2, (\d+) bytes$/,"id 2, $1 byte"],[/^(\d), (\d+) \((Opus|VP8), as agreed in the SDP\)$/,"$1, $2 ($3, sesuai kesepakatan di SDP)"]],post:s};export{h as default};
